/*
 * テキストの本文(中学英語の文法)。書式は lessons_1.js と同じ。
 * 【 】でかこんだ語は太字で表示する。
 */
window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  // ===== 中1の文法 =====
  L.e_m1 = {
    goal: 'be動詞(am・is・are)を主語に合わせて使い分け、be動詞の肯定文・否定文・疑問文を正しく作れるようになる。',
    intro: 'be動詞は、英語でいちばん最初に出会う動詞です。意味はおもに「【〜です】(イコール)」と「【〜にいる・ある】」の2つ。たとえば I am Ken.(私はケンです。)は「私=ケン」という関係を表しています。主語によって am・is・are と形が変わるので、まずはその組み合わせを覚えましょう。',
    pre: '英語の文は、ふつう【主語(〜は・〜が)】で始まり、そのすぐ後ろに【動詞(〜する・〜です)】がきます。日本語の「私は ケンです」は、英語では I(私は)→ am(です)→ Ken(ケン)の順になります。\n主語によく使うことばを確認しましょう。I(私)、you(あなた・あなたたち)、he(彼)、she(彼女)、it(それ)、we(私たち)、they(彼ら・彼女ら・それら)。これらは名詞のかわりに使うので【代名詞】といいます。\n1人・1つのことを【単数】、2人・2つ以上のことを【複数】といいます。a dog(1ぴきの犬)は単数、dogs(2ひき以上の犬)は複数です。\n英語の文は、最初の文字を大文字で書き、最後にピリオド(.)をつけます。疑問文(質問の文)の最後にはクエスチョンマーク(?)をつけます。I(私)は文のどこにあっても大文字です。',
    secs: [
      { h: '英語の文には必ず動詞がいる', t: '日本語では「私は学生。」のように、動詞がなくても文になります。でも英語では、【1つの文に必ず1つ動詞が必要】です。\nそこで、「私」と「学生」をイコールでつなぐ役目の動詞が必要になります。それが【be動詞】です。\nI am a student.(私は生徒です。)の am は、「I = a student」の「=」の記号のような働きをしています。\nbe動詞という名前は、もとの形(原形)が be であることから来ています。現在の文では am・is・are の3つの形で使います。\nなお、a student の a は「1人の・1つの」という意味で、数えられるものが1つのときに名詞の前につけます。',
        key: '英語の文には動詞が必ず1つ必要。「AはBです」の「です」にあたるつなぎ役が be動詞。' },
      { h: '主語でかわる am・is・are', t: 'be動詞は、主語に合わせて形を使い分けます。組み合わせは3つだけです。\n【I → am】 I am a student.(私は生徒です。)\n【you・複数 → are】 You are kind.(あなたは親切です。)/We are friends.(私たちは友だちです。)\n【he・she・it など、自分と相手以外の1人・1つ → is】 She is my sister.(彼女は私の姉[妹]です。)/This is a pen.(これはペンです。)\nKen and I(ケンと私)のように2人以上なら複数なので are です。主語が人の名前や the cat などでも、1人・1ぴきなら is を使います。\n会話では短縮形(2語をちぢめた形)もよく使います:I am → I\'m、you are → you\'re、he is → he\'s、she is → she\'s、it is → it\'s。',
        key: 'I は am、you と複数は are、それ以外の1人・1つは is。',
        ex: [{ q: '( )に am・is・are のどれかを入れよう。(1) I (   ) from Japan. (2) Ken and Mika (   ) in the library. (3) My dog (   ) very big.', hint: 'まず主語が I か、you・複数か、それ以外の1人・1つかを見分けます。', steps: ['(1) 主語は I。I には必ず am を使うので am。', '(2) 主語は Ken and Mika。and で2人がつながっているので複数 → are。', '(3) 主語は my dog。自分でも相手でもない1ぴき(単数)なので is。'], a: '(1) am(私は日本出身です。) (2) are(ケンとミカは図書館にいます。) (3) is(私の犬はとても大きいです。)', check: '主語を代名詞に置きかえると、(2) は they、(3) は it になり、they are・it is の組み合わせと一致します。' }] },
      { h: 'be動詞の2つの意味', t: '①【イコール(〜です)】…主語と後ろのことばが「同じもの」や「そのようす」であることを表します。\nTom is a doctor.(トムは医者です。)→ Tom = a doctor\nThe cat is cute.(そのねこはかわいいです。)→ the cat = cute(ようす)\n②【いる・ある】…後ろに場所を表すことばがきます。in(〜の中に)、on(〜の上に)、under(〜の下に)などを使います。\nMy mother is in the kitchen.(母は台所にいます。)/Your bag is on the desk.(あなたのかばんは机の上にあります。)\nどちらの意味かは、be動詞の後ろが「名詞・ようすを表すことば」か「場所を表すことば」かで判断できます。' },
      { h: '否定文の作り方', t: '「〜ではありません」「〜にいません」という打ち消しの文を【否定文】といいます。\n作り方はかんたんで、【be動詞の後ろに not を入れる】だけです。\nHe is busy.(彼はいそがしいです。)→ He is not busy.(彼はいそがしくありません。)\nI am a teacher.(私は先生です。)→ I am not a teacher.(私は先生ではありません。)\n短縮形は is not → isn\'t、are not → aren\'t です。am not は短縮せず、I\'m not とします。\nnot の位置がずれると意味が通じなくなります。「be動詞のすぐ後ろ」と位置を決めて覚えましょう。' },
      { h: '疑問文と答え方', t: '「〜ですか」とたずねる文を【疑問文】といいます。be動詞の文では、【be動詞を主語の前に出し、最後に ? をつけます】。\nHe is busy. → Is he busy?(彼はいそがしいですか。)\nYou are a student. → Are you a student?(あなたは生徒ですか。)\n答えるときも be動詞を使います。Yes, he is.(はい、いそがしいです。)/No, he isn\'t.(いいえ、いそがしくありません。)\n答えでは、人の名前や this・that を代名詞(he・she・it など)にかえます。Is this your bike?(これはあなたの自転車ですか。)→ Yes, it is.\nAre you 〜? と聞かれたら、答えは自分のことなので I am で答えます。Are you hungry? — Yes, I am.(はい、すいています。)',
        key: '疑問文は be動詞を主語の前へ。答えも be動詞を使い、名前は代名詞にかえる。',
        ex: [{ q: 'Ken is in the gym.(ケンは体育館にいます。)を、否定文と疑問文にしよう。疑問文には答え方も書こう。', hint: 'be動詞はどれかを最初に見つけ、not を入れる位置・前に出す語を決めます。', steps: ['主語 Ken は自分と相手以外の1人なので、be動詞は is。この is を動かせばよい。', '否定文:is の後ろに not を入れる → Ken is not in the gym.', '疑問文:is を主語 Ken の前に出し、最後を ? にする → Is Ken in the gym?', '答え方:名前の Ken は代名詞 he にかえて、Yes, he is. / No, he isn\'t.'], a: '否定文:Ken is not(isn\'t) in the gym.(ケンは体育館にいません。)/疑問文:Is Ken in the gym?(ケンは体育館にいますか。)— Yes, he is. / No, he isn\'t.', check: 'できた疑問文の Is を主語の後ろにもどすと、もとの文 Ken is in the gym. にもどることを確かめます。' }] },
      { h: 'be動詞と一般動詞を区別する', t: 'play(する)、like(好きだ)、go(行く)のように、動作や気持ちを表す動詞を【一般動詞】といいます。be動詞以外の動詞はすべて一般動詞です。\n【1つの文に、動詞は原則1つ】です。be動詞と一般動詞を並べてはいけません。\n× I am play tennis. → ○ I play tennis.(私はテニスをします。)\n見分け方:「イコールの文」「いる・あるの文」なら be動詞、「動作・気持ちの文」なら一般動詞です。\n疑問文の作り方も別々です。be動詞の文は Are you 〜?、一般動詞の文は Do you 〜? で始めます(一般動詞の文は次の単元でくわしく学びます)。\nAre you hungry?(あなたはおなかがすいていますか。)/Do you like music?(あなたは音楽が好きですか。)',
        key: '1つの文に動詞は1つ。be動詞と一般動詞を並べない。',
        ex: [{ q: '( )に入る語は? (1) She (   ) a student. (2) (   ) you play tennis?', hint: '文の中に一般動詞があるかどうかを先に確認します。', steps: ['(1) 文の中に一般動詞がない。「彼女=生徒」というイコールの文なので be動詞を入れる。', '主語 She は自分と相手以外の1人なので is。', '(2) play(する)という一般動詞がある。一般動詞の疑問文は Do で始める。', 'Are を入れると、be動詞と一般動詞が並んでしまうのでまちがい。'], a: '(1) is(彼女は生徒です。) (2) Do(あなたはテニスをしますか。)', check: '(2) の答えの文 Do you play tennis? の中で、動詞は play の1つだけになっていることを確かめます。' },
          { q: '次の文のまちがいを直そう。(1) My brother and I is good friends. (2) Are you like music?', hint: '(1) は主語の人数、(2) は動詞の数に注目します。', steps: ['(1) 主語は My brother and I。兄[弟]と私の2人なので複数。', '複数の主語には are を使う → My brother and I are good friends.', '(2) like(好きだ)は一般動詞。Are を使うと be動詞と一般動詞が並んでしまう。', '一般動詞の疑問文なので Do で始める → Do you like music?'], a: '(1) My brother and I are good friends.(兄[弟]と私は仲のよい友だちです。) (2) Do you like music?(あなたは音楽が好きですか。)', check: '(1) の主語を we(私たち)に置きかえると We are good friends. となり、are が正しいと確かめられます。' }] },
      { h: 'もっと深く:be動詞は文の「つなぎ役」としてくり返し登場する', t: 'be動詞の後ろに来ることばは、大きく分けて3種類です。①【名詞】(a student・my sister)、②【形容詞】(happy・tall などようすを表すことば)、③【場所を表すことば】(in the room・here)。①と②は主語を説明する「イコール」の関係、③は「いる・ある」の関係です。\n日本語では「彼女はうれしい。」のように「です」がなくても文になります。しかし英語では、形容詞だけでは動詞になれないので、She is happy. と be動詞が必要です。× She happy. は、英語として成り立ちません。\n「〜がある・いる」は、【There is / There are 〜】でも表せます。There is a cat under the table.(テーブルの下にねこが1ぴきいます。)/There are two cats under the table.(テーブルの下にねこが2ひきいます。)この文では、is か are かを【後ろの名詞】で決めます。主語の位置にある there には「そこに」という意味はほとんどありません。\n主語が長いときは、かたまりの【中心の名詞】を見ます。The pictures on the wall are beautiful.(かべの絵は美しい。)では、on the wall は説明で、中心は pictures(複数)なので are です。\nbe動詞はこの先、進行形(be + ing形)、受動態(be + 過去分詞)、be going to などで何度も使います。どの文でも「not は be動詞の後ろ」「疑問文は be動詞を主語の前へ」というルールはそのままです。ここで身につけたルールが、中学英語全体の土台になります。', key: 'be動詞の後ろは「名詞・形容詞(イコール)」か「場所(いる・ある)」。主語が長いときは中心の名詞で am・is・are を決める。' },
      { h: '入試ではこう出る:主語を見きわめて be動詞を選ぶ', t: '高校入試では、be動詞だけを問う問題は多くありません。そのかわり、【適語補充・語形選択・英作文】の中で、主語に合った形を選べるかがくり返し試されます。\nいちばん多いひっかけは、【主語と be動詞の間に説明が入る文】です。The books on that desk 〜 のように、be動詞のすぐ前の desk(単数)につられて is を選ぶとまちがいです。主語のかたまりの中心(ここでは books)を見つけましょう。\nOne of 〜(〜のうちの1人・1つ)も定番です。One of my friends 〜 の中心は one なので単数あつかい、is を使います。friends が複数でも、主語は「1人」です。\nThere is / There are の文では、be動詞の後ろの名詞を見ます。a lot of students(たくさんの生徒)なら複数なので are です。\n英作文では、【be動詞のぬけ】がよくある減点です(× I very happy.)。書き終えたら、1文ずつ「動詞があるか」「主語と形が合っているか」を確認しましょう。選択問題は「主語の中心 → 単数か複数か → 形」の3点確認で、1問30秒以内を目安に解きます。', key: '主語のかたまりの中心を見つける。One of 〜 は単数、There is / are は後ろの名詞で決める。',
        ex: [{ q: '( )内から最も適切な語を選ぼう。(1) The books on that desk ( am / is / are ) mine. (2) One of my sisters ( is / are ) a nurse. (3) There ( is / are ) a lot of students in the gym.', hint: 'be動詞のすぐ前の語ではなく、主語のかたまりの中心の名詞を探します。', steps: ['(1) 主語は The books on that desk。on that desk は「あの机の上の」という説明なので、中心は books(複数)→ are。', '(2) 主語は One of my sisters。中心は one(1人)なので単数 → is。', '(3) There 〜 の文は、be動詞の後ろの名詞で決める。a lot of students は複数 → are。', 'それぞれ、主語を代名詞に置きかえて(they・she・they)形が合うか確かめる。'], a: '(1) are(あの机の上の本は私のものです。) (2) is(私の姉妹の1人は看護師です。) (3) are(体育館にたくさんの生徒がいます。)', check: '(1) は They are mine.、(2) は She is a nurse. と言いかえられ、選んだ形と一致します。' }] }
    ],
    faq: [
      ['なぜ is と are を使い分ける必要があるの?', '英語では、動詞の形で「主語が1人(1つ)か、2人(2つ)以上か」を示すしくみがあるからです。\n日本語の「です」は主語がだれでも同じですが、英語では be動詞の形を見るだけで主語が単数か複数かが分かります。'],
      ['I am a student. の a は何?', '「1人の・1つの」という意味のことばで、数えられるものが1つのとき名詞の前につけます。\napple(りんご)のように母音(ア・イ・ウ・エ・オに近い音)で始まる語の前では an にします:an apple。\n複数のときは a をつけず、名詞に s をつけます:We are students.'],
      ['This is と It is はどうちがうの?', 'This is 〜 は、近くにあるものを指して「これは〜です」と言うときに使います。\nIt is 〜 は、一度話に出たものをもう一度言うときに使います。Is this your pen? — Yes, it is. のように、答えでは this を it にかえます。'],
      ['Yes, I am. を Yes, I\'m. と短縮できないのはなぜ?', '短縮形の I\'m は、am を弱く軽く読むときの形です。文の最後では am を強く読むので、短縮できません。\nそのため Yes, I am. / Yes, he is. のように短縮しない形で答えます。いっぽう No, I\'m not. は、最後に not が来るので短縮してかまいません。']
    ],
    drill: [
      { lv: 1, q: '( )に am・is・are のどれかを入れよう。(1) You and Ken (   ) classmates. (2) This bag (   ) very old.', a: '(1) are (2) is', exp: '(1) 主語は You and Ken。and で2人がつながっているので複数です。複数の主語には are を使います。(あなたとケンは同級生です。)\n(2) 主語は This bag(このかばん)。1つのものなので is です。(このかばんはとても古い。)\n迷ったら、主語を代名詞に置きかえます。(1) は you(あなたたち)、(2) は it になり、you are・it is の組み合わせと一致します。' },
      { lv: 1, q: 'I am a junior high school student.(私は中学生です。)を否定文にしよう。', a: 'I am not a junior high school student.(I\'m not a junior high school student.)', exp: 'be動詞の否定文は、be動詞のすぐ後ろに not を入れるだけです。\nam not には短縮形がないので、短くするときは I\'m not とします。× I amn\'t は使いません。' },
      { lv: 2, q: 'Are these your shoes?(これらはあなたのくつですか。)に Yes で答えよう。', a: 'Yes, they are.', exp: '答えでは、these(これら)を代名詞にかえます。these は複数のものを指すので they を使います。\n主語が they なので be動詞は are。Yes, they are. となります。\nthis で聞かれたら it、these で聞かれたら they、と組み合わせで覚えておくと、答えの文ですぐに使えます。' },
      { lv: 2, q: '日本文に合う英文を書こう。「私の父と母は今、台所にいます。」', a: 'My father and mother are in the kitchen now.', exp: '「いる」は be動詞で表します。場所は in the kitchen(台所に)です。\n主語は My father and mother(父と母)の2人なので複数。be動詞は are です。\nnow(今)はふつう文の最後に置きます。主語が2人なので、is にしないよう注意しましょう。' },
      { lv: 3, q: '次の文には誤りが1か所あります。正しく直して全文を書こう。The boy in the pictures are my brother.', a: 'The boy in the pictures is my brother.(写真の中の男の子は私の兄[弟]です。)', exp: 'be動詞のすぐ前の pictures は複数ですが、これは in the pictures(写真の中の)という説明の一部です。\n主語のかたまりの中心は The boy(1人の男の子)なので単数。are ではなく is が正しい形です。\n主語を He に置きかえると He is my brother. となり、is で合っていることが確かめられます。入試では、このように説明のことばで主語と動詞が離れる文がよくねらわれます。' },
      { lv: 3, q: '対話が成り立つように、( )に適する語を1語ずつ入れよう。A: (   ) your sister a teacher? B: No, (   ) (   ). She is a doctor.', a: 'Is / she / isn\'t(A:あなたのお姉さん[妹さん]は先生ですか。B:いいえ、ちがいます。彼女は医者です。)', exp: 'B の答えに She is a doctor. とあるので、A は「お姉さん[妹さん]は先生ですか」とたずねる be動詞の疑問文です。主語 your sister は単数なので Is で始めます。\n答えでは your sister を代名詞 she にかえ、No のあとは否定の形 she isn\'t とします。\n空所が2つなので、短縮形 isn\'t を使って she / isn\'t で2語にします(she\'s not でも意味は同じですが、空所の数に合わせます)。' }
    ],
    terms: [['be動詞', 'am・is・are(過去形は was・were)。「〜です」「〜にいる・ある」を表す'], ['一般動詞', 'be動詞以外の動詞。play・like・go など動作や気持ちを表す'], ['主語', '文の中で「〜は・〜が」にあたることば'], ['単数・複数', '1人・1つが単数、2人・2つ以上が複数'], ['短縮形', 'I\'m や isn\'t のように、2語をちぢめて書く形'], ['代名詞', 'he・she・it・they など、名詞のかわりに使うことば']],
    miss: ['be動詞と一般動詞を並べてしまう(× He is play soccer. → ○ He plays soccer.)。日本語の「〜です」につられるのが原因なので、文の中に一般動詞があれば be動詞は入れない、と確認しましょう。', 'Ken and I のような2人の主語に is を使う(正しくは are)。I のすぐ前の語だけを見てしまうのが原因です。主語全体を見て、we に置きかえて考えましょう。', '疑問文の答えで Yes, Ken is. と名前のまま答える。英語の答えは代名詞を使うのが決まりなので、Yes, he is. とします。', 'am not を amn\'t と短縮する。am not には短縮形がないので、I\'m not とします。'],
    sum: ['英語の文には必ず動詞が1つ。「〜です」をつなぐのが be動詞。', 'I → am、you・複数 → are、それ以外の1人・1つ → is。', 'be動詞の意味は「イコール」と「いる・ある」。', '否定文は be動詞の後ろに not、疑問文は be動詞を主語の前へ。答えも be動詞で。', '1つの文に be動詞と一般動詞を並べない。'],
    next: '次は「一般動詞の現在形・三単現」(e_pres)へ進みましょう。be動詞以外の動詞(play・like など)の文の作り方と、主語によってつく s のルールを学びます。'
  };
  L.e_pres = {
    goal: '一般動詞の現在形で、主語が3人称単数のときに s をつけ、do・does を使った否定文・疑問文を作れるようになる。',
    intro: 'I play tennis. と He plays tennis.。主語が he になると、動詞に s がつきます。これは「話し手(I)でも聞き手(you)でもない、ほかの1人・1つ」が主語だという目じるしです。この s を【3単現の s】といいます。しくみが分かれば、否定文・疑問文も同じ考え方で作れます。',
    pre: '【一般動詞】とは、be動詞(am・is・are)以外の動詞のことです。play(〈スポーツなど〉をする)、like(〜が好きだ)、have(〜を持っている)、go(行く)、study(勉強する)などがあります。\n英語の語順は【主語 → 動詞 → 目的語(〜を)】です。「私はテニスをします」は I(私は)play(します)tennis(テニスを).となり、日本語とは動詞の位置がちがいます。\n1つの文に動詞は1つだけでした。I play tennis. には play があるので、am は入れません(× I am play tennis.)。\n主語が「1人・1つ(単数)」か「2人・2つ以上(複数)」かを見分ける力も使います。Ken and Tom や my parents(両親)は複数です。',
    secs: [
      { h: '「3人称単数」とはだれのこと?', t: '英語では、主語を3つのグループ(人称)に分けて考えます。\n【1人称】話し手自身:I(私)、we(私たち)\n【2人称】聞き手:you(あなた・あなたたち)\n【3人称】それ以外のすべて:he、she、it、Ken、my mother、this dog など\nこのうち、3人称で【1人・1つ】(単数)のものを【3人称単数】といいます。主語が3人称単数で現在の文のとき、一般動詞に s をつけます。\nKen plays soccer.(ケンはサッカーをします。)/My sister likes cats.(姉[妹]はねこが好きです。)\n主語が Ken and Tom(2人)や they なら複数なので、s はつけません:They play soccer.(彼らはサッカーをします。)',
        key: '「自分でも相手でもない1人・1つ」が主語で、現在の文なら、一般動詞に s をつける。' },
      { h: 's のつけ方', t: 's のつけ方には、語の終わり方によっていくつかのルールがあります。発音しやすくするための決まりです。\n①ふつうは【s】:play → plays、like → likes、run → runs\n②s・x・sh・ch・o で終わる語は【es】:watch → watches、wash → washes、go → goes、do → does\n③「子音字 + y」で終わる語は、y を i にかえて【ies】:study → studies、try → tries\n「母音字(a・i・u・e・o)+ y」はそのまま s です:play → plays、enjoy → enjoys\n④特別な形:【have → has】。これは1語だけ覚えればよい例外です。\n例:He goes to school by bus.(彼はバスで学校に行きます。)/She studies English every day.(彼女は毎日英語を勉強します。)',
        ex: [{ q: '( )内の動詞を正しい形にしよう。(1) Mika (watch) TV after dinner. (2) My father (have) a car. (3) Tom (study) math.', hint: '主語が3人称単数かどうか → 動詞の終わり方、の順に確認します。', steps: ['主語の Mika・My father・Tom は、どれも自分と相手以外の1人なので3人称単数。現在の文なので s をつける。', '(1) watch は ch で終わる。s だけだと発音しにくいので es をつけて watches。', '(2) have は特別な形で has になる。', '(3) study は「子音字 d + y」で終わるので、y を i にかえて es → studies。'], a: '(1) watches(ミカは夕食後にテレビを見ます。) (2) has(父は車を持っています。) (3) studies(トムは数学を勉強します。)', check: '主語を I にかえると、watch・have・study ともとの形にもどることを確かめます。' }] },
      { h: '否定文:do not・does not', t: '一般動詞の否定文は、be動詞のように not を入れるだけでは作れません。動詞の前に【do not(don\'t)】を置きます。\nI like dogs. → I don\'t like dogs.(私は犬が好きではありません。)\n主語が3人称単数のときは【does not(doesn\'t)】を使い、後ろの動詞は【原形】(s のつかないもとの形)にもどします。\nShe likes dogs. → She doesn\'t like dogs.(彼女は犬が好きではありません。)\nなぜ原形にもどすのでしょうか。それは、does の中にすでに s(3単現のしるし)が入っているからです。【s は1つの文に1回だけ】と考えましょう。\n× She doesn\'t likes dogs. のように s を2回つけるのは、まちがいです。',
        key: '3単現の否定文は doesn\'t + 動詞の原形。s は does に移ったので、動詞は原形。' },
      { h: '疑問文と答え方', t: '一般動詞の疑問文は、文の最初に【Do】を置きます。主語が3人称単数なら【Does】です。後ろの動詞はやはり原形です。\nYou like dogs. → Do you like dogs?(あなたは犬が好きですか。)\nShe likes dogs. → Does she like dogs?(彼女は犬が好きですか。)\n答えも do・does を使います:Yes, I do. / No, I don\'t.  Yes, she does. / No, she doesn\'t.\nbe動詞の文と一般動詞の文では、疑問文の作り方がちがいます。Is she 〜?(be動詞の文)と Does she 〜?(一般動詞の文)を、動詞の種類で使い分けましょう。',
        ex: [{ q: 'Tom plays the guitar.(トムはギターをひきます。)を否定文と疑問文にしよう。疑問文には答え方も書こう。', hint: '主語が3人称単数なので、do ではなく does を使います。', steps: ['主語 Tom は3人称単数なので、do ではなく does を使う。', '否定文:動詞の前に doesn\'t を置き、plays を原形 play にもどす(s は does に移ったから)→ Tom doesn\'t play the guitar.', '疑問文:文の最初に Does を置き、動詞は原形 → Does Tom play the guitar?', '答え方:Tom を代名詞 he にかえて Yes, he does. / No, he doesn\'t.'], a: '否定文:Tom doesn\'t play the guitar.(トムはギターをひきません。)/疑問文:Does Tom play the guitar?(トムはギターをひきますか。)— Yes, he does. / No, he doesn\'t.', check: '文の中に s のしるしが1回だけ(does のところだけ)になっているか数えて確かめます。' },
          { q: '( )に do・does・is・are から適する語を入れよう。(1) (   ) your brother like baseball? (2) (   ) your parents busy? (3) My sister (   ) not have a bike.', hint: '文の中に一般動詞があるかどうか、主語が単数か複数かの2点を確認します。', steps: ['(1) like は一般動詞。主語 your brother は3人称単数なので Does。', '(2) 一般動詞がなく、「両親=いそがしい」というイコールの文なので be動詞。主語 your parents は複数なので Are。', '(3) have は一般動詞。主語 my sister は3人称単数なので does(does not で「〜ない」)。', 'どれも、be動詞と一般動詞が並ばないように選んでいる。'], a: '(1) Does(お兄[弟]さんは野球が好きですか。) (2) Are(ご両親はいそがしいですか。) (3) does(姉[妹]は自転車を持っていません。)', check: 'できた文の中で、be動詞と一般動詞が同時に使われていないことを確かめます。' }] },
      { h: '現在形が表すこと', t: '一般動詞の現在形は、「今この瞬間」よりも、【ふだんの習慣・くり返すこと】や【変わらない事実】を表します。\nI get up at six every morning.(私は毎朝6時に起きます。)\nThe sun rises in the east.(太陽は東からのぼります。)\nevery day(毎日)、usually(ふつうは)、often(よく)、sometimes(ときどき)などの語といっしょによく使われます。\nusually・often・sometimes のように「どのくらいの回数か」を表す語は、ふつう一般動詞の前に置きます。\nHe usually walks to school.(彼はふだん歩いて学校へ行きます。)',
        ex: [{ q: '日本文に合う英文を書こう。「私の母はときどき朝食の前に公園を走ります。」', hint: '主語 → 回数を表す語 → 動詞 → 場所 → 時 の順に並べます。', steps: ['主語は my mother(3人称単数)。現在の習慣なので現在形を使う。', '「ときどき」は sometimes。回数を表す語なので一般動詞の前に置く。', '「走る」は run。3人称単数なので runs。「公園を」は in the park。', '「朝食の前に」は before breakfast。英語では場所 → 時の順なので最後に置く。'], a: 'My mother sometimes runs in the park before breakfast.', check: '主語を my parents(複数)にかえると runs が run にもどることを確かめると、s が正しくついているか分かります。' }] },
      { h: 'もっと深く:三単現の s と do・does のしくみ', t: '否定文・疑問文で使う do・does は、それ自体に意味はなく、【文の形を作るための語(助動詞)】です。does は do に es がついた形で、主語が3人称単数であることを引き受けています。\nShe likes music. を疑問文にすると、likes の s が does に移ると考えられます:Does she like music? 。s は1つの文に1回だけなので、does を使ったら後ろの動詞は【原形】にもどります。否定文 She doesn\'t like music. も同じしくみです。\ns の発音は3通りです。likes・stops は /s/(ス)、plays・goes は /z/(ズ)、watches・washes・uses は /iz/(イズ)。つづりに es がつく語や、se で終わる語の多くは /iz/ と読みます。\n主語が3人称単数かどうか迷う例もあります。My father and mother は2人なので複数(s なし)。Everyone(みんな)は「1人1人」と考えて単数あつかいなので、Everyone likes him. と s をつけます。\n現在形は「今この瞬間」ではなく、【いつもくり返すこと(習慣)・変わらない事実】を表します。The sun rises in the east.(太陽は東からのぼる。)のような事実も現在形です。always・usually・often・sometimes などの頻度を表す語は、【一般動詞の前】に置きます(be動詞の文では be動詞の後ろ)。', key: 'does が s を引き受けるので、does の後ろの動詞は原形。現在形は「習慣・変わらない事実」を表す。' },
      { h: '入試ではこう出る:語形変化と主語の見落とし', t: '高校入試では、「( )内の語を適する形にかえなさい」という【語形変化】の問題がよく出ます。答えを出す前に、①主語は3人称単数か、②時は現在か、③否定文・疑問文で does を使っていないか、の3点を確認します。\nひっかけの典型は、【主語と動詞が離れている文】です。My sister often 〜 のように頻度の副詞が間に入る文や、Everyone in my class 〜 のように説明がつく主語では、s を落としやすくなります。\nもう1つは、【Does・doesn\'t の後ろに s をつけてしまう】まちがいです。Does he (study) 〜? の答えは studies ではなく study です。\nhave → has、do → does、go → goes のように、s のつけ方が特別な語もねらわれます。study → studies(子音字 + y)と play → plays(母音字 + y)の区別も確認しておきましょう。\n英作文では、3人称単数の主語で s が落ちるのがいちばん多い減点です。書いたら主語に線を引き、その動詞に s が必要かを1文ずつ点検する習慣をつけると、ミスが大きく減ります。', key: '主語・時・does の有無を確認してから形を決める。Does・doesn\'t の後ろは必ず原形。',
        ex: [{ q: '( )内の語を適する形にかえよう。(1) My sister often (go) shopping with her friends. (2) Does your brother (study) English every day? (3) Everyone in my class (like) Mr. Brown.', hint: '主語が3人称単数か、文の中に does があるかを先に確認します。', steps: ['(1) 主語は My sister(3人称単数)。often は間に入った頻度の副詞なので、動詞 go に es をつけて goes。', '(2) 文の頭に Does がある。s は does が引き受けているので、動詞は原形の study のまま。', '(3) 主語は Everyone in my class。中心の Everyone は単数あつかいなので likes。', '最後に、それぞれの文で s が1回だけ使われているかを確認する。'], a: '(1) goes(私の姉[妹]はよく友だちと買い物に行きます。) (2) study(あなたのお兄さん[弟さん]は毎日英語を勉強しますか。) (3) likes(私のクラスのみんながブラウン先生を好きです。)', check: '(2) を肯定文にもどすと Your brother studies English every day. となり、s が does に移っていたことが分かります。' }] }
    ],
    faq: [
      ['なぜ3人称単数のときだけ s をつけるの?', '昔の英語では、主語ごとに動詞の形がたくさん変わっていました。長い時間の中でほとんどの形がなくなり、3人称単数の s だけが残ったのです。\n理由を気にするより、「he・she・it などのしるし」と考えて使えば大丈夫です。'],
      ['Does she likes 〜? はなぜだめなの?', 'does が「3人称単数・現在」のしるしをすでに持っているからです。しるしを2回つけることはしません。\nDoes を使ったら、後ろの動詞は必ず原形にもどします。'],
      ['I と you は単数なのに、なぜ s をつけないの?', 's をつけるのは「3人称」の単数だけです。I は1人称、you は2人称なので、単数でも s はつけません。'],
      ['always や often は、文のどこに置けばいいの?', 'always・usually・often・sometimes・never などの頻度を表す語は、ふつう【一般動詞の前】、【be動詞の後ろ】に置きます。\nI often play tennis.(私はよくテニスをします。)/He is always kind.(彼はいつも親切です。)\nsometimes は文の最初や最後に置くこともあります。迷ったら「一般動詞の前・be動詞の後ろ」を基本にすれば安全です。']
    ],
    drill: [
      { lv: 1, q: '次の動詞に3人称単数現在の s(es)をつけよう。(1) carry (2) wash (3) play', a: '(1) carries (2) washes (3) plays', exp: '(1) carry は「子音字 + y」で終わるので、y を i にかえて es をつけます。\n(2) wash は sh で終わるので es をつけます。s・x・ch・sh・o で終わる語は es です。\n(3) play は「母音字(a)+ y」で終わるので、そのまま s をつけます。y の前の文字が母音字か子音字かで変わる点がポイントです。' },
      { lv: 1, q: 'My brother plays soccer.(私の兄[弟]はサッカーをします。)を否定文にしよう。', a: 'My brother doesn\'t(does not)play soccer.', exp: '主語が3人称単数なので、否定文は does not(doesn\'t)を動詞の前に置きます。\ns は doesn\'t が引き受けるので、plays は原形 play にもどします。× doesn\'t plays としないよう注意しましょう。' },
      { lv: 2, q: 'Your parents watch TV every night. を疑問文にし、No で答えよう。', a: 'Do your parents watch TV every night? — No, they don\'t.', exp: '主語 Your parents(あなたの両親)は2人なので複数。疑問文は Do で始めます。\n答えでは your parents を代名詞 they にかえ、No, they don\'t. とします。\n主語が parents のように複数形の名詞なら、3人称でも s はつかず、does も使いません。「3人称」かつ「単数」のときだけ does になることを確認しましょう。' },
      { lv: 2, q: '日本文に合う英文を書こう。「私の祖父はいつも6時に起きます。」', a: 'My grandfather always gets up at six.', exp: '「起きる」は get up。主語 My grandfather は3人称単数なので gets up とします。\nalways(いつも)は一般動詞の前に置くので、always gets up の語順です。\n「6時に」は at six(at six o\'clock)。習慣を表すので現在形を使います。' },
      { lv: 3, q: '次の文には誤りが2か所あります。正しく直して全文を書こう。Ken and his sister doesn\'t likes cats.', a: 'Ken and his sister don\'t like cats.(ケンと彼の妹[姉]はねこが好きではありません。)', exp: '主語は Ken and his sister の2人なので複数です。複数の主語の否定文は don\'t を使います。doesn\'t は誤りです。\nまた、don\'t・doesn\'t の後ろの動詞は原形なので、likes を like にします。\n主語が and でつながっているときは複数、というルールと、否定文の動詞は原形、という2つのルールが同時に問われる問題です。' },
      { lv: 3, q: '下線部の発音が、ほかの3つと異なるものを選ぼう。ア watches の es イ uses の es ウ washes の es エ plays の s', a: 'エ', exp: 'watches・uses・washes の語尾は、どれも /iz/(イズ)と発音します。ch・se・sh の音のあとに s をつけると、間に母音が入るためです。\nplays の s は /z/(ズ)で、イの音は入りません。\nつづりの es だけで判断せず、「語の最後の音」で考えるのがコツです。ch・sh・s・se などのこすれる音で終わる語は /iz/ になります。' }
    ],
    terms: [['3人称単数', '自分(I)と相手(you)以外の、1人・1つ'], ['3単現の s', '主語が3人称・単数で、現在の文のときに一般動詞につける s・es'], ['原形', 's も ed もつかない、動詞のもとの形'], ['do・does', '一般動詞の否定文・疑問文を作るときに使う語'], ['目的語', '動詞の後ろにきて「〜を」にあたることば'], ['頻度を表す副詞', 'usually・often・sometimes など、回数を表す語。一般動詞の前に置く']],
    miss: ['否定文・疑問文で s を残す(× Does he plays? → ○ Does he play?)。does がしるしを引き受けている、と考えて原形にもどしましょう。', 'He don\'t 〜 としてしまう(3単現は doesn\'t)。主語を見てから don\'t と doesn\'t を選ぶ習慣をつけましょう。', 'study を studys、go を gos とする(正しくは studies、goes)。動詞の最後の文字を見てからつけ方を決めましょう。', '主語が They や Ken and Tom なのに s をつける。主語が複数かどうかを先に確認しましょう。'],
    sum: ['主語が3人称単数・現在なら、一般動詞に s・es をつける。', 'have は has、study は studies、go は goes。', '否定文は don\'t・doesn\'t + 原形。', '疑問文は Do・Does + 主語 + 原形。答えも do・does を使う。', '現在形は、習慣や変わらない事実を表す。'],
    next: '次は「現在進行形」(e_prog)へ進みましょう。ふだんのこと(現在形)と「今まさにしていること」を、形で区別できるようになります。'
  };
  L.e_prog = {
    goal: '「今〜しているところ」を be動詞 + ing形で表し、ing形を正しく作って、肯定文・否定文・疑問文を書けるようになる。',
    intro: 'I play tennis. は「(ふだん)テニスをする」、I am playing tennis. は「(今まさに)テニスをしているところ」。同じ play でも、形を変えると伝わる場面が変わります。今ちょうど動作の途中であることを表すのが【現在進行形】です。',
    pre: 'be動詞(am・is・are)は主語に合わせて使い分けました。I → am、you・複数 → are、それ以外の1人・1つ → is です。\nbe動詞の文の否定文は be動詞の後ろに not、疑問文は be動詞を主語の前に出して作りました。この単元でもそのまま使います。\n一般動詞の現在形(I play tennis.)は、【ふだんの習慣】を表しました。「毎週テニスをする」という意味で、今この瞬間にしているとは限りません。\n動詞の【原形】とは、s や ed のつかないもとの形(play・make など)のことです。',
    secs: [
      { h: '現在形と現在進行形のちがい', t: 'I play tennis.(現在形)…ふだんテニスをする(習慣)。今この瞬間はしていなくてもかまいません。\nI am playing tennis now.(現在進行形)…今まさにテニスをしているところ。\n「進行」は「進んでいる途中」という意味です。動作が始まっていて、まだ終わっていない場面を表します。\n現在進行形は【be動詞 + 動詞の ing形】で作ります。be動詞は主語に合わせて am・is・are を使い分けます。\nHe is reading a book.(彼は本を読んでいます。)/They are swimming in the pool.(彼らはプールで泳いでいます。)\nnow(今)、right now(ちょうど今)、Look!(見て)、Listen!(聞いて)などが目じるしになります。',
        key: '現在進行形 = be動詞 + ing形。「今まさに〜している途中」を表す。' },
      { h: 'ing形の作り方', t: '①ふつうはそのまま【ing】:play → playing、read → reading、study → studying\n②発音しない e で終わる語は【e をとって ing】:make → making、write → writing、use → using\n③「短い母音 + 子音字1つ」で終わる語は【最後の文字を重ねて ing】:run → running、swim → swimming、sit → sitting、get → getting\n④ie で終わる語は【ie を y にかえて ing】:lie → lying、die → dying\nswim の m を重ねるのは、swiming だと「スワイミング」のように読まれやすく、短い「イ」の音を残すためです。',
        ex: [{ q: '次の動詞を ing形にしよう。(1) dance (2) cut (3) cook (4) write', hint: '動詞の最後の1〜2文字を見て、①〜④のどのルールかを決めます。', steps: ['(1) dance は e で終わる → e をとって dancing。', '(2) cut は「短い母音 u + 子音字 t」で終わる → t を重ねて cutting。', '(3) cook は母音字が2つ(oo)続いているので「短い母音 + 子音字1つ」ではない → そのまま cooking。', '(4) write は e で終わる → e をとって writing(t は重ねない)。'], a: '(1) dancing (2) cutting (3) cooking (4) writing', check: '声に出して読んでみて、もとの動詞の音(ダンス・カット・クック・ライト)がそのまま残っているか確かめます。' }] },
      { h: '肯定文・否定文の作り方', t: '現在進行形は be動詞を使う文なので、be動詞の文と同じしくみで作れます。\n【肯定文】主語 + be動詞 + ing形.\nShe is cooking dinner.(彼女は夕食を作っています。)\n【否定文】be動詞の後ろに not を入れます。do・does は使いません。\nShe is not(isn\'t) cooking dinner.(彼女は夕食を作っていません。)\nI\'m not sleeping.(私は眠っていません。)',
        key: '進行形の否定文・疑問文は、be動詞のルールで作る。do・does は使わない。' },
      { h: '疑問文と答え方', t: '【疑問文】be動詞を主語の前に出し、最後に ? をつけます。\nIs she cooking dinner?(彼女は夕食を作っていますか。)\n【答え方】be動詞を使って答えます:Yes, she is. / No, she isn\'t.\n疑問詞の what(何)を使うと、「何をしているの?」とたずねられます。do は「する」という意味の動詞で、doing はその ing形です。\nWhat are you doing?(あなたは何をしていますか。)— I\'m doing my homework.(宿題をしています。)\nWhat is Ken doing?(ケンは何をしていますか。)— He is washing the dishes.(お皿を洗っています。)',
        ex: [{ q: 'They play baseball. を「今〜している」の文にし、さらに疑問文にしよう。', hint: 'be動詞を足し、play を ing形にします。', steps: ['「今〜している」なので be動詞 + ing形にする。主語 They は複数なので be動詞は are。', 'play は「母音字 a + y」で終わるので、そのまま ing をつけて playing。', '肯定文:They are playing baseball now.(now を足すと「今」がはっきりする)', '疑問文:be動詞 are を主語 They の前に出す → Are they playing baseball now?'], a: 'They are playing baseball now.(彼らは今野球をしています。)/Are they playing baseball now?(彼らは今野球をしていますか。)— Yes, they are. / No, they aren\'t.', check: '疑問文から are を They の後ろにもどすと、肯定文と同じになることを確かめます。' },
          { q: '[ ]内の語を使って「〜は何をしていますか。— …しています。」の会話を作ろう。[ your sister / swim ]', hint: '質問は What + be動詞 + 主語 + doing? の形です。', steps: ['主語 your sister は3人称単数なので be動詞は is。', '質問:What is your sister doing?(何をしていますか。)', 'swim は「短い母音 i + 子音字 m」で終わるので m を重ねて swimming。', '答え:your sister を代名詞 she にかえ、She is swimming. とする。'], a: 'What is your sister doing? — She is swimming.(お姉[妹]さんは何をしていますか。— 泳いでいます。)', check: '答えの文の be動詞が、質問の be動詞(is)と同じになっていることを確かめます。' }] },
      { h: '進行形にしない動詞', t: 'like(好きだ)、know(知っている)、want(ほしい)、have(持っている)のように、【状態や気持ち】を表す動詞を【状態動詞】といい、ふつう進行形にしません。\nもともと「続いている状態」を表しているので、わざわざ「途中」を表す ing にする必要がないのです。\n× I am knowing him. → ○ I know him.(私は彼を知っています。)\n× She is liking cats. → ○ She likes cats.(彼女はねこが好きです。)\nただし have が「食べる」の意味のときは動作なので、進行形にできます:We are having lunch.(私たちは昼食を食べています。)',
        ex: [{ q: '( )内の動詞を正しい形にしよう。(1) Look! The bird (fly) in the sky. (2) I (know) that girl.', hint: '動作か状態か、「今の途中」の目じるしがあるかを見ます。', steps: ['(1) Look!(見て)があるので、今まさに起きている動作 → 現在進行形。', '主語 the bird は単数なので is、fly はそのまま ing をつけて flying → is flying。', '(2) know(知っている)は状態動詞なので進行形にしない。', '主語 I なので s はつけず、現在形 know のまま。'], a: '(1) is flying(見て!鳥が空を飛んでいるよ。) (2) know(私はあの女の子を知っています。)', check: '(2) を「今知っている途中」と言いかえると意味が不自然になることから、進行形にしないのが正しいと確かめます。' }] },
      { h: 'もっと深く:進行形が表す「途中」と「一時的」', t: '進行形の中心のイメージは、【動作の途中】です。I am reading a book. は、本を読み始めてまだ読み終わっていない「途中」を切り取っています。\nそのため、始まりと終わりがはっきりしない【状態を表す動詞】は、ふつう進行形にしません。know(知っている)、like(好きだ)、want(ほしい)、have(持っている)などです。日本語では「知っている」と「〜ている」がつきますが、英語では I know him. と現在形を使います。\n同じ動詞でも、意味が動作なら進行形にできます。have は「持っている」なら状態ですが、「食べる」なら動作なので I am having lunch.(昼食を食べているところです。)は正しい文です。\n進行形は「一時的なこと」を表すこともあります。I live in Tokyo. は「ふだん住んでいる」ことですが、I am living with my aunt this month.(今月はおばの家で暮らしています。)は一時的なようすです。\ning形のつづりで子音字を重ねるのは、【短い母音 + 子音字1つで終わり、そこを強く読む語】です(run → running、swim → swimming、begin → beginning)。visit は前を強く読むので visiting と重ねません。ie で終わる語は ie を y にかえて ing をつけます(lie → lying、die → dying)。', key: '進行形は「動作の途中・一時的」。状態を表す know・like・want・have(持っている)はふつう進行形にしない。' },
      { h: '入試ではこう出る:合図のことばと状態動詞のひっかけ', t: '高校入試では、進行形は【語形変化・適語選択・対話文】でよく問われます。まず探すのは「今そのとき」の合図です。Look!(見て!)、Listen!(聞いて!)、now、right now などがあれば、進行形を考えます。\nいっぽうで、合図があっても【状態動詞】なら進行形にしません。Ken (want) a new bike now. の答えは wants です。now につられて is wanting としないことが、いちばんのひっかけです。\n( )内の語を「適する形に」という問題では、1語とは限らないことがあります。指示に「2語以上になることもある」とあれば、be動詞 + ing形の2語で答える可能性を考えます。\n対話文では What are you doing? — I\'m 〜ing. のやりとりや、電話で「今何をしているか」をたずねる場面がよく出ます。答えの文の be動詞は、主語に合わせて am・is・are を選びます。\nつづりは swim → swimming、sit → sitting、make → making などが定番です。書いたら「e を消すか・子音字を重ねるか」を確認しましょう。', key: 'Look!・Listen!・now は進行形の合図。ただし know・want などの状態動詞は合図があっても現在形。',
        ex: [{ q: '( )内の語を適する形にかえよう。2語になる場合もある。(1) Listen! Someone (sing) in the next room. (2) Ken (want) a new bike now. (3) Look at those boys. They (swim) in the river.', hint: '合図のことばを見つけたら、その動詞が「動作」か「状態」かを確認します。', steps: ['(1) Listen! があるので「今歌っている」。主語 Someone は単数あつかい → is singing。', '(2) now があるが、want(ほしい)は状態を表す動詞なので進行形にしない。主語 Ken は3人称単数 → wants。', '(3) Look at 〜 で今の動作。主語 They は複数、swim は m を重ねる → are swimming。', 'それぞれの文で、be動詞と ing形がそろっているか(または状態動詞の現在形か)を確認する。'], a: '(1) is singing(聞いて!となりの部屋でだれかが歌っています。) (2) wants(ケンは今、新しい自転車をほしがっています。) (3) are swimming(あの男の子たちを見て。川で泳いでいます。)', check: '(2) を Ken is wanting 〜 とすると、状態動詞を進行形にしたことになります。want は「途中」がない動詞だと確認できます。' }] }
    ],
    faq: [
      ['I am play tennis. はなぜだめなの?', 'be動詞と原形の動詞が並んでしまうからです。進行形にするなら play を ing形に変えて I am playing tennis. とします。\nふだんのことなら be動詞をとって I play tennis. とします。'],
      ['現在形と現在進行形、どちらを使えばいいか迷ったら?', '「ふだん・いつも」のことなら現在形、「今この瞬間の途中」なら現在進行形です。\nevery day・usually があれば現在形、now・Look! があれば現在進行形、と目じるしで判断できます。'],
      ['have はなぜ進行形にできるときとできないときがあるの?', 'have には「持っている」(状態)と「食べる・過ごす」(動作)の両方の意味があるからです。\n動作の意味のときだけ進行形にできます:We are having a good time.(私たちは楽しい時間を過ごしています。)'],
      ['日本語で「〜している」と言うときは、いつも進行形にするの?', 'いいえ。日本語の「〜している」は、英語では進行形にならないことがよくあります。\n「知っている」は know、「住んでいる」はふつう live、「(めがねを)かけている」は wear、「結婚している」は be married です。\n英語で進行形にするのは、動作が「今まさに途中」のときです。日本語の形ではなく、動作の途中かどうかで判断しましょう。']
    ],
    drill: [
      { lv: 1, q: '次の動詞を ing形にしよう。(1) sit (2) take (3) study', a: '(1) sitting (2) taking (3) studying', exp: '(1) sit は「短い母音 + 子音字1つ」で終わるので、t を重ねて sitting。\n(2) take は e で終わるので、e をとって ing をつけ taking。\n(3) study はそのまま ing をつけて studying。過去形(studied)とちがい、y は i にかえません。' },
      { lv: 1, q: 'She reads a book.(彼女は本を読みます。)を「今読んでいるところです」という文にしよう。', a: 'She is reading a book now.', exp: '現在進行形は be動詞 + ing形です。主語 She には is を使います。\nreads の s は be動詞が引き受けるので、ing形は原形 read に ing をつけた reading です。now を加えると「今」の意味がはっきりします。' },
      { lv: 2, q: 'Are they playing tennis? に No で答え、「彼らはバスケットボールをしています」と続けよう。', a: 'No, they aren\'t. They are playing basketball.', exp: 'be動詞の疑問文なので、答えも be動詞を使います。主語は they なので No, they aren\'t. です。\n続く文は「今している」動作なので現在進行形 They are playing basketball. とします。\n答えで do を使って No, they don\'t. としないよう注意しましょう。進行形の疑問文は be動詞で始まっているので、答えも be動詞です。' },
      { lv: 2, q: '日本文に合う英文を書こう。「あなたは今何をしているのですか。— 私は宿題をしています。」', a: 'What are you doing now? — I\'m(I am)doing my homework.', exp: '「何を」は What で文の最初に置き、後ろに進行形の疑問文 are you doing を続けます。\n「宿題をする」は do my homework。進行形にすると I\'m doing my homework. です。\nWhat are you doing? の doing は「する」という動詞 do の ing形です。答えの文では、doing の部分に実際の動作を入れて答えます。' },
      { lv: 3, q: '次の文の誤りを直して全文を書こう。I am knowing her phone number.', a: 'I know her phone number.(私は彼女の電話番号を知っています。)', exp: 'know(知っている)は状態を表す動詞なので、ふつう進行形にしません。\n日本語の「知っている」の「〜ている」につられて進行形にするのは、よくあるまちがいです。\n「知っている」状態は始まりや途中がない、と考えると、現在形 I know 〜 が正しいと分かります。' },
      { lv: 3, q: '( )内の語を適する形にかえよう。2語になる場合もある。My sister usually (walk) to school, but today she (ride) her bike.', a: 'walks / is riding(私の妹[姉]はふだんは歩いて学校へ行きますが、今日は自転車に乗っています。)', exp: '前半は usually(ふだん)があるので「いつものこと(習慣)」です。習慣は現在形で表すので、3人称単数の walks。\n後半は today(今日は)で、いつもとちがう「今の一時的なようす」を表しているので、現在進行形 is riding にします。ride は e で終わるので、e をとって riding。\n1つの文の中で「習慣=現在形」と「今=進行形」をくらべる問題は、両方の意味のちがいが分かっているかを確かめる、入試の定番です。' }
    ],
    terms: [['現在進行形', 'be動詞 + ing形。「今〜しているところ」'], ['ing形', '動詞の後ろに ing をつけた形(現在分詞)'], ['状態動詞', 'like・know・want など、状態や気持ちを表す動詞。ふつう進行形にしない'], ['動作動詞', 'play・run・eat など、動作を表す動詞。進行形にできる'], ['What are you doing?', '「何をしていますか」とたずねる表現']],
    miss: ['be動詞を忘れる(× I playing tennis.)。ing形だけでは動詞にならないので、必ず be動詞とセットで使いましょう。', 'be動詞と原形を並べる(× I am play tennis.)。be動詞を使ったら、後ろは ing形にします。', 'make を makeing、run を runing とする(making、running)。最後の文字を見てルールを選びましょう。', 'know・like を進行形にする。「途中」がある動作かどうかを考えましょう。'],
    sum: ['現在進行形 = be動詞 + ing形で「今〜している」。', 'e で終わる語は e をとる、短い母音 + 子音字は重ねる。', '否定文は be動詞の後ろに not、疑問文は be動詞を前へ。do・does は使わない。', 'What are you doing? で「何をしているか」をたずねる。', 'like・know・want などの状態動詞は進行形にしない。'],
    next: '次は「can・命令文」(e_can)へ進みましょう。「〜できる」の can と、「〜しなさい」の命令文で、動詞の原形の使い方を学びます。'
  };
  L.e_can = {
    goal: 'can を使った「〜できる」の文と、命令文・Don\'t・Let\'s の文を正しい語順で作れるようになる。',
    intro: 'can は、動詞の前に置くだけで「〜できる」という意味を足せる便利なことばです。また、相手に「〜しなさい」「〜しないで」「〜しよう」と働きかける文(命令文)も、この単元で学びます。どちらも【後ろの動詞は原形】という共通のルールがあります。',
    pre: '動詞の【原形】とは、s・ed・ing などのつかない、もとの形のことです。plays の原形は play、goes の原形は go、is・am・are の原形は be です。\n主語が3人称単数(he・she・Ken など)で現在の文なら、一般動詞に s をつけました(He plays tennis.)。この単元では、この s が「つかなくなる」場面が出てきます。\n一般動詞の疑問文は Do・Does で始め、be動詞の疑問文は be動詞を前に出しました。この単元の can はそのどちらでもなく、can 自身を前に出します。\n英語の基本の語順は「主語 → 動詞 → 目的語」です。',
    secs: [
      { h: 'can は「〜できる」', t: 'can のように、動詞の前に置いて意味をつけ足すことばを【助動詞】といいます。「動詞を助けることば」という意味です。\n【can の後ろは、必ず動詞の原形】です。主語が3人称単数でも、can にも動詞にも s はつけません。\nI can swim.(私は泳げます。)/He can swim.(彼は泳げます。)\n× He cans swim. × He can swims.\nなぜ s がつかないのでしょうか。助動詞はもともと、主語によって形が変わらないことばだからです。助動詞がつくと、後ろの動詞はいつも原形にもどる、と覚えましょう。',
        key: '助動詞 can の後ろは必ず動詞の原形。主語が he・she でも s はつけない。',
        ex: [{ q: '( )内の語を使って、「〜できます」の文に書きかえよう。(1) She plays the piano. (can) (2) My brother runs fast. (can)', hint: 'can を動詞の前に入れたら、動詞を原形にもどします。', steps: ['(1) 動詞 plays の前に can を置く。', 'can の後ろは原形なので plays → play。→ She can play the piano.', '(2) 動詞 runs の前に can を置き、runs を原形 run にもどす。', '→ My brother can run fast.'], a: '(1) She can play the piano.(彼女はピアノをひくことができます。) (2) My brother can run fast.(兄[弟]は速く走ることができます。)', check: 'can の後ろの動詞に s・es が残っていないか確かめます。' }] },
      { h: 'can の否定文・疑問文', t: '【否定文】can の後ろに not を入れます。ふつう cannot(1語)か can\'t と書きます。\nShe cannot(can\'t) play the piano.(彼女はピアノをひけません。)\n【疑問文】can を主語の前に出します。do・does は使いません。\nCan she play the piano?(彼女はピアノをひけますか。)\n【答え方】can を使って答えます:Yes, she can. / No, she can\'t.\ncan not と2語に分けて書くこともありますが、ふつうは cannot と1語で書きます。',
        key: 'can の文の否定文・疑問文では、do・does を使わない。can 自身を動かす。',
        ex: [{ q: 'Ken can ski.(ケンはスキーができます。)を否定文と疑問文にしよう。疑問文には答え方も書こう。', hint: 'can の文なので、do・does は使いません。', steps: ['can の文なので、否定文・疑問文で do・does は使わない。', '否定文:can の後ろに not → Ken cannot(can\'t) ski.', '疑問文:can を主語 Ken の前に出す → Can Ken ski?', '答え方:Ken を代名詞 he にかえて Yes, he can. / No, he can\'t.'], a: '否定文:Ken cannot(can\'t) ski.(ケンはスキーができません。)/疑問文:Can Ken ski?(ケンはスキーができますか。)— Yes, he can. / No, he can\'t.', check: 'どの文でも ski が原形のままになっていることを確かめます。' }] },
      { h: '依頼・許可の Can you 〜? / Can I 〜?', t: 'can には「できる」のほかに、会話でよく使う意味があります。\n【Can you 〜?】「〜してくれますか」(依頼:相手にお願いする)\nCan you help me?(手伝ってくれますか。)— Sure.(いいですよ。)/ Sorry, I can\'t.(ごめんなさい、できません。)\n【Can I 〜?】「〜してもいいですか」(許可:自分がしてよいかたずねる)\nCan I use this pen?(このペンを使ってもいいですか。)— Sure. / Of course.(もちろん。)\nだれが動作をするかで区別します。you が主語なら相手が動く(依頼)、I が主語なら自分が動く(許可)です。' },
      { h: '命令文:「〜しなさい」', t: '目の前の相手に「〜しなさい」と言う文を【命令文】といいます。\n命令文は【主語を省いて、動詞の原形で文を始めます】。言う相手(you)が分かりきっているので、主語を言わないのです。\nOpen the window.(窓を開けなさい。)/Wash your hands.(手を洗いなさい。)\nbe動詞の命令文は、原形の Be で始めます:Be quiet.(静かにしなさい。)/Be careful.(気をつけて。)\nていねいにしたいときは please をつけます:Please sit down. / Sit down, please.(すわってください。)\nplease を文の最後に置くときは、前にコンマ(,)をつけます。',
        key: '命令文は主語を言わず、動詞の原形で始める。be動詞なら Be で始める。' },
      { h: '「〜するな」「〜しよう」', t: '【〜するな(禁止)】Don\'t + 動詞の原形.\nDon\'t run in the hallway.(ろうかを走ってはいけません。)/Don\'t be late.(遅れないでね。)\n【〜しよう(さそい)】Let\'s + 動詞の原形.\nLet\'s play soccer.(サッカーをしよう。)— Yes, let\'s.(うん、そうしよう。)/ OK.(いいよ。)\nLet\'s は let us をちぢめた形で、「私たちに〜させて」から「〜しよう」という意味になりました。\n命令文・Don\'t・Let\'s の後ろは、どれも動詞の原形です。',
        ex: [{ q: '次の日本文を英語にしよう。(1) この部屋で写真をとってはいけません。(2) いっしょに昼食を食べよう。', hint: '「〜してはいけない」は Don\'t、「〜しよう」は Let\'s で始めます。', steps: ['(1)「〜してはいけない」は Don\'t + 原形。「写真をとる」は take pictures。', '場所「この部屋で」は in this room。英語では場所を文の最後に置く。', '(2)「〜しよう」は Let\'s + 原形。「昼食を食べる」は have lunch。', '「いっしょに」は together を文の最後に置く。'], a: '(1) Don\'t take pictures in this room. (2) Let\'s have lunch together.', check: 'Don\'t・Let\'s のすぐ後ろが、s も ing もつかない原形になっているか確かめます。' },
          { q: '次の文を、[ ]の指示にしたがって書きかえよう。(1) You are kind to your friends. [命令文に] (2) You use this computer. [「〜してはいけない」の文に]', hint: '命令文は主語の you をとり、動詞を原形にします。are の原形は be です。', steps: ['(1) 命令文にするので主語 You をとる。', '動詞 are を原形 Be にかえて、文の最初に置く → Be kind to your friends.', '(2) 禁止の文なので Don\'t + 原形。主語 You はとる。', 'use はすでに原形なので、Don\'t use this computer. とする。'], a: '(1) Be kind to your friends.(友だちに親切にしなさい。) (2) Don\'t use this computer.(このコンピューターを使ってはいけません。)', check: '(1) で Are kind 〜 としていないか、be動詞の原形 Be になっているかを確かめます。' }] },
      { h: 'もっと深く:can のほかの意味と be able to', t: 'can は【助動詞】です。助動詞には共通のルールがあります。①後ろの動詞は原形、②主語によって形が変わらない(× He cans swim.)、③助動詞は2つ並べない(× will can)。\ncan の意味は「〜できる(能力)」だけではありません。Can I use this pen?(このペンを使ってもいいですか。)のように【許可】、Can you help me?(手伝ってくれますか。)のように【依頼】にも使います。どの意味かは、主語と場面で判断します。\ncan とほぼ同じ意味を表すのが【be able to + 動詞の原形】です。She can swim. = She is able to swim. 。be動詞は主語と時に合わせて変えます。\n助動詞は2つ並べられないので、「〜できるようになるだろう」は will can ではなく【will be able to】と表します。You will be able to ski next winter.(あなたは次の冬にはスキーができるようになるでしょう。)\n命令文に主語がないのは、話している相手(you)に向けた文であることが明らかだからです。be動詞の命令文は原形 Be で始めます:Be careful.(気をつけて。)/Don\'t be late.(おくれないで。)please を文の最後につけるときは、前にコンマを置きます:Open the window, please.', key: '助動詞は後ろが原形・形が変わらない・2つ並べない。「〜できるようになるだろう」は will be able to。' },
      { h: '入試ではこう出る:会話表現の応答と書きかえ', t: '高校入試の対話文では、can を使った【会話表現】と、それへの【応答】がよく問われます。Can you 〜?(〜してくれますか)への応答は、Sure.・OK.・All right.(いいですよ)や Sorry, I can\'t.(ごめんなさい、できません)です。\nCan I 〜?(〜してもいいですか)への応答は、Sure.・Of course.(もちろん)や Sorry, you can\'t. です。お店で店員が言う Can I help you? は「いらっしゃいませ/何かお手伝いしましょうか」の意味です。\n適文選択では、【空所の後ろの応答】が大きなヒントになります。B が Sure. と答えていれば、A は依頼か許可を求める文だと分かります。前後の文を読んで「だれが何をしたいのか」をつかみましょう。\n書きかえでは、can = be able to、You must not 〜 = Don\'t 〜(〜してはいけない)などがねらわれます。will can や can able to のような、助動詞を重ねたまちがいを見ぬけるかも問われます。', key: '空所の後ろの応答(Sure. / Sorry, I can\'t.)から、依頼・許可の文を見つける。will can は不可、will be able to。',
        ex: [{ q: '次の対話の( )に入る最も適切なものを選ぼう。A: I can\'t open this window. It\'s very heavy. (   ) B: Sure. ア Can I use it? イ Can you help me? ウ Let\'s open it. エ Don\'t open it.', hint: 'B の Sure. は何に対する返事かを考えます。', steps: ['A は「この窓を開けられない。とても重い」と困っている。', 'B は Sure.(いいですよ)と引き受けているので、A は何かをたのんでいると考えられる。', 'ア「それを使ってもいいですか」は窓の場面に合わない。ウ「開けよう」、エ「開けないで」は Sure. の応答とつながらない。', 'イ「手伝ってくれますか」は依頼で、Sure. と自然につながる。'], a: 'イ(A:この窓が開けられません。とても重いんです。手伝ってくれますか。B:いいですよ。)', check: 'イを入れて読み直すと、「困っている → 依頼 → 引き受ける」の流れになり、会話が自然につながります。' },
          { q: '日本文に合う英文を書こう。「あなたは来年、上手に泳げるようになるでしょう。」', hint: 'will と can は並べられません。can を別の形で表します。', steps: ['「〜でしょう」は未来なので will を使う。', '「泳げる」は can swim だが、will can とは言えない。', 'can と同じ意味の be able to を使い、will の後ろなので be は原形のまま → will be able to swim。', '「上手に」は well、「来年」は next year を最後に置く。'], a: 'You will be able to swim well next year.', check: 'will の後ろが原形 be になっているか、助動詞が1つだけかを確認します。' }] }
    ],
    faq: [
      ['命令文に主語がないのはなぜ?', '命令は目の前の相手(you)に言うものなので、主語を言わなくてもだれに言っているかが分かるからです。\nYou be quiet. のように言うのは、ふつうの英文としてはまちがいと考えましょう。'],
      ['cannot と can\'t はどちらを使えばいいの?', 'どちらも正しい英語です。can\'t は会話やくだけた文、cannot は書いた文でよく使われます。\nテストではどちらで書いてもかまいませんが、can not と2語にするのはさけたほうが安全です。'],
      ['Let\'s の答え方は?', '賛成なら Yes, let\'s.(そうしよう。)や OK. / Sure. と答えます。\n断るときは No, let\'s not.(やめておこう。)や Sorry, I can\'t.(ごめん、できないんだ。)と言います。'],
      ['Can you 〜? と Will you 〜? は、どちらも「〜してくれますか」なの?', 'どちらも依頼に使えます。Can you 〜? は「〜できる?」というニュアンスで、気軽にたのむときによく使います。Will you 〜? は「〜してくれる?」と相手の意思をたずねる言い方です。\nもっとていねいにたのむときは、Could you 〜? や Would you 〜? を使います。目上の人やお店の人には、こちらがふさわしい場面が多いです。']
    ],
    drill: [
      { lv: 1, q: '日本文に合う英文を書こう。「私の妹は自転車に乗れません。」', a: 'My sister can\'t(cannot)ride a bike.', exp: '「〜できない」は can\'t(cannot)+ 動詞の原形です。主語が3人称単数でも、can も ride も形は変わりません。\n「自転車に乗る」は ride a bike(bicycle)。cannot は1語でつづる点にも注意しましょう。' },
      { lv: 1, q: 'You are quiet in the library. を「図書館では静かにしなさい」という命令文にしよう。', a: 'Be quiet in the library.', exp: '命令文は主語 You をとり、動詞の原形で始めます。are の原形は be なので、Be で始めます。\nquiet(静かな)は形容詞なので、動詞の役目は Be がはたしています。× Quiet in the library. は動詞がないので正しくありません。' },
      { lv: 2, q: 'Can your father cook well? に Yes で答えよう。', a: 'Yes, he can.', exp: 'can の疑問文には can を使って答えます。your father は代名詞 he にかえます。\nYes, he does. としないよう注意しましょう。疑問文で使っている語(ここでは can)で答えるのが基本です。' },
      { lv: 2, q: '対話が成り立つように( )に適する語を1語ずつ入れよう。A: (   ) (   ) use your dictionary? B: Sure. Here you are.(A:あなたの辞書を使ってもいいですか。B:いいですよ。はい、どうぞ。)', a: 'Can / I', exp: '「〜してもいいですか」と許可を求めるときは Can I 〜? を使います。\nB の Sure.(いいですよ)と Here you are.(はい、どうぞ)は、許可をあたえてものを手わたすときの決まった応答です。\nCan you 〜? にすると「(あなたが)〜してくれますか」という依頼になり、「あなたの辞書を使う」のは相手ではなく自分なので合いません。' },
      { lv: 3, q: '2つの文がほぼ同じ意味になるように、( )に適する語を1語ずつ入れよう。Tom can play the guitar well. → Tom is (   ) (   ) play the guitar well.', a: 'able / to', exp: 'can は be able to + 動詞の原形で言いかえられます。\n主語 Tom と現在の文に合わせて be動詞は is になっているので、残りの2語は able to です。\nこの言いかえは、will be able to(〜できるようになるだろう)を作るときの土台になります。' },
      { lv: 3, q: '次の文には誤りが2か所あります。正しく直して全文を書こう。Let\'s playing baseball after school, and don\'t late.', a: 'Let\'s play baseball after school, and don\'t be late.(放課後に野球をしよう。それから、おくれないでね。)', exp: 'Let\'s の後ろは動詞の原形です。playing ではなく play にします。\n「おくれないで」は late(おくれた)という形容詞を使うので、動詞 be が必要です。Don\'t の後ろに be を入れて don\'t be late とします。\nLet\'s・Don\'t の後ろは「原形」というルールと、形容詞を使う命令文には be が必要、というルールが組み合わさった問題です。' }
    ],
    terms: [['助動詞', 'can・will・must など、動詞の前に置いて意味をつけ足すことば'], ['cannot(can\'t)', 'can の否定形。「〜できない」'], ['依頼', '「〜してくれますか」と相手にお願いすること(Can you 〜?)'], ['許可', '「〜してもいいですか」と相手にたずねること(Can I 〜?)'], ['命令文', '主語を省いて動詞の原形で始める文。「〜しなさい」'], ['Let\'s 〜', '「〜しよう」とさそう表現']],
    miss: ['can の後ろの動詞に s をつける(× He can plays.)。主語 he に引っぱられるのが原因です。can を見たら「後ろは原形」と確認しましょう。', 'Do you can 〜? のように do と can を並べる(○ Can you 〜?)。can 自身が疑問文を作るので、do は不要です。', 'be動詞の命令文を Are quiet. とする(○ Be quiet.)。命令文は原形で始めるので、are・is の原形 be を使います。', 'Don\'t の後ろを ing形にする(× Don\'t running.)。Don\'t の後ろも原形です。'],
    sum: ['can + 動詞の原形で「〜できる」。主語が何でも形は同じ。', '否定文は cannot・can\'t、疑問文は Can を主語の前へ。do・does は使わない。', 'Can you 〜? は依頼、Can I 〜? は許可。', '命令文は動詞の原形で始める。be動詞なら Be。', 'Don\'t + 原形で「〜するな」、Let\'s + 原形で「〜しよう」。'],
    next: '次は「疑問詞」(e_wh)へ進みましょう。Yes・No では答えられない「何」「どこ」「いつ」などのたずね方を学び、ここまでの疑問文の作り方を総まとめします。'
  };
  L.e_wh = {
    goal: '何をたずねたいか(もの・人・場所・時・理由・数など)に合わせて疑問詞を選び、正しい語順で疑問文を作れるようになる。',
    intro: 'Do you live in Osaka?(大阪に住んでいますか。)には Yes・No で答えられます。でも「どこに住んでいるの?」と知りたいときは、Where(どこ)のような【疑問詞】を使います。疑問詞の文を作るコツは、【答えの文から逆算すること】です。',
    pre: 'これまでに学んだ疑問文は、すべて Yes・No で答える疑問文でした。作り方は3通りです。\n①be動詞の文:be動詞を主語の前へ(Is this a map?)\n②一般動詞の文:Do・Does を文の最初へ、動詞は原形(Do you live in Osaka? / Does he play tennis?)\n③can の文:can を主語の前へ(Can you swim?)\nこの単元では、これらの疑問文の前に「疑問詞」を1つ置くだけで、新しい疑問文が作れます。①〜③の作り方があやしい人は、先に復習しておきましょう。',
    secs: [
      { h: '疑問詞とは', t: 'Yes・No で答える疑問文は、「そうかどうか」しかたずねられません。\n「何?」「だれ?」「どこ?」のように、具体的な内容を知りたいときに使うことばを【疑問詞】といいます。\n疑問詞の多くは wh で始まるので、疑問詞の文は「wh 疑問文」とも呼ばれます。\n疑問詞の文には、Yes・No では答えません。たずねられた内容そのもの(物の名前・場所・時間など)を答えます。\nWhere do you live?(どこに住んでいますか。)— I live in Osaka.(大阪に住んでいます。)',
        key: '疑問詞の文には Yes・No で答えず、たずねられた内容を答える。' },
      { h: 'もの・人をたずねる what・who・whose・which', t: '【What】何:What is this?(これは何ですか。)— It\'s a map.(地図です。)\n【Who】だれ:Who is that boy?(あの男の子はだれですか。)— He\'s my brother.(私の兄[弟]です。)\n【Whose】だれの:Whose bag is this?(これはだれのかばんですか。)— It\'s mine.(私のです。)\nWhose は後ろに名詞をつけて「だれの〜」というかたまりで使うことが多いです。mine は「私のもの」という意味です。\n【Which】どちら・どれ(決まった選択肢から選ぶ):Which do you like, tea or coffee?(紅茶とコーヒーでは、どちらが好きですか。)— I like tea.(紅茶が好きです。)' },
      { h: '場所・時・理由・方法をたずねる where・when・why・how', t: '【Where】どこ:Where is my cap?(私の帽子はどこですか。)— It\'s on the bed.(ベッドの上です。)\n【When】いつ:When is your birthday?(誕生日はいつですか。)— It\'s May 5.(5月5日です。)\n【Why】なぜ:Why do you like summer?(なぜ夏が好きなのですか。)— Because I can swim in the sea.(海で泳げるからです。)\nWhy の答えは、Because 〜(〜だから)で始めることが多いです。\n【How】どのように・どうやって:How do you go to school?(どうやって学校に行きますか。)— By bike.(自転車です。)\nHow には「どんな具合」という意味もあります。How are you?(元気ですか。)— I\'m fine.(元気です。)' },
      { h: '語順のルール', t: '基本は【疑問詞 + ふつうの疑問文の語順】です。疑問詞を文の先頭に置き、その後ろは Yes・No でたずねる疑問文と同じ形にします。\nbe動詞の文:Is this a map? → What is this?\n一般動詞の文:Do you live in Osaka? → Where do you live?\n3単現の文:Does he play tennis? → What does he play?(彼は何をしますか。)\ncan の文:Can you see a bird? → What can you see?(何が見えますか。)\nたずねる部分(上の例では a map・in Osaka・tennis・a bird)は疑問詞にかわって前に出たので、後ろには書きません。',
        key: '疑問詞を先頭に置き、後ろはふつうの疑問文の語順にする。',
        ex: [{ q: '【 】の部分をたずねる疑問文を作ろう。(1) I play 【tennis】 after school. (2) He lives 【in Kyoto】.', hint: '①【 】を疑問詞にかえる → ②残りを疑問文の語順にする、の2段階で作ります。', steps: ['(1) tennis は「何」にあたる → What。', '残りの I play after school を疑問文にすると do you play after school(I は相手にたずねるので you にかわる)→ What do you play after school?', '(2) in Kyoto は「場所」にあたる → Where。', '主語 He は3人称単数なので does を使い、lives は原形 live にもどす → Where does he live?'], a: '(1) What do you play after school?(あなたは放課後に何をしますか。) (2) Where does he live?(彼はどこに住んでいますか。)', check: '作った疑問文にもとの文で答えると、【 】の部分がちょうど答えになることを確かめます。' }] },
      { h: '疑問詞が主語のとき', t: '「だれが〜しますか」「何が〜ですか」のように、【疑問詞そのものが主語】になることがあります。\nこのときは do・does を使わず、【疑問詞のすぐ後ろに動詞】を置きます。主語がもう文の先頭にあるので、語順を変える必要がないからです。\n疑問詞の主語は3人称単数として扱うので、現在の文では動詞に s がつきます。\nWho plays the piano?(だれがピアノをひきますか。)— Mary does.(メアリーです。)\n答えは「主語 + do・does」の形で短く言います。Who can swim?(だれが泳げますか。)— Ken can.(ケンです。)',
        ex: [{ q: '日本文に合う英文を書こう。「だれが毎朝この部屋をそうじしますか。— 私の父です。」', hint: '「だれが」は主語です。主語の疑問詞の後ろには、すぐ動詞を置きます。', steps: ['「だれが」は主語なので Who を先頭に置き、すぐ後ろに動詞を続ける。do・does は使わない。', '疑問詞の主語は3人称単数あつかい → clean に s をつけて cleans。', '「この部屋を」this room、「毎朝」every morning を後ろに置く → Who cleans this room every morning?', '答えは「主語 + does」で短く → My father does.'], a: 'Who cleans this room every morning? — My father does.', check: '答えの My father を Who の位置に入れると My father cleans this room every morning. という正しい文になることを確かめます。' }] },
      { h: 'How・What を使ったかたまり', t: '【How many + 名詞の複数形】いくつ(数):How many pens do you have?(ペンを何本持っていますか。)— I have three.(3本です。)\n【How much】いくら(値段)・どのくらい(量):How much is this cap?(この帽子はいくらですか。)— It\'s 2,000 yen.(2000円です。)\n【How old】何歳:How old are you?(何歳ですか。)— I\'m thirteen.(13歳です。)/【How tall】どのくらいの高さ:How tall is your father?(お父さんの身長はどのくらいですか。)\n【What time】何時:What time is it?(何時ですか。)— It\'s seven.(7時です。)/【What + 名詞】何の〜:What sport do you like?(何のスポーツが好きですか。)\nこれらは2語で1つの疑問詞のように働くので、【かたまりのまま文の先頭】に置きます。\nHow many と How much のちがい:数えられるもの(ペン・本・人など)の「数」は How many、値段や数えられないもの(水・お金など)の「量」は How much です。',
        ex: [{ q: '( )に入る2語は? (1) (   ) (   ) brothers do you have? — I have two. (2) (   ) (   ) is this bag? — It\'s 3,000 yen.', hint: '答えの文が「数」なのか「値段」なのかを見ます。', steps: ['(1) 答えが「2人」という数。', 'brothers は数えられる名詞の複数形 → 数をたずねる How many。', '(2) 答えが「3000円」という値段 → 値段をたずねる How much。'], a: '(1) How many(兄弟は何人いますか。— 2人です。) (2) How much(このかばんはいくらですか。— 3000円です。)', check: '(1) の How many の後ろの名詞が複数形 brothers になっていることも確かめます。' },
          { q: '次の答えになるような疑問文を作ろう。(1) — It\'s Tuesday today.(今日は火曜日です。) (2) — I like blue.(青が好きです。)', hint: '曜日をたずねるときは What day、色をたずねるときは What color を使います。', steps: ['(1) 曜日をたずねるかたまりは What day。be動詞の文なので What day + is it + today? の語順にする。', '曜日・時刻・天気などを言うときの主語は it を使うので、疑問文も is it になる。', '(2) 「何色」は What color。like は一般動詞で、主語は you。', 'What color + do you like? の語順にする。'], a: '(1) What day is it today?(今日は何曜日ですか。) (2) What color do you like?(あなたは何色が好きですか。)', check: '(2) の疑問文に I like blue. で答えたとき、blue が What color の位置にあてはまることを確かめます。' }] },
      { h: 'もっと深く:疑問詞の疑問文ができるしくみ', t: '疑問詞の疑問文は、【ふつうの疑問文の前に疑問詞を置いた形】です。He lives in Kyoto. の in Kyoto(場所)をたずねるなら、①疑問文 Does he live in Kyoto? を作る、②たずねたい in Kyoto を消す、③場所の疑問詞 Where を文頭に置く、の3段階で Where does he live? ができます。\n疑問詞が【主語】のときは、もともと主語が文頭にあるので、②③で順番が変わりません。Who plays the piano?(だれがピアノをひきますか。)のように、ふつうの文と同じ語順になり、do・does は使いません。疑問詞の主語は3人称単数あつかいなので、動詞に s がつきます。\nWhat color・Which bus・Whose bag・How many books のように、疑問詞と名詞が【かたまり】になることもあります。このときは、かたまりごと文頭に出します。× What do you like color? ではなく、What color do you like? です。\n疑問詞の疑問文には、Yes・No では答えません。たずねられた部分を答えます。読むときは、Yes・No で答える疑問文は文末を上げ調子、疑問詞の疑問文はふつう下げ調子で読みます。\nWhere are you from?(どこの出身ですか。)のように、前置詞が文の最後に残る形もあります。I am from 〜. の from 〜 の部分をたずねていると考えると、語順が理解できます。', key: '疑問詞の文 = 疑問詞(かたまり)+ ふつうの疑問文。疑問詞が主語なら、ふつうの文の語順で do・does 不要。' },
      { h: '入試ではこう出る:答えから疑問詞を逆算する', t: '高校入試の対話文では、【答えの文から疑問文を作る】問題がよく出ます。答えの中心になっている情報が何の種類かを見て、疑問詞を決めましょう。\n代表的な組み合わせ:時刻 → What time、日付・時 → When、場所 → Where、手段(By bus.)→ How、理由(Because 〜.)→ Why、数(Two.)→ How many + 複数名詞、値段 → How much、期間(For two hours.)→ How long、回数・頻度(Three times a week.)→ How often(How many times)。\n次に、【時と主語】を答えに合わせます。答えが過去形なら did、3人称単数の主語なら does、be動詞の文なら be動詞を使います。\nリスニングでも、質問の最初の疑問詞を聞きのがすと答えを選べません。問題用紙の選択肢を先に見て、「時刻が並んでいるから What time の質問だ」と予想しておくと、聞き取りが楽になります。\nひっかけとして、How many の後ろの名詞を単数のままにする、疑問詞が主語なのに do を入れる、などのまちがいがねらわれます。', key: '答えの情報の種類で疑問詞を決め、時と主語を答えに合わせる。How many の後ろは複数名詞。',
        ex: [{ q: '対話が成り立つように、( )に適する語を1語ずつ入れよう。(1) A: (   ) (   ) do you practice the piano? B: Three times a week. (2) A: (   ) bike is this? B: It\'s my brother\'s.', hint: 'B の答えが「何の情報」かを見て、疑問詞を決めます。', steps: ['(1) B は Three times a week.(週に3回)と回数・頻度を答えている。', '頻度をたずねる2語は How often。How many times でも意味は通じるが3語になるので、空所の数に合わない。', '(2) B は my brother\'s(兄[弟]のもの)と持ち主を答えている。', '持ち主をたずねる疑問詞は Whose。後ろの bike とかたまりになって Whose bike となる。'], a: '(1) How / often(A:あなたはどのくらいの頻度でピアノを練習しますか。B:週に3回です。) (2) Whose(A:これはだれの自転車ですか。B:私の兄[弟]のです。)', check: 'それぞれ答えの文に疑問詞の意味を当てはめると、「どのくらいの頻度で → 週に3回」「だれの → 兄[弟]の」と対応します。' }] }
    ],
    faq: [
      ['Where do you live? の do には意味があるの?', 'この do には「する」という意味はありません。「これは一般動詞の疑問文です」と知らせるしるしの役目をしています。\nだから日本語には訳さず、主語が3人称単数なら does、過去なら did に形が変わります。'],
      ['What と Which はどう使い分けるの?', '選択肢が決まっていないときは What、「A と B のどちら」のように選択肢が決まっているときは Which を使います。\nWhat fruit do you like?(何の果物が好き?)/Which fruit do you like, apples or oranges?(りんごとオレンジ、どちらが好き?)'],
      ['Who plays 〜? の答えが Mary does. になるのはなぜ?', 'Mary plays the piano. の plays the piano をくり返さないように、does 1語で代わりをさせているからです。\nMary. とだけ答えても会話では通じますが、テストでは Mary does. の形がよく問われます。'],
      ['What time と When は、どう使い分けるの?', 'What time は「何時に」と、時刻だけをたずねます。答えは at seven のような時刻です。\nWhen は「いつ」と、時刻・日付・曜日・季節など、時を広くたずねます。When is your birthday? — It\'s May 5. のように、時刻以外の答えも来ます。\n時刻をたずねるときは When も使えますが、時刻をはっきり聞きたいなら What time を使うのが確実です。']
    ],
    drill: [
      { lv: 1, q: '( )に適する疑問詞を入れよう。(1) (   ) is your birthday? — It\'s May 5. (2) (   ) is that girl? — She is my cousin.', a: '(1) When (2) Who', exp: '(1) 答えが May 5(5月5日)という日付なので、「いつ」をたずねる When です。\n(2) 答えが my cousin(私のいとこ)と、その人がだれかを答えているので Who です。\n疑問詞は、答えの文の中心の情報を見て決めます。' },
      { lv: 1, q: '( )に適する疑問詞を入れよう。(   ) do you go to school? — By bike.', a: 'How', exp: 'By bike(自転車で)は、学校へ行く手段・方法の答えです。\n手段・方法をたずねるのは How(どうやって)です。By 〜 の答えを見たら How を思い出しましょう。' },
      { lv: 2, q: '【 】の部分をたずねる疑問文を作ろう。Ken gets up 【at six】.', a: 'What time does Ken get up?', exp: 'at six(6時に)は時刻なので、What time を使います。\n次に、Ken gets up. を疑問文にすると Does Ken get up? 。その前に What time を置きます。\ndoes を使うので、gets は原形 get にもどします。When does Ken get up? も文法的には正しいですが、時刻をたずねるなら What time がもっとも適切です。' },
      { lv: 2, q: '日本文に合う英文を書こう。「あなたは、赤いかばんと青いかばんのどちらがほしいですか。」', a: 'Which bag do you want, the red one or the blue one?', exp: '決まったものの中から「どちら」と選ばせるときは Which を使います。Which bag とかたまりにして文頭に置きます。\n後ろに do you want を続け、コンマのあとに選択肢を A or B の形で示します。\none は、くり返しをさけるために bag のかわりに使う語です。the red bag or the blue bag と書いても正しい英文です。' },
      { lv: 3, q: '【 】の部分をたずねる疑問文を作ろう。【My mother】 made this cake.', a: 'Who made this cake?', exp: 'My mother は文の主語なので、主語をたずねる疑問文になります。\n疑問詞が主語のときは、ふつうの文と同じ語順で、主語の部分を Who にかえるだけです。did は使いません。\n× Who did make this cake? や × Who did your mother make? は、主語をたずねる形としては誤りです。答えは My mother did. のようになります。' },
      { lv: 3, q: '次の文には誤りが2か所あります。正しく直して全文を書こう。How many book does your sister has?', a: 'How many books does your sister have?(あなたのお姉さん[妹さん]は本を何冊持っていますか。)', exp: 'How many の後ろには、数えられる名詞の【複数形】が来ます。book を books にします。\nまた、does を使った疑問文なので、後ろの動詞は原形です。has を have にします。\nHow many + 複数名詞 と、does の後ろは原形、という2つのルールがどちらも入試でよくねらわれます。' }
    ],
    terms: [['疑問詞', 'what・who・where など、具体的な内容をたずねることば'], ['Whose', '「だれの」と持ち主をたずねる'], ['Which', '決まった選択肢の中から「どちら・どれ」とたずねる'], ['How many', '数をたずねる。後ろの名詞は複数形'], ['How much', '値段や量をたずねる'], ['Because 〜', 'Why の質問に「〜だから」と理由を答えるときに使う']],
    miss: ['Where you live? のように do・does を忘れる(○ Where do you live?)。疑問詞の後ろは「ふつうの疑問文」と覚え、Do you live 〜? を先に作ってから疑問詞をつけましょう。', 'How many の後ろの名詞を単数にする(× How many book → ○ How many books)。数が1つとは限らないので複数形にします。', '疑問詞の文に Yes・No で答える。疑問詞の文は内容をたずねているので、その内容を答えます。', '疑問詞が主語なのに do を入れる(× Who does play the piano? → ○ Who plays the piano?)。「だれが」「何が」のときは疑問詞のすぐ後ろが動詞です。'],
    sum: ['疑問詞は文の先頭。後ろはふつうの疑問文の語順。', '答えの文を見て、何をたずねているかを考えて疑問詞を選ぶ。', 'How many + 複数名詞は数、How much は値段・量。', 'What time・What day・What color などはかたまりで先頭へ。', '疑問詞が主語なら「疑問詞 + 動詞」の順で、do・does は使わない。'],
    next: '次は「過去形」(e_m2)へ進みましょう。「〜した」と過去のことを言う文と、did を使った否定文・疑問文を学びます。疑問詞と組み合わせた What did you do? もよく使います。'
  };
  L.e_m2 = {
    goal: '一般動詞と be動詞の過去形を正しく作り、did・was・were を使った否定文・疑問文を書けるようになる。',
    intro: '「きのうテニスをした」のように過去のことを言うときは、動詞を【過去形】にします。日本語の「〜した」にあたる部分です。一般動詞の過去の否定文・疑問文では【did】が「過去」の役目を引き受けるので、動詞は原形にもどります。この役割分担がこの単元のいちばんのポイントです。',
    pre: '現在の文では、一般動詞の否定文・疑問文を do・does で作りました。He doesn\'t play tennis. / Does he play tennis? のように、does を使うと後ろの動詞は原形にもどりました。\nこれは、does が「3人称単数・現在」というしるしを引き受けてくれるからでした。この単元の did も、同じように「過去」というしるしを引き受けます。\nbe動詞の文は、否定文は be動詞の後ろに not、疑問文は be動詞を前に出して作りました。過去の文でもこのしくみは変わりません。\n英語の動詞には「原形(play)」「3単現(plays)」「ing形(playing)」などの形がありました。この単元では「過去形(played)」が加わります。',
    secs: [
      { h: '過去形とは', t: '英語では、いつのことかによって動詞の形を変えます。これを【時制】といいます。\n今のことやふだんのことは現在形(I play tennis.)、過去のことは【過去形】(I played tennis.)で表します。\n日本語では「する」→「した」と語尾を変えますが、英語では動詞そのものの形を変えます。\n過去形は、【主語が何でも同じ形】です。現在形の3単現の s のような、主語による変化はありません。\nI went to Kyoto yesterday.(私はきのう京都へ行きました。)/She went to Kyoto last week.(彼女は先週京都へ行きました。)',
        key: '過去のことは動詞を過去形にする。過去形は主語が何でも同じ形。' },
      { h: '規則動詞:ed をつける', t: '語の最後に ed をつけて過去形を作る動詞を【規則動詞】といいます。\n・ふつうは ed:play → played、watch → watched\n・e で終わる語は d だけ:live → lived、use → used\n・「子音字 + y」は y を i にかえて ed:study → studied、try → tried\n・「短い母音 + 子音字1つ」は最後の文字を重ねて ed:stop → stopped、plan → planned\ned の発音は3通りあります。played(ド)、watched(トゥ)、wanted(ティッド)。t・d で終わる語の後では「イッド」と1音ふえます。',
        ex: [{ q: '次の動詞を過去形にしよう。(1) stop (2) study (3) like (4) enjoy', hint: '最後の文字が e か、y か、「短い母音 + 子音字1つ」かを確認します。', steps: ['(1) stop は「短い母音 o + 子音字 p」で終わる → p を重ねて stopped。', '(2) study は「子音字 d + y」で終わる → y を i にかえて studied。', '(3) like は e で終わる → d だけつけて liked。', '(4) enjoy は「母音字 o + y」で終わる → y はそのままで enjoyed。'], a: '(1) stopped (2) studied (3) liked (4) enjoyed', check: '-ing形と比べると、stop → stopping、study → studying のように、ing では y を i にかえないことも確認しておきます。' }] },
      { h: '不規則動詞:1語ずつ覚える', t: 'ed をつけず、形が不規則に変わる動詞を【不規則動詞】といいます。よく使う動詞ほど不規則なことが多いです。\ngo → went、come → came、see → saw、have → had、eat → ate、get → got、make → made、buy → bought\nread → read は、つづりは同じで、発音が「リード」から「レッド」に変わります。\n不規則動詞はルールで作れないので、声に出して何度もくり返して覚えるのがいちばんの近道です。',
        ex: [{ q: '( )内の動詞を過去形にして、文を完成させよう。(1) I (go) to the zoo last Sunday. (2) We (have) a good time. (3) My sister (make) a cake.', hint: 'どれも不規則動詞です。ed をつけないように注意します。', steps: ['last Sunday(この前の日曜日)があるので過去の文。(1) go は不規則動詞 → went。', '(2) have は不規則動詞 → had。', '(3) make は不規則動詞 → made。主語 my sister でも過去形は同じ形。'], a: '(1) went(私はこの前の日曜日に動物園へ行きました。) (2) had(私たちは楽しい時間を過ごしました。) (3) made(姉[妹]はケーキを作りました。)', check: 'goed・haved・maked のように ed をつけていないか確かめます。' }] },
      { h: 'be動詞の過去形 was・were', t: 'am・is の過去形は【was】、are の過去形は【were】です。\nI was busy yesterday.(私はきのういそがしかった。)/They were in the park then.(彼らはそのとき公園にいました。)\n否定文:be動詞の後ろに not → was not(wasn\'t)/were not(weren\'t)\nI wasn\'t busy yesterday.(私はきのういそがしくなかった。)\n疑問文:be動詞を主語の前へ → Was he at home?(彼は家にいましたか。)— Yes, he was. / No, he wasn\'t.\nyou は1人でも were を使います(現在形で are を使うのと同じ)。You were late.(あなたは遅刻しました。)',
        key: 'am・is → was、are → were。be動詞の過去の文に did は使わない。' },
      { h: '一般動詞の過去の否定文・疑問文', t: '【否定文】主語 + did not(didn\'t) + 動詞の原形。主語が何でも did です。\nHe watched TV last night. → He didn\'t watch TV last night.(彼は昨夜テレビを見ませんでした。)\n【疑問文】Did + 主語 + 動詞の原形 〜?\nDid he watch TV last night?(彼は昨夜テレビを見ましたか。)— Yes, he did. / No, he didn\'t.\n原形にもどす理由:【did が「過去」を引き受けてくれる】ので、動詞はもとの形でよいのです。過去のしるしは1つの文に1回だけです。\n疑問詞を使うと:What did you do yesterday?(きのうは何をしましたか。)— I played tennis.(テニスをしました。)',
        key: 'didn\'t・Did の後ろは必ず動詞の原形。過去のしるしは did が引き受ける。',
        ex: [{ q: 'Mai bought a new bag.(マイは新しいかばんを買いました。)を否定文と疑問文にしよう。', hint: 'bought のもとの形(原形)は何かを、まず考えます。', steps: ['bought は buy の過去形。一般動詞の過去の文なので did を使う。', '否定文:didn\'t の後ろは原形 → Mai didn\'t buy a new bag.', '疑問文:Did + Mai + buy 〜? → Did Mai buy a new bag?', '答え方:Mai を she にかえて Yes, she did. / No, she didn\'t.'], a: '否定文:Mai didn\'t buy a new bag.(マイは新しいかばんを買いませんでした。)/疑問文:Did Mai buy a new bag?(マイは新しいかばんを買いましたか。)— Yes, she did. / No, she didn\'t.', check: '文の中に過去のしるし(did か過去形)が1つだけになっているか数えて確かめます。' }] },
      { h: '過去を表すことば', t: '次のことばがあれば、過去形を使う目じるしです。\n【yesterday】きのう、【last 〜】この前の〜(last night 昨夜、last week 先週、last Sunday この前の日曜日)\n【〜 ago】〜前(two days ago 2日前、three years ago 3年前)、【then / at that time】そのとき、【in + 過去の年】(in 2020 など)\nlast や ago の前には in・on をつけません。× on last Sunday → ○ last Sunday\nまた、文の中にこうした語がなくても、話の流れで過去のことなら過去形を使います。',
        ex: [{ q: '日本文に合う英文を書こう。「あなたは3日前にどこへ行きましたか。— 私は祖母の家へ行きました。」', hint: '疑問詞 Where + 一般動詞の過去の疑問文(did + 主語 + 原形)の形です。', steps: ['「どこへ」は Where。一般動詞の過去の疑問文なので Where + did + you + 原形 go の順。', '「3日前に」は three days ago。ago の前に in はつけず、文の最後に置く → Where did you go three days ago?', '答えは過去の肯定文なので go の過去形 went を使う。', '「祖母の家へ」は to my grandmother\'s house → I went to my grandmother\'s house.'], a: 'Where did you go three days ago? — I went to my grandmother\'s house.', check: '疑問文では原形 go、答えでは過去形 went になっているか確かめます。' }] },
      { h: 'もっと深く:-ed の発音と、不規則動詞のグループ', t: '規則動詞の ed の発音は3通りです。①【/id/(イド)】:原形が t・d の音で終わる語(wanted・needed・visited)。②【/t/(ト)】:原形が k・p・s・ch・sh などのにごらない音で終わる語(looked・stopped・watched)。③【/d/(ド)】:それ以外のにごる音や母音で終わる語(played・lived・used)。\nつづりのルールは三単現の s と似ています。「子音字 + y」は y を i にかえて ed(study → studied)、「母音字 + y」はそのまま ed(play → played)。stop → stopped、plan → planned のように、「短い母音 + 子音字1つ」で終わり、そこを強く読む語は最後の文字を重ねます。visit は前を強く読むので visited です。\n不規則動詞は、グループで覚えると楽になります。母音が変わる型(come → came、run → ran、get → got、write → wrote)、-ought・-aught になる型(buy → bought、think → thought、bring → brought、teach → taught、catch → caught)、形が変わらない型(put → put、cut → cut、read → read)などです。read は形は同じでも、過去形は「レッド」と発音します。\n過去形は、【今とは切り離された過去のこと】を表します。I lived in Osaka. は「(以前)大阪に住んでいた」ことで、ふつう「今は住んでいない」ことをふくみます。今とつながる言い方は、中3で学ぶ現在完了で表します。', key: 'ed の発音は /id/・/t/・/d/ の3通り。不規則動詞はグループで覚える。過去形は今と切り離された過去。' },
      { h: '入試ではこう出る:時の合図と did の後ろ', t: '高校入試の語形変化や適語補充では、まず【時の合図】を探します。yesterday、last 〜(last week・last Sunday)、〜 ago(two days ago)、then、at that time、when I was a child などがあれば、過去形を使います。\nひっかけの典型は3つです。①Did・didn\'t の後ろに過去形を使う(× Did you went?)。②主語が3人称単数なので s をつけてしまう(過去形には s はつきません)。③be動詞の過去を選ぶとき、you に was を使う(you は単数でも were)。\n長文読解では、物語や体験談は過去形で進みます。found・felt・left・thought などの過去形を見て、すぐに find・feel・leave・think と原形が分かることが、読むスピードに直結します。\n英作文では、日記や思い出を書く問題がよく出ます。I went to 〜 with 〜. I enjoyed 〜ing. It was 〜. のように、過去形で書き通し、途中で現在形にもどらないよう注意しましょう。', key: '過去の合図を見つけたら過去形。Did・didn\'t の後ろは原形、you は単数でも were。',
        ex: [{ q: '( )内の語を適する形にかえよう。(2) は2つの語をそれぞれかえる。(1) Ken (lose) his umbrella two days ago. (2) (Do) you (see) Mr. Sato at the station yesterday? (3) I was very tired, so I (sleep) for ten hours last night.', hint: 'まず時の合図を探し、次に文の中に did があるかを確認します。', steps: ['(1) two days ago(2日前)があるので過去。lose は不規則動詞で過去形は lost。', '(2) yesterday があるので過去の疑問文。Do を Did にする。Did を使ったら後ろは原形なので see のまま。', '(3) last night と was があるので過去。sleep は不規則動詞で過去形は slept。', '最後に、did のある文の動詞が原形、ない文の動詞が過去形になっているかを確認する。'], a: '(1) lost(ケンは2日前にかさをなくしました。) (2) Did / see(あなたはきのう駅で佐藤先生に会いましたか。) (3) slept(私はとてもつかれていたので、昨夜は10時間ねむりました。)', check: '(2) を肯定文にもどすと You saw Mr. Sato 〜 となり、過去を表す形が did に移っていたと確かめられます。' }] }
    ],
    faq: [
      ['なぜ Did you went? はだめなの?', 'did がすでに「過去」のしるしを持っているからです。went にもしるしがあるので、2回重なってしまいます。\nDid を使ったら動詞は原形、と決めておきましょう。'],
      ['不規則動詞はいくつ覚えればいいの?', '中学校でよく使う不規則動詞は60〜70語ほどです。一度に覚えず、教科書に出てきたものから順に覚えていきましょう。\ngo・come・see・have・make・take・get・buy など、毎日使う動詞から始めると効率的です。'],
      ['be動詞の過去の文にも did を使えるの?', '使えません。be動詞の文は、過去でも be動詞(was・were)自身で否定文・疑問文を作ります。\n× Did you busy? → ○ Were you busy?(いそがしかったですか。)'],
      ['read の過去形は、なぜつづりが同じなの?', 'read は、過去形でもつづりが read のまま変わらず、発音だけが「リード」から「レッド」に変わる特別な動詞です。put・cut のように形がまったく変わらない動詞の仲間ですが、read は発音だけが変わる点に注意が必要です。\n文の中では、時の合図(yesterday など)や主語で見分けます。He read the book yesterday. の read は、主語が He なのに s がないことからも、過去形だと分かります。']
    ],
    drill: [
      { lv: 1, q: '次の動詞を過去形にしよう。(1) carry (2) plan (3) write', a: '(1) carried (2) planned (3) wrote', exp: '(1) carry は「子音字 + y」で終わるので、y を i にかえて ed をつけます。\n(2) plan は「短い母音 + 子音字1つ」で終わるので、n を重ねて planned。\n(3) write は不規則動詞で、過去形は wrote です。規則動詞のように writed としないよう注意しましょう。' },
      { lv: 1, q: '( )に was か were を入れよう。(1) We (   ) in the same class last year. (2) It (   ) rainy yesterday.', a: '(1) were (2) was', exp: '(1) 主語 We は複数なので were です。(私たちは去年、同じクラスでした。)\n(2) 主語 It は単数なので was です。(きのうは雨でした。)\nam・is の過去形は was、are の過去形は were と覚えましょう。' },
      { lv: 2, q: 'She came home at seven.(彼女は7時に帰宅しました。)を否定文にしよう。', a: 'She didn\'t(did not)come home at seven.', exp: '一般動詞の過去の否定文は、did not(didn\'t)を動詞の前に置きます。主語が何でも didn\'t です。\n過去の意味は didn\'t が引き受けるので、came は原形 come にもどします。× didn\'t came は誤りです。' },
      { lv: 2, q: '【 】の部分をたずねる疑問文を作ろう。They went 【to Nara】 last month.', a: 'Where did they go last month?', exp: 'to Nara(奈良へ)は場所なので、Where を使います。\nThey went 〜. の疑問文は Did they go 〜? 。その前に Where を置き、たずねる部分の to Nara は消します。\ndid を使うので、went は原形 go にもどします。答えは They went to Nara. のようになります。' },
      { lv: 3, q: '下線部の ed の発音が、ほかの3つと異なるものを選ぼう。ア wanted イ needed ウ visited エ looked', a: 'エ', exp: 'wanted・needed・visited は、原形が t か d の音で終わるので、ed を /id/(イド)と読みます。\nlooked は原形 look が k(にごらない音)で終わるので、ed は /t/(ト)と読みます。\n原形の最後の音が t・d なら /id/、にごらない音なら /t/、それ以外なら /d/、の順に判断すると確実です。' },
      { lv: 3, q: '日本文に合う英文を書こう。「あなたは昨夜何時に寝ましたか。— 11時に寝ました。」', a: 'What time did you go to bed last night? — I went to bed at eleven.', exp: '「寝る(床につく)」は go to bed です。時刻をたずねるので What time を文頭に置き、過去の疑問文 did you go to bed を続けます。\n答えの文は過去形なので、go を went にします。did を使わない肯定文では、動詞そのものを過去形にします。\n疑問文では原形 go、答えでは過去形 went、と形が変わる点がこの問題のポイントです。' }
    ],
    terms: [['時制', '現在・過去など、いつのことかを表す動詞の形の区別'], ['過去形', '過去のことを表す動詞の形'], ['規則動詞', 'ed をつけて過去形を作る動詞'], ['不規則動詞', 'go → went のように、形が不規則に変わる動詞'], ['did', '一般動詞の過去の否定文・疑問文で使う語。後ろの動詞は原形'], ['was・were', 'be動詞の過去形。am・is → was、are → were']],
    miss: ['Did you went? のように、did の後ろも過去形にする(○ Did you go?)。過去のしるしは did に1回だけ、と覚えましょう。', 'study を studyed、stop を stoped とする(studied、stopped)。最後の文字を見てから ed のつけ方を決めましょう。', 'You was 〜 とする(you・複数には were)。現在形で are を使う主語には were、と対応させて覚えましょう。', 'be動詞の過去の文に did を使う(× Did he busy? → ○ Was he busy?)。文の中に一般動詞があるかを先に確かめましょう。'],
    sum: ['過去のことは過去形。主語が何でも同じ形。', '規則動詞は ed、不規則動詞は1語ずつ覚える。', 'am・is → was、are → were。', '一般動詞の否定文は didn\'t + 原形、疑問文は Did + 主語 + 原形。', 'yesterday・last 〜・〜 ago は過去形の目じるし。'],
    next: '次は中2の「過去進行形」(e_pprog)へ進みましょう。過去形と現在進行形を組み合わせて、「そのとき〜しているところだった」を表します。'
  };

  // ===== 中2の文法 =====
  L.e_pprog = {
    goal: '「(過去のある時に)〜しているところだった」を was・were + ing形で表し、過去形との意味のちがいを説明できるようになる。',
    intro: '友だちに「きのうの夜9時、何してた?」と聞かれたら、「テレビを見ているところだった」と答えますよね。このように、過去のある時点で【動作の途中だった】ことを表すのが【過去進行形】です。現在進行形の be動詞を過去形にするだけで作れます。',
    pre: '【現在進行形】は「be動詞(am・is・are)+ ing形」で、「今まさに〜しているところ」を表しました。He is reading a book.(彼は本を読んでいます。)\nbe動詞の過去形は、am・is → was、are → were でした。\ning形の作り方:ふつうは ing(play → playing)、e で終わる語は e をとる(make → making)、短い母音 + 子音字1つは重ねる(run → running)。\nlike・know・want などの【状態動詞】は、進行形にしないのでした。このルールは過去進行形でも同じです。',
    secs: [
      { h: '時間の線で考える', t: '過去進行形を理解するには、時間を1本の線で考えるのが分かりやすいです。左が過去、右が今です。\n過去のある時点(たとえば「昨夜9時」)に点を打ちます。その点をはさんで、ある動作が続いていたとします。\nその点では、動作はまだ終わっていません。「その時点では途中だった」ことを表すのが過去進行形です。\n現在進行形は「今」という点で途中、過去進行形は「過去のある点」で途中、と考えるとちがいがはっきりします。',
        key: '過去進行形は「過去のある時点で、動作の途中だった」ことを表す。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="過去進行形を表す時間の線。昨夜9時の点をはさんで動作が続いている"><line x1="10" y1="80" x2="205" y2="80" class="ax"/><path d="M198 75 L206 80 L198 85" class="ax"/><line x1="45" y1="62" x2="140" y2="62" class="cv"/><line x1="92" y1="44" x2="92" y2="80" class="dash"/><circle cx="92" cy="80" r="4" class="pt"/><circle cx="180" cy="80" r="4" class="pt"/><text x="30" y="36">テレビを見ている途中</text><text x="70" y="98">昨夜9時</text><text x="175" y="98">今</text><text x="12" y="98">過去</text><text x="20" y="128">その時点で動作の途中</text></svg>' },
      { h: '過去進行形の形', t: '【was・were + 動詞の ing形】で「(そのとき)〜しているところだった」を表します。\nI・he・she・it など1人・1つの主語 → 【was】、you・複数の主語 → 【were】。\nI was studying at eight last night.(私は昨夜8時に勉強していました。)\nThey were playing soccer then.(彼らはそのときサッカーをしていました。)\ning形の作り方は現在進行形と同じです(make → making、run → running)。',
        ex: [{ q: '( )内の動詞を過去進行形にしよう。(1) I (write) a letter at that time. (2) The children (swim) in the river then.', hint: '主語で was か were かを決め、動詞を ing形にします。', steps: ['(1) 主語 I には was。write は e で終わるので e をとって writing → was writing。', '(2) 主語 the children(子どもたち)は複数なので were。', 'swim は「短い母音 i + 子音字 m」で終わるので m を重ねて swimming → were swimming。'], a: '(1) was writing(私はそのとき手紙を書いていました。) (2) were swimming(子どもたちはそのとき川で泳いでいました。)', check: '主語を代名詞にすると (2) は they になり、they were の組み合わせになることを確かめます。' }] },
      { h: '過去形とのちがい', t: '【過去形】I watched TV last night.(私は昨夜テレビを見ました。)\n→ テレビを見たという動作を、ひとまとまりの「終わったこと」として言っています。\n【過去進行形】I was watching TV at nine last night.(私は昨夜9時にテレビを見ていました。)\n→ 9時という時点で、テレビを見ている「途中」だったことを言っています。その前から見ていて、その後も続いていたかもしれません。\nそのため、過去進行形は then(そのとき)、at that time(そのとき)、at 〜 o\'clock(〜時に)のように、【時点を表すことば】といっしょによく使われます。' },
      { h: '否定文・疑問文の作り方', t: '過去進行形は be動詞を使う文なので、be動詞の文と同じしくみで作ります。did は使いません。\n【否定文】was・were の後ろに not。\nShe was not(wasn\'t) cooking dinner.(彼女は夕食を作っていませんでした。)\n【疑問文】was・were を主語の前に出す。\nWas she cooking dinner?(彼女は夕食を作っていましたか。)— Yes, she was. / No, she wasn\'t.\n疑問詞を使うと:What were you doing at seven?(あなたは7時に何をしていましたか。)— I was taking a bath.(おふろに入っていました。)',
        key: '過去進行形の否定文・疑問文は was・were で作る。did は使わない。',
        ex: [{ q: 'They were running in the park.(彼らは公園で走っていました。)を否定文と疑問文にしよう。', hint: 'be動詞の文なので、were を動かします。', steps: ['be動詞は were(主語 They は複数)。be動詞の文なので did は使わない。', '否定文:were の後ろに not → They were not(weren\'t) running in the park.', '疑問文:were を They の前に出す → Were they running in the park?', '答え方:Yes, they were. / No, they weren\'t.'], a: '否定文:They weren\'t running in the park.(彼らは公園で走っていませんでした。)/疑問文:Were they running in the park?(彼らは公園で走っていましたか。)— Yes, they were. / No, they weren\'t.', check: 'running の形が変わっていないこと(原形にもどさない)を確かめます。' }] },
      { h: 'when といっしょに使う', t: '「〜したとき、…していた」という文では、【長く続いていた動作】を過去進行形、【そこに割りこんだ短い出来事】を過去形で表します。\nI was taking a bath when he called me.(彼が電話をかけてきたとき、私はおふろに入っていました。)\n→ おふろ(続いていた動作)の途中に、電話(短い出来事)が割りこんだ。\nWhen 〜 を文の前に置くときは、区切りにコンマをつけます:When he called me, I was taking a bath.\nどちらが「続いていた動作」かは、日本語の「〜していた」「〜した」で見分けられることが多いです。',
        ex: [{ q: '( )内の動詞を正しい形にしよう。When I got home, my brother (watch) TV.(私が家に帰ったとき、弟はテレビを見ていました。)', hint: '「帰った」と「見ていた」の、どちらが続いていた動作かを考えます。', steps: ['「帰った」は短い出来事で、すでに過去形 got になっている。', '「テレビを見ていた」は、帰ったときに途中だった動作 → 過去進行形。', '主語 my brother は1人なので was。watch → watching。'], a: 'was watching', check: '時間の線を書き、「帰った」の点で「見ている」が途中だったことを確かめます。' },
          { q: '日本文に合う英文を書こう。「雨が降り始めたとき、私たちはテニスをしていました。」', hint: '割りこんだ出来事(雨が降り始めた)は過去形、続いていた動作(テニスをしていた)は過去進行形です。', steps: ['続いていた動作は「テニスをしていた」→ 主語 we なので were playing tennis。', '割りこんだ出来事は「雨が降り始めた」→ 過去形 it started to rain(it は天気を表す主語)。', '「〜したとき」は when でつなぐ。', 'when の部分を後ろに置くならコンマは不要、前に置くならコンマで区切る。'], a: 'We were playing tennis when it started to rain.(= When it started to rain, we were playing tennis.)', check: 'started を was starting にしていないか確かめます。割りこんだ出来事は一瞬なので過去形です。' }] }
    ],
    faq: [
      ['I watched TV at nine. と I was watching TV at nine. は同じ意味?', '少しちがいます。過去形だと「9時に見始めた」ようにも受け取れます。\n過去進行形にすると、「9時の時点で見ている途中だった」ことがはっきり伝わります。'],
      ['Did you watching 〜? はなぜまちがい?', '進行形は be動詞の文だからです。疑問文は be動詞を前に出して Were you watching 〜? とします。\ndid は、一般動詞の過去の文(Did you watch 〜?)のときだけ使います。']
    ],
    terms: [['過去進行形', 'was・were + ing形。「(過去のある時に)〜しているところだった」'], ['時点', '時間の流れの中の、ある1つの点'], ['then', 'そのとき'], ['at that time', 'そのとき(then と同じ意味)'], ['when', '「〜するとき・〜したとき」と2つの文をつなぐことば']],
    miss: ['be動詞を現在形のままにする(× I am watching TV last night.)。last night があるのに is・am・are を使うのは、時制を見落としているからです。過去なら was・were。', '主語が複数なのに was を使う(○ They were 〜)。主語を代名詞に置きかえて確かめましょう。', 'Did you watching 〜? のように did を使う(○ Were you watching 〜?)。ing形があれば be動詞の文です。', 'when の文で、割りこんだ短い出来事まで過去進行形にする。一瞬で終わる出来事は過去形です。'],
    sum: ['過去進行形 = was・were + ing形。', '過去形は「した」、過去進行形は「その時点でしている途中だった」。', '否定文は was・were + not、疑問文は was・were を前へ。did は使わない。', 'What were you doing? で「そのとき何をしていたか」をたずねる。', 'when の文では、続いていた動作が過去進行形、割りこんだ出来事が過去形。'],
    next: '次は「未来形(will・be going to)」(e_fut)へ進みましょう。過去・現在に続いて、これから先のことを表す方法を学びます。'
  };
  L.e_fut = {
    goal: 'will と be going to を使って未来のことを表し、それぞれの肯定文・否定文・疑問文を作れるようになる。',
    intro: '英語の動詞には「未来形」という形の変化はありません。そのかわりに、【will + 動詞の原形】や【be going to + 動詞の原形】を使って、これから先のことを表します。どちらも後ろは原形。be going to は be動詞を忘れやすいので注意しましょう。',
    pre: '【助動詞】は動詞の前に置いて意味をつけ足すことばで、後ろの動詞は必ず原形でした。can(〜できる)がその例です:He can swim.\n助動詞の文の否定文は助動詞の後ろに not、疑問文は助動詞を主語の前に出しました。Can you swim? — Yes, I can.\nbe動詞の文の否定文・疑問文は、be動詞を使って作りました。主語に合わせて am・is・are を使い分けます。\n現在形は習慣、過去形は過去のことを表しました。この単元では「これから」のことを学びます。',
    secs: [
      { h: '英語の「未来」の表し方', t: '英語の動詞は、過去なら played のように形が変わりますが、未来のための形の変化はありません。\nそのかわりに、動詞の前に【will】や【be going to】を置いて、「これから〜する」「〜だろう」という意味を足します。\nI will play tennis tomorrow.(私はあしたテニスをします。)\nI am going to play tennis tomorrow.(私はあしたテニスをする予定です。)\nどちらの場合も、後ろの動詞は【原形】です。',
        key: '未来は will + 原形 か be going to + 原形で表す。後ろはどちらも原形。' },
      { h: 'will + 動詞の原形', t: 'will は can と同じ助動詞です。主語が何でも will の形は変わらず、後ろの動詞は原形です。\n①【予想】〜だろう:It will be sunny tomorrow.(あしたは晴れるでしょう。)\n②【意志】〜します・〜するつもりだ:I will call you tonight.(今夜あなたに電話します。)\n× He wills come. × He will comes. → ○ He will come.(彼は来るでしょう。)\nbe動詞の文を未来にするときは、am・is・are を原形 be にして will be とします。I am busy. → I will be busy tomorrow.(あしたはいそがしいでしょう。)\n短縮形:I will → I\'ll、you will → you\'ll、he will → he\'ll、it will → it\'ll。',
        ex: [{ q: '( )内の語を使って、未来の文に書きかえよう。(1) She is fifteen. (next year / will) (2) My father washes the car. (tomorrow / will)', hint: 'will の後ろは原形。is の原形は be です。', steps: ['(1) will の後ろは原形なので、is を be にかえる → She will be fifteen next year.', '(2) will の後ろは原形なので、washes の es をとって wash にする。', '→ My father will wash the car tomorrow.'], a: '(1) She will be fifteen next year.(彼女は来年15歳になります。) (2) My father will wash the car tomorrow.(父はあした車を洗うでしょう。)', check: 'will の後ろに is・washes など、原形でない形が残っていないか確かめます。' }] },
      { h: 'will の否定文・疑問文', t: '【否定文】will の後ろに not → will not。短縮形は【won\'t】(ウォウント)です。\nHe will not(won\'t) come.(彼は来ないでしょう。)\n【疑問文】will を主語の前へ → Will he come?(彼は来るでしょうか。)\n【答え方】Yes, he will. / No, he won\'t.\n疑問詞を使うと:What will you do this weekend?(今週末は何をしますか。)— I will visit my aunt.(おばを訪ねます。)\nWill you 〜? は「〜してくれますか」という依頼の意味にもなります。Will you open the door?(ドアを開けてくれますか。)',
        ex: [{ q: 'It will rain this afternoon.(午後は雨が降るでしょう。)を否定文と疑問文にしよう。', hint: 'will の文なので、do・does は使いません。', steps: ['will の文なので、否定文・疑問文は will 自身を使って作る。', '否定文:will の後ろに not → It will not(won\'t) rain this afternoon.', '疑問文:will を主語 It の前に出す → Will it rain this afternoon?', '答え方:Yes, it will. / No, it won\'t.'], a: '否定文:It won\'t rain this afternoon.(午後は雨が降らないでしょう。)/疑問文:Will it rain this afternoon?(午後は雨が降るでしょうか。)— Yes, it will. / No, it won\'t.', check: 'will not の短縮形を willn\'t としていないか(正しくは won\'t)確かめます。' }] },
      { h: 'be going to + 動詞の原形', t: '①【前から決めていた予定】〜するつもりだ・〜する予定だ\nI am going to visit my aunt next week.(私は来週おばを訪ねる予定です。)\nShe is going to play tennis tomorrow.(彼女はあしたテニスをするつもりです。)\nbe動詞は主語に合わせて am・is・are を使い分けます。「行く」の go の意味はなく、be going to のかたまりで1つの助動詞のように働きます。\n②【今の様子から考えて】〜しそうだ\nLook at those clouds. It is going to rain.(あの雲を見て。雨が降りそうだよ。)',
        key: 'be going to の be は、主語に合わせた am・is・are。忘れずに入れる。' },
      { h: 'be going to の否定文・疑問文', t: 'be going to の文は be動詞の文なので、be動詞の文と同じしくみで作ります。\n【否定文】be動詞の後ろに not → They are not going to swim.(彼らは泳ぐつもりはありません。)\n【疑問文】be動詞を主語の前へ → Are they going to swim?(彼らは泳ぐつもりですか。)\n【答え方】Yes, they are. / No, they aren\'t.\n疑問詞を使うと:What are you going to do tomorrow?(あしたは何をするつもりですか。)— I\'m going to see a movie.(映画を見るつもりです。)',
        ex: [{ q: 'Ken is going to buy a new bike.(ケンは新しい自転車を買うつもりです。)を否定文と疑問文にしよう。', hint: 'be動詞 is を動かします。going はそのままです。', steps: ['be going to の文なので、be動詞 is を使って作る。do・does は使わない。', '否定文:is の後ろに not → Ken is not going to buy a new bike.', '疑問文:is を Ken の前に出す → Is Ken going to buy a new bike?', '答え方:Yes, he is. / No, he isn\'t.'], a: '否定文:Ken isn\'t going to buy a new bike.(ケンは新しい自転車を買うつもりはありません。)/疑問文:Is Ken going to buy a new bike?(ケンは新しい自転車を買うつもりですか。)— Yes, he is. / No, he isn\'t.', check: 'going to の後ろの buy が原形のままになっていることを確かめます。' }] },
      { h: 'will と be going to の使い分け', t: '【前から決めていた予定】→ be going to が自然です。\nI\'m going to visit Kyoto this summer.(この夏、京都を訪れる予定です。)\n【その場で決めたこと】→ will が自然です。\nThe phone is ringing. — OK, I\'ll get it.(電話が鳴っているよ。— わかった、ぼくが出るよ。)\n【ただの予想】→ どちらも使えます。It will rain tomorrow. / It is going to rain tomorrow.(あしたは雨が降るでしょう。)\n未来を表すことば:tomorrow(あした)、next 〜(次の〜)、this evening(今晩)、soon(まもなく)、someday(いつか)、in the future(将来)。',
        ex: [{ q: 'I will clean my room this afternoon. を、be going to を使った文に書きかえよう。', hint: 'will を「be動詞 + going to」に置きかえます。', steps: ['will を be going to にかえる。', '主語 I に合う be動詞は am。', '後ろの動詞は原形 clean のまま。'], a: 'I am(I\'m) going to clean my room this afternoon.(私は今日の午後、部屋をそうじするつもりです。)', check: 'am を入れ忘れて I going to としていないか確かめます。' }] }
    ],
    faq: [
      ['will と be going to はどちらを使ってもいいの?', '予想のときはどちらでもほぼ同じ意味です。\n予定については、前から決めていたなら be going to、話しているその場で決めたなら will がより自然です。テストでは書きかえ問題で「同じ意味」として扱われることが多いです。'],
      ['be going to の going は「行く」の意味?', 'ここでは「行く」の意味はありません。be going to のかたまりで「〜するつもりだ・〜しそうだ」という意味になります。\n「行くつもりだ」と言うときは I\'m going to go to the park. のように、後ろにもう一度 go を置きます。'],
      ['won\'t はなぜ willn\'t ではないの?', '昔の英語の形が残ったもので、発音しやすいように変化したといわれています。\nwon\'t は特別な形として、そのまま覚えましょう。']
    ],
    terms: [['will', '未来の予想・意志を表す助動詞。後ろは原形'], ['be going to', '予定・様子から考えた未来を表す。be は主語に合わせる'], ['won\'t', 'will not の短縮形'], ['予想', '「〜だろう」とこれから起こることを考えること'], ['意志', '「〜します」と自分で決めた気持ち']],
    miss: ['be going to の be動詞を忘れる(× I going to play.)。日本語の「〜するつもり」には be にあたる語がないためです。主語の後ろに am・is・are があるか確認しましょう。', 'will の後ろに s や ing をつける(× He will plays.)。will は助動詞なので後ろは原形です。', 'going to の後ろを ing形にする(× I\'m going to playing.)。going の ing につられないよう、to の後ろは原形と覚えましょう。', 'Will you 〜? に Yes, I do. と答える(○ Yes, I will.)。質問に使われた語(will)で答えます。'],
    sum: ['英語に未来の形の変化はない。will + 原形、be going to + 原形で未来を表す。', 'be動詞の文の未来は will be。', 'will の否定は won\'t、疑問文は Will を前へ。', 'be going to は be動詞の文と同じしくみで否定文・疑問文を作る。', '前からの予定は be going to、その場で決めたことは will。'],
    next: '次は「助動詞(must・have to など)」(e_m3)へ進みましょう。can・will の仲間の助動詞で、「〜しなければならない」「〜してもよい」などを表します。'
  };
  L.e_m3 = {
    goal: 'must・have to・may・should などの助動詞の意味と使い方が分かり、肯定文・否定文・疑問文や会話表現を正しく使えるようになる。',
    intro: '「宿題をしなければならない」「入ってもいいですか」「早く寝たほうがいい」。こうした話し手の気持ちや判断は、【助動詞】で表します。助動詞のルールはどれも共通で、【助動詞 + 動詞の原形】。意味を正しく覚えれば、使い方はかんたんです。',
    pre: 'これまでに can(〜できる)と will(〜だろう・〜するつもりだ)の2つの助動詞を学びました。\n助動詞の後ろの動詞は必ず原形で、主語が3人称単数でも s はつけません:He can swim. / She will come.\n否定文は助動詞の後ろに not(cannot・won\'t)、疑問文は助動詞を主語の前に出しました:Can you swim? — Yes, I can.\n一般動詞の否定文・疑問文は do・does・did を使って作りました:He doesn\'t like dogs. / Does he like dogs? この作り方は、この単元の have to で使います。',
    secs: [
      { h: '助動詞の共通ルール', t: '助動詞は、動詞に「話し手の気持ちや判断」をつけ足すことばです。どの助動詞にも、次の4つの共通ルールがあります。\n①後ろは必ず動詞の原形 ②主語が何でも形は変わらない ③否定文は後ろに not ④疑問文は主語の前へ\nこの単元で学ぶ must・may・should も、can・will と同じルールで使えます。\nYou must go.(行かなければならない)/You may go.(行ってもよい)/You should go.(行ったほうがよい)\nこのように、動詞 go は同じでも、前の助動詞を変えるだけで意味が変わります。',
        key: '助動詞 + 動詞の原形。どの助動詞も、主語で形が変わらない。' },
      { h: 'must と have to:〜しなければならない', t: '【must】〜しなければならない:You must wear a helmet.(ヘルメットをかぶらなければなりません。)\n【have to + 原形】も「〜しなければならない」という意味で、肯定文では must とほぼ同じです。\nただし have to は助動詞ではなく、have が一般動詞のように形を変えます。\n・3人称単数 → has to:She has to get up early.(彼女は早起きしなければなりません。)\n・過去 → had to:I had to wait for an hour.(私は1時間待たなければなりませんでした。)\nmust には過去形がないので、過去のことは had to で表します。\nmust には「〜にちがいない」という意味もあります:He must be tired.(彼は疲れているにちがいない。)',
        ex: [{ q: '( )内の語を使って書きかえよう。(1) I must study tonight. (have) (2) My sister must practice the piano. (has) (3) We must wait for the bus.(「〜しなければならなかった」の文に)', hint: 'have to は主語や時制で形が変わります。', steps: ['(1) must を have to にかえる。主語 I なので have to のまま → I have to study tonight.', '(2) 主語 my sister は3人称単数なので has to → My sister has to practice the piano.', '(3) 過去のことなので、must ではなく had to を使う。', '後ろの動詞はどれも原形のまま。'], a: '(1) I have to study tonight. (2) My sister has to practice the piano. (3) We had to wait for the bus.', check: 'to の後ろの動詞が原形(study・practice・wait)になっているか確かめます。' }] },
      { h: '否定文で意味が大きく変わる', t: '肯定文ではほぼ同じ意味の must と have to ですが、否定文になると意味がまったくちがいます。\n【must not】(mustn\'t)〜してはいけない(禁止)\nYou must not swim here.(ここで泳いではいけません。)\n【don\'t have to】〜しなくてもよい・〜する必要はない(不必要)\nYou don\'t have to hurry.(急がなくてもいいですよ。)\nhave to の否定文は、一般動詞と同じく don\'t・doesn\'t・didn\'t を使います:He doesn\'t have to come.(彼は来なくてもよい。)\n覚え方:must not は「しないことが必要」、don\'t have to は「することが必要ではない」。not がどこを打ち消しているかがちがうのです。',
        key: 'must not は「〜してはいけない」、don\'t have to は「〜しなくてもよい」。',
        ex: [{ q: '( )に入る語は? You (   ) (   ) to bring lunch. We have a party.(お弁当を持ってくる必要はありません。パーティーがあるからです。)', hint: '「必要がない」のか「してはいけない」のかを考えます。', steps: ['「〜する必要はない」は不必要を表すので don\'t have to。', 'must not にすると「持ってきてはいけない」という禁止になってしまう。', '空所は2つで、後ろに to があるので don\'t + have が入る。'], a: 'don\'t have', check: '日本文を「持ってきてはいけない」に言いかえて意味が変わることから、must not ではないと確かめます。' }] },
      { h: 'may と should', t: '【may】には2つの意味があります。\n①〜してもよい(許可):You may use my pen.(私のペンを使ってもいいですよ。)\n②〜かもしれない(推量):It may rain this afternoon.(午後は雨が降るかもしれません。)\n【should】〜すべきだ・〜したほうがよい(助言・義務)\nYou should go to bed early.(早く寝たほうがいいですよ。)/You shouldn\'t eat too much.(食べすぎないほうがいいですよ。)\nmust よりも should のほうがやわらかい言い方で、友だちにアドバイスするときによく使います。',
        ex: [{ q: '日本文に合う英文を書こう。(1) 彼は今日来ないかもしれません。(2) あなたはお母さんを手伝うべきです。', hint: '(1) は推量の may、(2) は助言の should を使います。', steps: ['(1)「〜かもしれない」は may。否定なので may の後ろに not を置く。', '「来る」は come(原形)。「今日」は today を最後に → He may not come today.', '(2)「〜すべきだ」は should + 原形。', '「お母さんを手伝う」は help your mother → You should help your mother.'], a: '(1) He may not come today. (2) You should help your mother.', check: '(1) で may の後ろの come に s がついていないか(主語が He でも原形)確かめます。' }] },
      { h: '疑問文と答え方', t: '助動詞の疑問文は、助動詞を主語の前に出します。答え方には決まった形があるので、セットで覚えましょう。\n【Must I 〜?】(〜しなければなりませんか。)— Yes, you must. / No, you don\'t have to.(いいえ、その必要はありません。)\nNo の答えで must not を使うと「してはいけない」になるので、don\'t have to を使います。\n【Do I have to 〜? / Does he have to 〜?】— Yes, he does. / No, he doesn\'t.\n【Should I 〜?】(〜すべきですか。)— Yes, you should. / No, you shouldn\'t.',
        ex: [{ q: 'Ken must clean the room.(ケンは部屋をそうじしなければなりません。)を have to を使って書きかえ、さらに疑問文にしよう。', hint: 'has to の疑問文は、一般動詞と同じく Does を使います。', steps: ['must = have to。主語 Ken は3人称単数なので has to にする。', '書きかえ:Ken has to clean the room.', '疑問文:has to は一般動詞と同じように Does を使い、has は原形 have にもどす。', '→ Does Ken have to clean the room? — Yes, he does. / No, he doesn\'t.'], a: 'Ken has to clean the room. / Does Ken have to clean the room?(ケンは部屋をそうじしなければなりませんか。)— Yes, he does. / No, he doesn\'t.', check: 'Does と has を同時に使っていないか(Does Ken has to 〜 になっていないか)確かめます。' }] },
      { h: '会話でよく使う表現', t: '【Shall I 〜?】(私が)〜しましょうか(申し出):Shall I open the window?(窓を開けましょうか。)— Yes, please. / No, thank you.\n【Shall we 〜?】(いっしょに)〜しましょうか(さそい。Let\'s 〜 とほぼ同じ):Shall we dance?(おどりましょうか。)— Yes, let\'s.\n【Will you 〜?】〜してくれますか(依頼):Will you help me?(手伝ってくれますか。)— Sure.(いいですよ。)\n【Could you 〜?】〜していただけますか(ていねいな依頼):Could you tell me the way to the station?(駅への道を教えていただけますか。)\n【May I 〜?】〜してもよろしいですか(ていねいな許可):May I come in?(入ってもよろしいですか。)— Sure.\nShall I は「自分が」、Shall we は「いっしょに」、Will you・Could you は「相手が」動作をする、と主語で区別できます。',
        ex: [{ q: '場面に合う表現を( )に入れよう。(1) 重そうな荷物を持つ人に:(   ) I carry your bag? (2) 友だちを映画にさそう:(   ) we go to the movies?', hint: '動作をするのが「自分」か「いっしょに」かを考えます。', steps: ['(1) かばんを運ぶのは自分 → 申し出の Shall I 〜?。', '(2) 映画に行くのは自分と友だちいっしょ → さそいの Shall we 〜?。', 'どちらも Shall が入るが、後ろの主語(I と we)で意味が変わる。'], a: '(1) Shall(かばんを運びましょうか。) (2) Shall(映画に行きましょうか。)', check: '(2) は Let\'s go to the movies. と言いかえても同じ意味になることを確かめます。' }] }
    ],
    faq: [
      ['must と have to は、肯定文ならどちらを使ってもいいの?', 'ほぼ同じ意味なので、テストでは書きかえ問題でよく使われます。\nくわしく言うと、must は話し手自身が「そうすべきだ」と思う気持ち、have to は規則や事情でそうする必要がある感じが強めです。'],
      ['May I 〜? と Can I 〜? のちがいは?', 'どちらも「〜してもいいですか」ですが、May I 〜? のほうがていねいです。\n先生やお店の人など、目上の人には May I 〜? を使うとよいでしょう。'],
      ['なぜ Must I 〜? に No, you must not. と答えないの?', 'must not は「してはいけない」という禁止の意味だからです。\n「しなければなりませんか」への No は「その必要はない」なので、No, you don\'t have to. と答えます。']
    ],
    terms: [['must', '〜しなければならない/〜にちがいない'], ['have to', '〜しなければならない。主語・時制で has to・had to になる'], ['may', '〜してもよい/〜かもしれない'], ['should', '〜すべきだ・〜したほうがよい'], ['must not と don\'t have to', '「〜してはいけない(禁止)」と「〜しなくてよい(不必要)」'], ['Shall I 〜? / Shall we 〜?', '「〜しましょうか」(申し出)/「いっしょに〜しましょうか」(さそい)']],
    miss: ['must not と don\'t have to を同じ意味だと思う。肯定文の must = have to をそのまま否定文にも当てはめるのが原因です。否定文は意味が別、と覚えましょう。', '主語が3人称単数なのに have to のままにする(○ She has to 〜)。have to の have は一般動詞と同じく形が変わります。', 'must を過去形にしようとして musted とする(○ had to)。must には過去形がありません。', 'Does he has to 〜? とする(○ Does he have to 〜?)。Does を使ったら has は原形 have にもどします。'],
    sum: ['助動詞 + 動詞の原形。主語が何でも助動詞の形は同じ。', 'must ≒ have to。have to は has to・had to と形が変わる。', 'must not は禁止、don\'t have to は不必要。', 'may は許可・推量、should は助言。', 'Shall I は申し出、Shall we はさそい、Will you・Could you は依頼。'],
    next: '次は「不定詞」(e_m4)へ進みましょう。to + 動詞の原形で「〜すること」「〜するための」「〜するために」を表す方法を学びます。'
  };
  L.e_m4 = {
    goal: 'to + 動詞の原形(不定詞)の3つの用法(名詞的・形容詞的・副詞的)を見分け、意味を正しくとれるようになる。',
    intro: '【不定詞】は「to + 動詞の原形」の形をしたことばのかたまりです。同じ形なのに、文の中での働きによって「〜すること」「〜するための」「〜するために」と意味が変わります。どの働きかは、【文のどこにあるか】と【何を説明しているか】で決まります。',
    pre: 'ことばには、文の中での働きによる分け方(品詞)があります。この単元では次の3つを使います。\n【名詞】もの・ことの名前(book・music など)。文の主語(〜は)や目的語(〜を)になります。\n【形容詞】名詞のようすを説明することば(big・new など)。a big dog の big は dog を説明しています。\n【副詞】動詞や文に「なぜ・どのように」などの情報をつけ足すことば(fast・here など)。He runs fast. の fast は runs を説明しています。\n動詞の【原形】は、s・ed・ing のつかないもとの形です。be動詞の原形は be でした。',
    secs: [
      { h: '不定詞とは', t: '【不定詞】は【to + 動詞の原形】の形をしたかたまりです。\n主語が3人称単数でも、過去の文でも、to の後ろはいつも原形です。主語や時制によって形が「定まらない(変わらない)」ので、不定詞と呼ばれます。\n× He wants to plays. × I wanted to played. → ○ He wants to play. / I wanted to play.\nこの to は「〜へ」という意味の前置詞の to とは別のものです。to the park(公園へ)の to の後ろは名詞、不定詞の to の後ろは動詞の原形です。\n不定詞は文の中で、①名詞 ②形容詞 ③副詞 のどれかの働きをします。これを不定詞の3用法といいます。',
        key: '不定詞 = to + 動詞の原形。主語・時制に関係なく、to の後ろはいつも原形。' },
      { h: '名詞的用法①:動詞の目的語になる', t: '【名詞的用法】の不定詞は「〜すること」という意味で、名詞と同じように使います。\nI like music.(音楽が好き)の music の位置に to read books を入れると、I like to read books.(私は本を読むことが好きです。)になります。\nこのように、動詞の後ろで「〜を」にあたる目的語になる使い方が、最もよく出てきます。\nよく使う形:【want to 〜】〜したい、【hope to 〜】〜することを望む、【try to 〜】〜しようとする、【start(begin) to 〜】〜し始める、【decide to 〜】〜することに決める\nI want to be a doctor.(私は医者になりたい。)\n注意:enjoy・finish・stop の後ろには不定詞ではなく ing形(動名詞)を使います。× I enjoyed to play. → ○ I enjoyed playing.',
        ex: [{ q: '日本文に合うように英語にしよう。「私は将来、先生になりたい。」', hint: '「〜したい」は want to + 原形です。「〜になる」は be を使います。', steps: ['「〜したい」は「〜することを望む」と考え、want to + 原形にする。', '「先生になる」は be a teacher(be動詞の原形 be を使う)。', '「将来」は in the future を文の最後に置く。'], a: 'I want to be a teacher in the future.', check: 'want の後ろが to be と原形になっているか、am にしていないかを確かめます。' }] },
      { h: '名詞的用法②:補語・主語になる', t: '名詞的用法の不定詞は、be動詞の後ろ(補語)にも置けます。補語とは、主語と「イコール」になることばです。\nMy dream is to travel around the world.(私の夢は世界中を旅することです。)→ my dream = to travel around the world\n主語にもなりますが、「〜することは…だ」は、ふつう【It is … (for 人) to 〜.】の形にします。主語が長くなると文の始まりが重くなるので、仮の主語 It を先に置くのです。\nIt is important for us to study.(私たちにとって勉強することは大切です。)\nIt は仮の主語で、「それ」とは訳しません。本当の主語は to 以下です。for 人 は「だれにとって」を表し、なくてもかまいません。',
        ex: [{ q: '[ ]の語を並べかえて、日本文に合う英文にしよう。「英語を毎日勉強することは大切です。」 It [ important / English / is / study / to ] every day.', hint: 'It is … to 〜 の形にあてはめます。', steps: ['仮の主語 It の後ろに be動詞 is を置く → It is。', '「大切だ」important を is の後ろに置く → It is important。', '本当の主語「英語を勉強すること」を to + 原形で表す → to study English。', '最後に every day をつける。'], a: 'It is important to study English every day.', check: 'It を to study English every day に置きかえて「英語を毎日勉強することは大切です」と読めるか確かめます。' }] },
      { h: '形容詞的用法:〜するための・〜すべき', t: '【形容詞的用法】の不定詞は、【すぐ前の名詞】を後ろから説明します。\nI have a lot of homework to do.(私にはやるべき宿題がたくさんあります。)→ to do が homework を説明\nI want something to drink.(何か飲むものがほしい。)→ to drink が something を説明\nThere are many places to visit in Kyoto.(京都には訪れるべき場所がたくさんあります。)\n日本語では「飲む もの」と説明が前にきますが、英語では「もの + 飲むための」と、説明が後ろにきます。\n見分け方:to の直前が名詞で、「〜するための(名詞)」「〜すべき(名詞)」と訳すと自然なら形容詞的用法です。',
        key: 'to の直前に名詞があり、その名詞を「〜するための」と説明していれば形容詞的用法。' },
      { h: '副詞的用法:〜するために/〜して', t: '【副詞的用法】の不定詞は、動詞や形容詞に「なぜ」の情報をつけ足します。\n【目的】〜するために:I went to the library to study.(私は勉強するために図書館へ行きました。)\nWhy did you go there? — To see my friend.(なぜそこへ行ったのですか。— 友だちに会うためです。)のように、Why の答えにも使えます。\n【感情の原因】〜して:glad・happy・sad・surprised など、気持ちを表す語の後ろに置きます。\nI am glad to see you.(あなたに会えてうれしいです。)\nI was surprised to hear the news.(私はその知らせを聞いておどろきました。)',
        ex: [{ q: '2つの文を、不定詞を使って1つにしよう。I got up early. I wanted to watch the sunrise.(私は早起きしました。日の出を見たかったのです。)', hint: '「〜するために早起きした」と、目的を表す形にします。', steps: ['2つ目の文は、早起きした「目的」を表している。', '目的は副詞的用法の to + 原形で表す → to watch the sunrise。', '1つ目の文の後ろにつなげる。'], a: 'I got up early to watch the sunrise.(私は日の出を見るために早起きしました。)', check: 'Why did you get up early? — To watch the sunrise. と問答にして、意味が通るか確かめます。' }] },
      { h: '3つの用法の見分け方', t: '用法を見分けるには、【to 〜 を取り去ったとき、何が欠けるか】を考えます。\n①動詞の目的語や補語が欠ける(I want … で文が終わってしまう)→ 名詞的用法「〜すること」\n②直前の名詞を説明している(something to drink)→ 形容詞的用法「〜するための」\n③取り去っても文が完成している(I went to the library. で文として成り立つ)→ 副詞的用法「〜するために/〜して」\n訳を当てはめて、いちばん自然な日本語になるものを選ぶのも有効です。',
        ex: [{ q: '下の文の不定詞は、名詞的・形容詞的・副詞的のどれ? (1) She went to Canada to study English. (2) I need a pen to write with. (3) He started to run.', hint: 'to 〜 を取り去ったとき、文が成り立つかどうかを考えます。', steps: ['(1) to 〜 を取ると She went to Canada. で文が完成する。「英語を勉強するために」という目的 → 副詞的用法。', '(2) 直前の名詞 a pen を説明し、「書くためのペン」となる → 形容詞的用法。', '(3) to 〜 を取ると He started. で「何を始めたか」が欠ける。started の目的語で「走ること」→ 名詞的用法。'], a: '(1) 副詞的用法(彼女は英語を勉強するためにカナダへ行った。) (2) 形容詞的用法(私は書くためのペンが必要だ。) (3) 名詞的用法(彼は走り始めた。)', check: 'それぞれの訳(〜するために/〜するための/〜すること)を入れて、日本語として自然かどうか確かめます。' }] }
    ],
    faq: [
      ['「〜するために」と「〜するための」はどう区別するの?', '「ために」は動詞(行った・起きた など)にかかり、「ための」は名詞(ペン・もの など)にかかります。\n不定詞のすぐ前が名詞で、その名詞を説明していれば「ための」(形容詞的用法)です。'],
      ['I want to go to the park. には to が2つあるけれど?', '1つ目の to は不定詞の to(後ろは原形 go)、2つ目の to は「〜へ」という前置詞の to(後ろは名詞 the park)です。\nto の後ろが動詞か名詞かで見分けましょう。'],
      ['It is … to 〜 の It は、何を指しているの?', '後ろの to 〜 を指しています。「それは」とは訳しません。\nTo study English is important. でも文法的にはまちがいではありませんが、英語では長い主語を後ろに回して It で始めるほうが自然です。']
    ],
    terms: [['不定詞', 'to + 動詞の原形'], ['名詞的用法', '「〜すること」。動詞の目的語・補語・主語になる'], ['形容詞的用法', '「〜するための・〜すべき」。前の名詞を説明する'], ['副詞的用法', '「〜するために(目的)」「〜して(感情の原因)」'], ['補語', '主語とイコールになることば。be動詞の後ろなどにくる'], ['仮の主語 It', 'It is … to 〜. の It。本当の主語は to 以下']],
    miss: ['to の後ろに s や ed をつける(× to plays、to played)。主語や時制につられるのが原因です。to を見たら後ろは原形、と確認しましょう。', 'enjoy・finish の後ろに不定詞を使う(× enjoy to play)。この2つは動名詞(ing形)をとる動詞です。', 'homework to do を「するために宿題」と副詞的用法で訳す(○ やるべき宿題)。直前に名詞があるかを先に見ましょう。', 'It is … to 〜 の It を「それは」と訳してしまう。仮の主語なので訳しません。'],
    sum: ['不定詞 = to + 動詞の原形。to の後ろはいつも原形。', '名詞的「〜すること」、形容詞的「〜するための」、副詞的「〜するために/〜して」。', 'want to・hope to・decide to などは名詞的用法。', '前に名詞があり、それを説明していれば形容詞的用法。', '「〜することは…だ」は It is … (for 人) to 〜.'],
    next: '次は「動名詞」(e_ger)へ進みましょう。不定詞の名詞的用法と同じ「〜すること」を ing形で表す方法と、どちらを使うかの見分け方を学びます。'
  };
  L.e_ger = {
    goal: '動名詞(〜ing)の使い方が分かり、ing をとる動詞・to をとる動詞・前置詞の後ろの形を正しく選べるようになる。',
    intro: '動詞に ing をつけると、「〜すること」という名詞のような働きをします。これを【動名詞】といいます。不定詞の名詞的用法(to 〜)と意味は似ていますが、【動詞によってどちらを後ろにとるかが決まっている】のがポイントです。',
    pre: '【不定詞の名詞的用法】は to + 動詞の原形で「〜すること」を表しました。I want to play tennis.(私はテニスをしたい。)\n動詞の ing形は、進行形(be動詞 + ing形)で「〜しているところ」を表すときにも使いました。He is playing tennis.\ning形の作り方:ふつうは ing、e で終わる語は e をとる(make → making)、短い母音 + 子音字1つは重ねる(swim → swimming)。\n【前置詞】は、at・in・on・for・of・about・with などのように、名詞の前に置いて場所や時などを表すことばです。in the room、for you のように使います。',
    secs: [
      { h: '動名詞とは', t: '【動名詞】は【動詞の ing形】で「〜すること」を表し、名詞と同じように文の中で使います。「動詞」から生まれた「名詞」なので、動名詞と呼ばれます。\n主語:Playing soccer is fun.(サッカーをすることは楽しい。)\n動名詞の主語は、いくつの語がついていても「1つのこと」なので単数あつかいです。だから be動詞は is になります。\n目的語:I like playing the piano.(私はピアノをひくことが好きです。)\n補語:My hobby is taking pictures.(私の趣味は写真をとることです。)',
        key: '動名詞 = 動詞の ing形で「〜すること」。主語になるときは単数あつかい。',
        ex: [{ q: '( )内の語を正しい形にしよう。(1) (Read) books (is / are) interesting. (2) (Get) up early is good for your health.', hint: '主語になる「〜すること」は動名詞にし、単数あつかいにします。', steps: ['(1) 文の最初で「本を読むこと」という主語にするので、read を ing形 Reading にする。', 'Reading books は「本を読むという1つのこと」なので単数あつかい → is。books の s につられて are にしない。', '(2) 「早起きすること」が主語 → Get を ing形にする。', 'get は「短い母音 e + 子音字 t」で終わるので t を重ねて Getting。'], a: '(1) Reading、is(本を読むことはおもしろい。) (2) Getting(早起きすることは健康によい。)', check: '主語を It(それ)に置きかえて It is interesting. と言えることから、is が正しいと確かめます。' }] },
      { h: '動名詞と進行形の見分け方', t: '動名詞も進行形の ing も、形はまったく同じです。文の中での働きで見分けます。\n【進行形】He is taking pictures.(彼は写真をとっています。)→「彼」が今していること\n【動名詞】My hobby is taking pictures.(私の趣味は写真をとることです。)→「趣味 = 写真をとること」というイコールの文\n「〜している」と訳して意味が通るなら進行形、「〜すること」と訳して意味が通るなら動名詞です。\n「私の趣味が写真をとっている」とは言えないので、2つ目は動名詞だと分かります。' },
      { h: 'ing をとる動詞・to をとる動詞', t: '「〜すること」を目的語にするとき、動詞によって ing と to のどちらを使うかが決まっています。\n【ing(動名詞)だけをとる】enjoy(楽しむ)、finish(終える)、stop(やめる)、practice(練習する)、give up(あきらめる)、mind(気にする)\nI enjoyed talking with her.(私は彼女と話して楽しかった。)/I finished writing the report.(私はレポートを書き終えました。)\n【to(不定詞)だけをとる】want(〜したい)、hope(望む)、decide(決める)、plan(計画する)、wish(願う)\nHe decided to study abroad.(彼は留学することに決めました。)\n【どちらもとれて意味がほぼ同じ】like、love、start、begin:It started raining. = It started to rain.(雨が降り始めた。)\n覚え方のイメージ:want・hope・decide は「まだしていない、これからのこと」なので to。enjoy・finish・stop は「実際にしていること」が前提なので ing。',
        key: 'enjoy・finish・stop は ing、want・hope・decide は to。動詞ごとに決まっている。',
        ex: [{ q: '( )内の動詞を正しい形にしよう。(1) We enjoyed (sing) songs. (2) I hope (see) you again. (3) Did you finish (clean) your room?', hint: '前の動詞が「ing をとる仲間」か「to をとる仲間」かを思い出します。', steps: ['(1) enjoy は ing をとる動詞 → singing。', '(2) hope は to をとる動詞 → to see。', '(3) finish は ing をとる動詞 → cleaning。'], a: '(1) singing(私たちは歌を歌って楽しみました。) (2) to see(またあなたに会いたいです。) (3) cleaning(部屋のそうじは終わりましたか。)', check: '(2) の hope はこれからのこと、(1)(3) の enjoy・finish は実際にしていることだ、とイメージに当てはまるか確かめます。' }] },
      { h: '前置詞の後ろは動名詞', t: 'at・in・of・for・about・without・before・after などの【前置詞の後ろに動詞を置くときは、必ず ing形】にします。\n前置詞の後ろには名詞がくるきまりなので、動詞を名詞の形(動名詞)にするのです。不定詞(to 〜)は前置詞の後ろには置けません。\nHe is good at swimming.(彼は泳ぐのが得意です。)/Thank you for helping me.(手伝ってくれてありがとう。)\nHow about going to the movies?(映画に行くのはどうですか。)/I am interested in learning Chinese.(私は中国語を学ぶことに興味があります。)\nBefore going to bed, I brush my teeth.(寝る前に、私は歯をみがきます。)\n× good at swim、× for help me のように原形を置くのはまちがいです。',
        key: '前置詞の後ろに動詞を置くときは、必ず ing形(動名詞)。',
        ex: [{ q: '日本文に合うように英語にしよう。「さよならを言わずに、彼は帰った。」', hint: '「〜せずに」は前置詞 without を使います。', steps: ['「〜せずに」は前置詞 without。', '前置詞の後ろなので、say を動名詞 saying にする。', '「さよなら」は goodbye。「帰った」は went home。', '文の骨組み He went home の後ろに without saying goodbye を置く。'], a: 'He went home without saying goodbye.', check: 'without の後ろが原形 say や to say になっていないか確かめます。' }] },
      { h: 'stop 〜ing と stop to 〜', t: 'stop の後ろは、ing か to かで意味がまったくちがいます。\nHe stopped talking.(彼は話すのをやめた。)→ talking は stop の目的語(動名詞)\nHe stopped to talk.(彼は話すために立ち止まった[手を止めた]。)→ to talk は「話すために」という目的(不定詞の副詞的用法)\n「〜するのをやめる」と言いたいときは、必ず stop 〜ing です。\nstop to 〜 の to 〜 は stop の目的語ではなく、「何のために止まったか」をつけ足しています。',
        ex: [{ q: '次の2つの文の意味のちがいを説明しよう。(1) She stopped reading the book. (2) She stopped to read the sign.', hint: 'stop の後ろが ing か to かを見ます。', steps: ['(1) stop + ing形 → 「〜するのをやめる」。reading the book は stop の目的語。', '→ 「彼女はその本を読むのをやめた」。', '(2) stop + to 〜 → to 〜 は「〜するために」という目的を表す副詞的用法。', '→ 「彼女は標識を読むために立ち止まった」。'], a: '(1) 彼女はその本を読むのをやめた。(読むことをやめた) (2) 彼女は標識を読むために立ち止まった。(立ち止まって読んだ)', check: '(2) で彼女は実際に標識を読んだ、(1) で彼女は本を読むのをやめた、と動作の結果が逆になることを確かめます。' }] }
    ],
    faq: [
      ['to 〜 と 〜ing、どちらも「〜すること」なのに、なぜ使い分けがあるの?', '動詞ごとに相性が決まっているからです。おおまかには、to はこれから先のこと、ing は実際にしている(していた)ことと結びつきやすい、という傾向があります。\nただし例外もあるので、enjoy・finish・stop(ing)と want・hope・decide(to)は、セットで覚えてしまうのが確実です。'],
      ['I like swimming. と I like to swim. は同じ意味?', 'like は ing も to もとれる動詞なので、どちらも「泳ぐことが好きです」と考えてかまいません。\nlove・start・begin も同じように、どちらの形も使えます。'],
      ['How about 〜? の後ろは必ず ing形?', '動詞を続けるときは ing形です(How about playing tennis?)。about が前置詞だからです。\n名詞を続けることもできます:How about tomorrow?(あしたはどう?)']
    ],
    terms: [['動名詞', '動詞の ing形で「〜すること」を表すもの'], ['前置詞', 'at・in・for など、名詞の前に置くことば。後ろに動詞がくるときは ing形'], ['目的語', '動詞の後ろで「〜を」にあたることば'], ['How about 〜ing?', '「〜するのはどうですか」とさそう表現'], ['be good at 〜ing', '「〜するのが得意だ」'], ['be interested in 〜ing', '「〜することに興味がある」']],
    miss: ['enjoy to play、finish to read のように to を使う。日本語の「〜すること」を何でも to にするのが原因です。enjoy・finish・stop の後ろは ing、と決めておきましょう。', 'want playing のように、to をとる動詞に ing を使う。want・hope・decide の後ろは to です。', '前置詞の後ろに原形を置く(× good at play → ○ good at playing)。前置詞の後ろは名詞の仲間、と考えましょう。', '動名詞の主語に are を使う(× Playing games are fun. → ○ is)。games の s につられず、「1つのこと」と考えましょう。'],
    sum: ['動名詞 = 動詞の ing形で「〜すること」。主語なら単数あつかい。', '「〜すること」と訳せれば動名詞、「〜している」なら進行形。', 'enjoy・finish・stop は ing、want・hope・decide は to。', '前置詞の後ろの動詞は必ず ing形。', 'stop 〜ing は「やめる」、stop to 〜 は「〜するために立ち止まる」。'],
    next: '次は「比較」(e_m5)へ進みましょう。形容詞・副詞の形を変えて、2つや3つ以上のものを比べる文を学びます。'
  };
  L.e_m5 = {
    goal: '比較級・最上級の作り方と使い方、as 〜 as の文が分かり、2つや3つ以上のものを比べる文を書けるようになる。',
    intro: '「トムはケンより背が高い」「富士山は日本で一番高い山だ」。ものを比べるとき、英語では形容詞や副詞の形を変えます。2つを比べるなら【比較級】、3つ以上の中で一番なら【最上級】、同じくらいなら【as 〜 as】。まずは形の作り方から整理しましょう。',
    pre: '【形容詞】は名詞のようすを表すことばです。tall(背が高い)、big(大きい)、new(新しい)、interesting(おもしろい)など。be動詞の後ろ(Tom is tall.)や名詞の前(a tall boy)で使います。\n【副詞】は動詞などをくわしくすることばです。fast(速く)、early(早く)、well(上手に)など。He runs fast. の fast は runs を説明しています。\nこの単元で形を変えるのは、この形容詞と副詞です。名詞や動詞の形は変えません。\nつづりのルールは、これまでの ing・ed と似ています。「子音字 + y」は y を i にかえる、「短い母音 + 子音字1つ」は最後の文字を重ねる、という考え方をそのまま使います。',
    secs: [
      { h: '比べ方は3通り', t: '英語でものを比べる言い方は、大きく3つです。\n①2つを比べて「A は B より〜だ」→【比較級】Tom is taller than Ken.\n②3つ以上の中で「A が一番〜だ」→【最上級】Tom is the tallest in the class.\n③「A は B と同じくらい〜だ」→【as + 原級 + as】Tom is as tall as Ken.\n【原級】とは、形容詞・副詞のもとの形(tall)のことです。比較級は tall に er、最上級は est をつけた形です。\n何と何を、いくつの中で比べているかを先に考えると、どの形を使えばよいかが決まります。',
        key: '2つなら比較級、3つ以上で一番なら最上級、同じくらいなら as 〜 as。' },
      { h: '比較級・最上級の作り方', t: '①ふつうは【er・est】:tall → taller → tallest、old → older → oldest、fast → faster → fastest\n②e で終わる語は【r・st】:large → larger → largest、nice → nicer → nicest\n③「子音字 + y」は y を i にかえて【ier・iest】:easy → easier → easiest、busy → busier → busiest、early → earlier → earliest\n④「短い母音 + 子音字1つ」は最後の文字を重ねる:big → bigger → biggest、hot → hotter → hottest\n⑤beautiful・interesting・difficult・popular などの長い語は、前に【more・most】:interesting → more interesting → most interesting\n⑥不規則に変わる語:good・well → better → best、many・much → more → most、bad → worse → worst\n⑤の語に er をつけたり、more と er を両方つけたりすることはありません(× more taller)。',
        ex: [{ q: '次の語の比較級と最上級を書こう。(1) happy (2) large (3) popular (4) good', hint: '語の終わり方と長さで、①〜⑥のどのルールかを決めます。', steps: ['(1) happy は「子音字 p + y」で終わる → y を i にかえて happier・happiest。', '(2) large は e で終わる → r・st だけつけて larger・largest。', '(3) popular は長い語 → 前に more・most をつけて more popular・most popular。', '(4) good は不規則 → better・best。'], a: '(1) happier・happiest (2) larger・largest (3) more popular・most popular (4) better・best', check: 'gooder・popularer のような形を作っていないか確かめます。' }] },
      { h: '2つを比べる:比較級 + than', t: '【A + 動詞 + 比較級 + than B】で「A は B より〜だ」を表します。than は「〜より」という意味です。\nTom is taller than Ken.(トムはケンより背が高い。)\nThis book is more interesting than that one.(この本はあの本よりおもしろい。)\nHe runs faster than I do.(彼は私より速く走ります。)のように、副詞も同じように使えます。\n【Which is + 比較級, A or B?】で「A と B ではどちらが〜ですか」とたずねます。\nWhich is bigger, the sun or the moon?(太陽と月では、どちらが大きいですか。)— The sun is.(太陽です。)',
        ex: [{ q: '日本文に合う英文を書こう。「この問題はあの問題よりむずかしい。」', hint: 'difficult は長い語なので、er ではなく more を使います。', steps: ['2つを比べているので比較級 + than を使う。', 'difficult は長い語なので、比較級は more difficult。', '「あの問題」は that question。くり返しをさけて that one としてもよい。', 'This question is + more difficult + than that one.'], a: 'This question is more difficult than that one(that question).', check: 'than の前が比較級(more difficult)になっていて、原級の difficult のままでないか確かめます。' }] },
      { h: '3つ以上で一番:the + 最上級', t: '【the + 最上級 + in・of 〜】で「〜の中で一番…だ」を表します。\nTom is the tallest in his class.(トムはクラスで一番背が高い。)\nThis is the most interesting of the three.(これは3つの中で一番おもしろい。)\nin と of の使い分け:【in + 場所・範囲・集団】in Japan、in my family、in the class\n【of + 複数を表すことば】of the three、of all、of the five boys\n「だれが一番〜か」とたずねるときは Who を使います:Who is the tallest in your class?(あなたのクラスでだれが一番背が高いですか。)',
        key: '最上級には the をつける。範囲・場所は in、複数を表すことばは of。',
        ex: [{ q: '( )内の語を正しい形にし、[ ]から in か of を選ぼう。(1) Mt. Fuji is the (high) mountain [ in / of ] Japan. (2) This bag is the (cheap) [ in / of ] the four.', hint: 'the があれば最上級。後ろが「場所」か「複数のもの」かで in・of を決めます。', steps: ['(1) the があり「日本で一番」なので最上級。high → highest。', 'Japan は場所・範囲を表すので in。', '(2) the があるので最上級。cheap(安い)→ cheapest。', 'the four(4つ)は複数を表すことばなので of。'], a: '(1) highest、in(富士山は日本で一番高い山です。) (2) cheapest、of(このかばんは4つの中で一番安い。)', check: 'in の後ろは1つの場所・集団、of の後ろは数や all になっているかを確かめます。' }] },
      { h: 'as 〜 as:同じくらい', t: '【as + 原級(もとの形) + as】で「…と同じくらい〜」を表します。\nMy bag is as big as yours.(私のかばんはあなたのと同じくらい大きい。)\n【not as + 原級 + as】で「…ほど〜ではない」を表します。\nI am not as tall as my brother.(私は兄ほど背が高くない。)\nこれは、My brother is taller than I am.(兄は私より背が高い。)と同じ内容です。\nas と as の間には、比較級ではなく必ず原級を入れます(× as bigger as)。',
        ex: [{ q: 'Ken is not as old as Tom.(ケンはトムほど年上ではない。)を、ほぼ同じ意味になるように Tom で始まる比較級の文にしよう。', hint: '「ケンはトムほど年上ではない」とき、年上なのはどちらかを考えます。', steps: ['「ケンはトムほど年上ではない」→ トムのほうが年上。', 'Tom を主語にして、old の比較級 older + than を使う。', 'than の後ろは比べる相手 Ken。'], a: 'Tom is older than Ken.(トムはケンより年上です。)', check: 'Ken is younger than Tom.(ケンはトムより年下です。)とも言いかえられ、同じ内容になることを確かめます。' }] },
      { h: '「〜のほうが好き」「〜が一番好き」', t: '「B より A が好き」は、【like A better than B】を使います。better は well の比較級です。\nI like summer better than winter.(私は冬より夏が好きです。)\nWhich do you like better, tea or coffee?(紅茶とコーヒーでは、どちらが好きですか。)— I like tea better.(紅茶のほうが好きです。)\n「〜が一番好き」は、【like 〜 the best】を使います。\nI like spring the best of all seasons.(私はすべての季節の中で春が一番好きです。)\nWhat sport do you like the best?(何のスポーツが一番好きですか。)— I like soccer the best.' }
    ],
    faq: [
      ['どんな語に more・most をつけるの?', 'おもに、つづりが長い語(beautiful・interesting・difficult・popular・famous・important など)です。\nまた、slowly・carefully のように -ly で終わる副詞も more・most を使います(early は例外で earlier・earliest)。'],
      ['最上級になぜ the がつくの?', '「一番〜なもの」は、その集団の中でただ1つに決まるからです。英語では、1つに決まるものに the をつけます。\nただし、like 〜 the best の the は省略されることもあります。'],
      ['than I と than me、どちらが正しいの?', 'テストでは than I(am) の形が正式です:He is taller than I am.\n会話では than me もよく使われますが、迷ったら than I am と動詞まで書くと確実です。']
    ],
    terms: [['原級', '形容詞・副詞のもとの形(tall・big など)'], ['比較級', '-er・more 〜 の形。2つを比べて「より〜」'], ['最上級', '-est・most 〜 の形。3つ以上の中で「一番〜」'], ['than', '「〜より」。比較級の後ろに置く'], ['as 〜 as', '「…と同じくらい〜」。間は原級'], ['like A better than B', '「B より A が好き」']],
    miss: ['more taller のように、more と er を両方つける。どちらか一方だけ、と覚えましょう。', 'good の比較級を gooder とする(○ better)。good・well・many・much・bad の不規則変化はセットで覚えましょう。', 'in と of を取りちがえる(× of Japan、× in the three)。後ろが場所・集団なら in、数・all なら of です。', 'as 〜 as の間に比較級を入れる(× as bigger as)。「同じくらい」なので比べた形にはしません。'],
    sum: ['2つなら比較級 + than、3つ以上なら the + 最上級、同じくらいなら as + 原級 + as。', '短い語は -er・-est、長い語は more・most。good → better → best。', '範囲・場所は in、複数を表すことばは of。', 'not as 〜 as は「…ほど〜ない」。比較級の文に書きかえられる。', 'like A better than B、like A the best。'],
    next: '次は「受動態」(e_m6)へ進みましょう。「〜される」という文の作り方を学びます。過去分詞という新しい動詞の形が出てきます。'
  };
  L.e_m6 = {
    goal: '受動態(be動詞 + 過去分詞)の意味と作り方が分かり、能動態の文を受動態に書きかえたり、否定文・疑問文にしたりできるようになる。',
    intro: '「母がこの部屋をそうじする」を、部屋の立場から言うと「この部屋は(母によって)そうじされる」になります。このように「〜される」という形を【受動態(受け身)】といいます。作り方は【be動詞 + 過去分詞】。be動詞の文なので、否定文・疑問文も be動詞のルールで作れます。',
    pre: 'be動詞は主語と時制に合わせて形を変えました。現在は am・is・are、過去は was・were です。\nbe動詞の文の否定文は be動詞の後ろに not、疑問文は be動詞を主語の前に出しました。did は使いませんでした。\n英語の基本の語順は「主語 → 動詞 → 目的語」です。My mother cleans this room. では、my mother が主語、this room が目的語(〜を)です。\n代名詞には形の変化があります。主語の形(主格)は I・he・she・they、目的語の形(目的格)は me・him・her・them です。\n動詞の過去形には、ed をつける規則動詞(clean → cleaned)と、形が変わる不規則動詞(make → made)がありました。',
    secs: [
      { h: '「する側」と「される側」', t: '1つのできごとは、2つの立場から言うことができます。\n【能動態】する側を主語にした、ふつうの文:My mother cleans this room.(母がこの部屋をそうじします。)\n【受動態】される側を主語にした文:This room is cleaned by my mother.(この部屋は母によってそうじされます。)\n言っている内容は同じですが、「何について話したいか」によって主語を選びます。部屋の話をしたいなら、部屋を主語にするのです。\n受動態は「受け身」ともいいます。主語が動作を「受ける」側だからです。',
        key: '受動態は「される側」を主語にした文。内容は能動態と同じで、見る立場がちがう。' },
      { h: '受動態の形:be動詞 + 過去分詞', t: '受動態は【be動詞 + 過去分詞】で「〜される・〜されている」を表します。\n【過去分詞】は動詞の形の1つで、「〜された」という意味をもちます。clean の過去分詞は cleaned です。\nbe動詞は主語と時制に合わせて am・is・are・was・were を使い分けます。\nThis room is cleaned every day.(この部屋は毎日そうじされます。)/English is spoken in many countries.(英語は多くの国で話されています。)\n「〜によって」と、だれがしたかを言うときは【by 〜】を使います:This picture was painted by my sister.(この絵は姉によってかかれました。)',
        key: '受動態 = be動詞 + 過去分詞。be動詞で時制と主語を、過去分詞で「される」を表す。' },
      { h: '過去分詞の形', t: '規則動詞の過去分詞は、過去形と同じ ed の形です:clean → cleaned → cleaned、use → used → used\n不規則動詞は「原形 ― 過去形 ― 過去分詞」をセットで覚えます。\nmake ― made ― made/build ― built ― built/write ― wrote ― written/speak ― spoke ― spoken\ntake ― took ― taken/see ― saw ― seen/know ― knew ― known/give ― gave ― given\neat ― ate ― eaten/sing ― sang ― sung/read ― read ― read\n受動態で点を落とす原因の多くは、過去分詞の覚えちがいです。声に出して3つセットでくり返しましょう。',
        ex: [{ q: '( )内の動詞を過去分詞にして、受動態の文を完成させよう。(1) This song is (sing) by many people. (2) These pictures were (take) in Hokkaido. (3) The door was (open) by Ken.', hint: '規則動詞か不規則動詞かを見分けます。', steps: ['(1) sing は不規則動詞 → sing ― sang ― sung。過去分詞は sung。', '(2) take は不規則動詞 → take ― took ― taken。過去分詞は taken。', '(3) open は規則動詞 → ed をつけて opened。'], a: '(1) sung(この歌は多くの人に歌われています。) (2) taken(これらの写真は北海道でとられました。) (3) opened(ドアはケンによって開けられました。)', check: '(1)(2) で過去形の sang・took を入れていないか確かめます。' }] },
      { h: '能動態を受動態にする手順', t: '例:Many people love this song.(多くの人がこの歌を愛しています。)\n①もとの文の目的語(this song)を主語にする。\n②動詞を「be動詞 + 過去分詞」にする。主語 this song は単数で現在の文なので is loved。\n③もとの主語を by の後ろに置く → This song is loved by many people.(この歌は多くの人に愛されています。)\nby の後ろに代名詞がくるときは目的格(him・her・them など)にします:He wrote this letter. → This letter was written by him.\nbe動詞の時制は、もとの文の動詞の時制に合わせます。もとが過去形なら was・were です。',
        ex: [{ q: 'Natsume Soseki wrote this book.(夏目漱石がこの本を書きました。)を受動態にしよう。', hint: '目的語 → 主語、動詞 → be動詞 + 過去分詞、主語 → by 〜 の3段階です。', steps: ['目的語 this book を主語にする。', 'もとの文 wrote は過去形 → be動詞は過去。主語 this book は単数なので was。', 'write の過去分詞は written → was written。', 'もとの主語を by の後ろへ → by Natsume Soseki。'], a: 'This book was written by Natsume Soseki.(この本は夏目漱石によって書かれました。)', check: '受動態の文を能動態にもどすと、もとの Natsume Soseki wrote this book. になることを確かめます。' }] },
      { h: 'by を使わない受動態・助動詞のある受動態', t: 'だれがしたかが分からないとき、言う必要がないときは、by 〜 を省きます。実際の英文では、by のない受動態のほうが多いくらいです。\nThis temple was built 500 years ago.(この寺は500年前に建てられました。)\nEnglish is spoken in Australia.(オーストラリアでは英語が話されています。)\n助動詞といっしょに使うときは【助動詞 + be + 過去分詞】です。助動詞の後ろは原形なので、be動詞は原形の be になります。\nStars can be seen at night.(星は夜に見ることができます。)/This work will be finished tomorrow.(この仕事はあした終えられるでしょう。)',
        ex: [{ q: '次の文を、[ ]内の語を加えて書きかえよう。This room is used by students. [ can ]', hint: '助動詞の後ろは原形。is の原形は be です。', steps: ['助動詞 can を be動詞の位置に入れる。', 'can の後ろは原形なので、is を be にかえる。', '過去分詞 used はそのまま → This room can be used by students.'], a: 'This room can be used by students.(この部屋は生徒が使うことができます。)', check: 'can is used のように、助動詞と is が並んでいないか確かめます。' }] },
      { h: '否定文・疑問文の作り方', t: '受動態は be動詞の文なので、be動詞のルールで作ります。\n【否定文】be動詞の後ろに not → This car is not made in Japan.(この車は日本で作られていません。)\n【疑問文】be動詞を主語の前へ → Is this car made in Japan?(この車は日本で作られていますか。)\n【答え方】Yes, it is. / No, it isn\'t.\n疑問詞を使うと:When was this temple built?(この寺はいつ建てられましたか。)/What language is spoken in Brazil?(ブラジルでは何語が話されていますか。)— Portuguese is.(ポルトガル語です。)\n文の動詞は be動詞なので、過去の疑問文でも did は使いません。',
        key: '受動態の否定文・疑問文は be動詞で作る。過去でも did は使わない。',
        ex: [{ q: '( )に入る語は? When (   ) this temple built?', hint: 'built は過去形か過去分詞か、文の動詞は何かを考えます。', steps: ['built は build の過去分詞。「建てられた」という受動態の疑問文。', '受動態の疑問文は be動詞を前に出す。did は使わない。', 'this temple は単数で過去のことなので was。'], a: 'was(この寺はいつ建てられましたか。)', check: '答えの文 This temple was built 〜. を作り、was が前に出たものだと確かめます。' }] }
    ],
    faq: [
      ['受動態はどんなときに使うの?', '①される側(もの)について話したいとき、②だれがしたか分からない・言う必要がないときに使います。\nThis bridge was built in 1990.(この橋は1990年に建てられた。)は、建てた人よりも橋のことを伝えたい文です。'],
      ['過去形と過去分詞は、どうやって見分けるの?', '規則動詞では同じ形なので、文の中の位置で見分けます。be動詞や have の後ろにあれば過去分詞、主語のすぐ後ろで動詞として使われていれば過去形です。\nThe window was broken.(過去分詞)/He broke the window.(過去形)'],
      ['by の後ろはなぜ him や them になるの?', 'by は前置詞なので、後ろの代名詞は目的格(me・him・her・us・them)にするきまりがあるからです。\nfor him・with them と同じ考え方です。']
    ],
    terms: [['受動態(受け身)', 'be動詞 + 過去分詞。「〜される」'], ['能動態', '「〜する」という、する側を主語にしたふつうの文'], ['過去分詞', '受動態や現在完了で使う動詞の形(written・made など)'], ['by 〜', '「〜によって」。動作をした人やものを表す'], ['目的格', 'me・him・her・them など、目的語や前置詞の後ろで使う代名詞の形']],
    miss: ['be動詞を忘れる(× This room cleaned every day.)。cleaned だけだと「そうじした」という過去形の文に見えてしまいます。必ず be動詞とセットにしましょう。', '過去分詞をまちがえる(× writed → ○ written)。不規則動詞は原形・過去形・過去分詞をセットで覚えましょう。', '受動態の疑問文に did を使う(× Did this temple built? → ○ Was this temple built?)。受動態は be動詞の文です。', 'by の後ろの代名詞を主格にする(× by he → ○ by him)。前置詞の後ろは目的格です。'],
    sum: ['受動態 = be動詞 + 過去分詞で「〜される」。', '能動態の目的語を主語にし、もとの主語は by の後ろへ。', 'だれがしたかが重要でなければ by 〜 は省く。', '助動詞があるときは「助動詞 + be + 過去分詞」。', '否定文は be動詞 + not、疑問文は be動詞を前へ。did は使わない。'],
    next: '次は「接続詞」(e_conj)へ進みましょう。because・if・when などで文と文をつなぎ、長い文を組み立てる方法を学びます。'
  };
  L.e_conj = {
    goal: '2つの文の関係(つけ足し・逆接・理由・結果・時・条件)を考えて、and・but・so・because・when・if・that などの接続詞を正しく使えるようになる。',
    intro: '「雨が降っていた。だから家にいた。」「ひまなら、遊びに行こう。」。文と文をつなぐことばを【接続詞】といいます。どの接続詞を使うかは、まず日本語で【2つの文がどんな関係か】を考えると決まります。',
    pre: '英語の文の中心は「主語 + 動詞」でした。I like dogs. のように、主語と動詞がそろって1つの文になります。\nこの単元では、「主語 + 動詞」のある文を2つつなげます。つないでも、それぞれの部分に主語と動詞があることは変わりません。\n未来のことは will + 原形で表しました:I will stay home.(私は家にいるつもりです。)\n命令文は動詞の原形で始める文でした:Hurry up.(急ぎなさい。)\n日本語でも「そして」「しかし」「だから」「もし〜なら」のように、文と文の関係を表すことばを使っています。',
    secs: [
      { h: '接続詞とは', t: '語と語、文と文をつなぐことばを【接続詞】といいます。\n接続詞を使うと、「理由」「結果」「時」「条件」など、2つの内容がどんな関係にあるかを相手に伝えられます。\n接続詞を選ぶ手順は、①2つの文を日本語で考える ②関係(つけ足し・反対・理由・結果・時・条件)を決める ③その関係に合う接続詞を選ぶ、の3つです。\nいきなり英語を考えるより、日本語で関係をはっきりさせてからのほうが、まちがいが少なくなります。',
        key: '接続詞は、2つの文の関係(理由・結果・時・条件など)を考えてから選ぶ。' },
      { h: '対等につなぐ and・but・or・so', t: '【and】そして・〜と…(つけ足し):I went to the park and played tennis.(私は公園へ行って、テニスをしました。)\n【but】しかし・〜だが(反対の内容):I like dogs, but my sister doesn\'t.(私は犬が好きですが、妹は好きではありません。)\n【or】または・それとも(選択):Which do you want, tea or coffee?(紅茶とコーヒー、どちらがほしいですか。)\n【so】だから(後ろに結果):It was raining, so we stayed home.(雨が降っていたので、私たちは家にいました。)\n命令文の後ろでは、and と or が特別な意味になります。\nHurry up, and you will catch the bus.(急ぎなさい、そうすればバスに間に合います。)\nHurry up, or you will be late.(急ぎなさい、さもないと遅れますよ。)',
        ex: [{ q: '( )に and・but・or・so から適する語を入れよう。(1) I was hungry, (   ) I ate a big lunch. (2) He is rich, (   ) he is not happy. (3) Study hard, (   ) you will pass the test.', hint: '前後の文の関係を日本語で考えます。', steps: ['(1)「おなかがすいていた」→「たくさん昼食を食べた」は、原因 → 結果の関係 → so。', '(2)「お金持ちだ」と「幸せではない」は、予想と反対の内容 → but。', '(3) 命令文の後ろで「そうすれば〜」の意味 → and。'], a: '(1) so(おなかがすいていたので、たくさん昼食を食べました。) (2) but(彼はお金持ちですが、幸せではありません。) (3) and(一生けんめい勉強しなさい、そうすればテストに合格するでしょう。)', check: '(3) を or にすると「さもないと合格する」となり意味が通らないことから、and が正しいと確かめます。' }] },
      { h: '時・理由・条件を表す when・because・if', t: '【when】〜するとき:When I got home, my mother was cooking.(私が家に帰ったとき、母は料理をしていました。)\n【because】〜なので(理由):I stayed home because I was sick.(具合が悪かったので、私は家にいました。)\n【if】もし〜なら(条件):If you are free, let\'s go shopping.(もしひまなら、買い物に行こう。)\nこれらの接続詞は、文の前にも後ろにも置けます。前に置くときは、区切りにコンマ(,)をつけます。\nI was happy when I saw him. = When I saw him, I was happy.(彼に会ったとき、私はうれしかった。)\nほかに、before(〜する前に)、after(〜した後に)も同じように使えます:I washed my hands before I ate lunch.(昼食を食べる前に手を洗いました。)',
        ex: [{ q: '日本文に合う英文を書こう。「もしあした晴れなら、私たちはサッカーをします。」(If で始めて)', hint: 'If の部分と、残りの部分の間にコンマを入れます。', steps: ['「もし〜なら」は条件なので if を使う。', 'if の中は「あした晴れる」→ 天気の主語は it。未来のことでも if の中は現在形なので it is sunny tomorrow。', '後半は未来の文なので we will play soccer。', 'If の部分を前に置くので、間にコンマを入れる。'], a: 'If it is sunny tomorrow, we will play soccer.', check: '前後を入れかえた We will play soccer if it is sunny tomorrow. ではコンマが不要になることも確かめます。' }] },
      { h: 'because と so のちがい', t: '同じ内容を2通りに言えます。\nI was tired, so I went to bed early.(私は疲れていたので、早く寝ました。)= I went to bed early because I was tired.\n【because の後ろは原因・理由】、【so の後ろは結果】です。日本語にすると同じ「〜ので」になりやすいので、どちらが原因かを考えて選びます。\nWhy で聞かれたら、Because 〜. で答えられます:Why were you late?(なぜ遅れたのですか。)— Because I missed the bus.(バスに乗りおくれたからです。)\nふつうの文章で Because 〜. だけを1つの文として書くのは、この Why の答えのときだけにしましょう。\nまた、because と so を1つの文でいっしょに使うことはできません。',
        key: 'because の後ろは原因、so の後ろは結果。1つの文で両方は使わない。',
        ex: [{ q: 'It was cold, so I wore a coat.(寒かったので、私はコートを着ました。)を because を使って同じ意味の文にしよう。', hint: 'まず、原因と結果がどちらかを見分けます。', steps: ['原因は「寒かった」(It was cold)、結果は「コートを着た」(I wore a coat)。', 'because の後ろには原因を置く。', '結果 + because + 原因 の順にする。'], a: 'I wore a coat because it was cold.', check: 'Why did you wear a coat? — Because it was cold. と問答にして、意味が通るか確かめます。' }] },
      { h: 'if・when の中は、未来のことでも現在形', t: '「時」や「条件」を表す if・when の中では、【未来のことでも現在形】を使います。\nIf it rains tomorrow, I will stay home.(あした雨が降ったら、私は家にいます。)× If it will rain tomorrow\nWhen he comes, I will tell him.(彼が来たら、私が伝えます。)× When he will come\n文の後半(I will stay home)は未来の will を使いますが、if・when の中だけは現在形にする、と覚えておきましょう。\n主語が3人称単数なら、現在形の s を忘れないようにします(it rains・he comes)。',
        ex: [{ q: '( )に入るものを選ぼう。If it (   ) sunny tomorrow, we will go to the beach.  [ be / is / will be ]', hint: 'if の中は、未来のことでも現在形です。', steps: ['if は「もし〜なら」という条件を表している。', '条件の if の中は、未来のことでも現在形。will be は使わない。', '主語 it に合う be動詞の現在形は is。原形 be は主語の後ろに置けない。'], a: 'is(あした晴れたら、私たちは海辺へ行きます。)', check: '文の後半は we will go と will が使われていることを確かめ、未来の文であることと if の中の現在形が両立していることを確認します。' }] },
      { h: '「〜ということ」をまとめる that', t: '【that】は「〜ということ」という意味で、文を1つのかたまりにまとめます。think・know・hope・say などの後ろでよく使います。\nI think (that) he is right.(私は彼が正しいと思います。)\nI know (that) she likes music.(私は彼女が音楽が好きだということを知っています。)\nこの that はよく省略されます。省略しても意味は変わりません。\n「〜ではないと思う」は、ふつう think の方を否定して I don\'t think 〜 とします:I don\'t think it will rain.(雨は降らないと思います。)\nthat の後ろも「主語 + 動詞」のそろったふつうの文の形です。' }
    ],
    faq: [
      ['because と so は、どちらを使ってもいいの?', '同じ内容をどちらでも表せますが、文の並び方が逆になります。\n「原因 , so 結果」「結果 because 原因」です。どちらが原因かを先に決めてから使いましょう。'],
      ['When を文の最初に置いたら疑問文にならないの?', '後ろが「主語 + 動詞」のふつうの語順で、最後が ? でなければ、接続詞の when(〜するとき)です。\nWhen did you come?(いつ来ましたか。)は疑問詞、When I came home, 〜(帰ったとき、〜)は接続詞です。'],
      ['なぜ if の中では will を使わないの?', 'if・when の中は「もしそうなったら」という条件や時を表す部分で、英語ではこの部分を現在形で表すきまりがあるからです。\n未来であることは、文の後半の will で十分に伝わります。']
    ],
    terms: [['接続詞', '語と語、文と文をつなぐことば'], ['because', '〜なので(後ろに理由)'], ['so', 'だから(後ろに結果)'], ['if', 'もし〜なら(条件)'], ['when', '〜するとき(時)'], ['that', '「〜ということ」と文をまとめる。省略されることが多い']],
    miss: ['because と so を1つの文でいっしょに使う(× Because I was tired, so I went to bed.)。日本語の「〜ので、だから」を直訳するのが原因です。どちらか一方だけ使いましょう。', 'because と so の後ろに置く内容(原因と結果)を逆にする。because の後ろが原因、と先に確認しましょう。', 'if・when の中で will を使う(× If it will rain tomorrow, 〜)。if・when の中だけは現在形にします。', 'When・If の部分を前に置いたのにコンマをつけない。前に置いたら区切りのコンマを入れましょう。'],
    sum: ['まず日本語で2つの文の関係を考えてから、接続詞を選ぶ。', 'and はつけ足し、but は反対、or は選択、so は結果。', 'because の後ろは理由、so の後ろは結果。', 'when・if の文を前に置くときはコンマで区切る。', '時・条件の if・when の中は、未来のことでも現在形。'],
    next: '次は中3の「現在完了」(e_m7)へ進みましょう。過去から今へつながることを表す、新しい時制を学びます。受動態で覚えた過去分詞をそのまま使います。'
  };

  // ===== 中3の文法 =====
  L.e_m7 = {
    goal: '現在完了(have・has + 過去分詞)の3つの意味(継続・経験・完了)を見分け、過去形とのちがいを説明できるようになる。',
    intro: '過去形は「過去のある時のこと」だけを言い、今どうなっているかは言いません。それに対して【現在完了】は、【過去から今へつながっている】ことを表します。「ずっと〜している(継続)」「〜したことがある(経験)」「もう〜した(完了)」の3つの意味があり、いっしょに使われることばで見分けられます。',
    pre: '【過去分詞】は、受動態(be動詞 + 過去分詞)で使った動詞の形でした。規則動詞は過去形と同じ ed の形(played)、不規則動詞は1語ずつ覚えます(see ― saw ― seen、go ― went ― gone、eat ― ate ― eaten)。\n過去形は「過去のある時のこと」を表しました。I lived in Osaka.(私は大阪に住んでいました。)は、今のことは何も言っていません。\n主語が3人称単数(he・she・Ken など)のとき、have は has になりました。この単元の現在完了でも同じです。\nyesterday・last 〜・〜 ago は「過去のある時」をはっきり表すことばでした。',
    secs: [
      { h: '過去形と現在完了のちがい', t: '過去形と現在完了は、どちらも過去のことにふれますが、【どこから見ているか】がちがいます。\n過去形:I lived in Tokyo for five years.(私は5年間東京に住んでいました。)→ 過去の話。今は住んでいない。\n現在完了:I have lived in Tokyo for five years.(私は5年間ずっと東京に住んでいます。)→ 過去に住み始め、今も住んでいる。\n時間の線で考えると、過去形は「過去の部分だけ」、現在完了は「過去から今までをつなぐ線」です。\n「完了」という名前ですが、「今の時点から見て、過去からどうなっているか」を表す形だと考えましょう。',
        key: '現在完了は「今」から見て、過去から今までのつながりを表す。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="現在完了を表す時間の線。過去の点から今まで矢印がのびている"><line x1="10" y1="85" x2="205" y2="85" class="ax"/><path d="M198 80 L206 85 L198 90" class="ax"/><path d="M50 65 L170 65" class="cv"/><path d="M163 60 L171 65 L163 70" class="cv"/><line x1="50" y1="65" x2="50" y2="85" class="dash"/><line x1="175" y1="65" x2="175" y2="85" class="dash"/><circle cx="50" cy="85" r="4" class="pt"/><circle cx="175" cy="85" r="4" class="pt"/><text x="62" y="52">ずっと住んでいる</text><text x="30" y="104">住み始め</text><text x="170" y="104">今</text><text x="20" y="132">過去から今までつながる</text></svg>' },
      { h: '現在完了の形', t: '【have + 過去分詞】で作ります。主語が3人称単数なら【has】です。\nI have finished my homework.(私は宿題を終えました。)/She has finished her homework.(彼女は宿題を終えました。)\n短縮形:I have → I\'ve、he has → he\'s、have not → haven\'t、has not → hasn\'t\n現在完了は「今」に視点があるので、yesterday・last 〜・〜 ago・When 〜? など、【はっきり過去の時を表すことば】とはいっしょに使えません。\n× I have seen him yesterday. → ○ I saw him yesterday.(私はきのう彼に会いました。)',
        key: '現在完了 = have・has + 過去分詞。yesterday・〜 ago などとはいっしょに使わない。' },
      { h: '継続:ずっと〜している', t: '過去に始まった状態が今も続いていることを表します。\n【for + 期間】〜の間:for three years(3年間)、for a long time(長い間)\n【since + 始まった時点】〜から・〜以来:since 2020(2020年から)、since last Monday(この前の月曜日から)、since I was a child(子どものころから)\nShe has been sick since last Monday.(彼女はこの前の月曜日からずっと具合が悪い。)\nHow long 〜? で期間をたずねます:How long have you lived here?(ここにどのくらい住んでいますか。)— For ten years.(10年間です。)/ Since 2015.(2015年からです。)',
        ex: [{ q: '( )に for か since を入れよう。(1) I have known him (   ) ten years. (2) It has been cold (   ) yesterday.', hint: '後ろが「期間(長さ)」か「始まった時点」かを見ます。', steps: ['(1) ten years(10年)は時間の長さ=期間。', '期間を表すときは for → for ten years。', '(2) yesterday(きのう)は続き始めた時点 → since。'], a: '(1) for(私は10年間彼を知っています。) (2) since(きのうからずっと寒い。)', check: '「〜の間」と訳せれば for、「〜から」と訳せれば since になっていることを確かめます。' }] },
      { h: '経験:〜したことがある', t: '今までに経験したことを表します。\n目じるし:ever(今までに)、never(一度も〜ない)、before(以前に)、once(1回)、twice(2回)、〜 times(〜回)\nI have visited Kyoto twice.(私は京都を2回訪れたことがあります。)/Have you ever seen a koala?(今までにコアラを見たことがありますか。)\nI have never eaten natto.(私は一度も納豆を食べたことがありません。)How many times 〜? で回数をたずねます。\n【have been to 〜】〜へ行ったことがある(経験):I have been to Hokkaido.(私は北海道へ行ったことがあります。)\n【have gone to 〜】〜へ行ってしまった(今ここにいない):He has gone to America.(彼はアメリカへ行ってしまいました。)',
        ex: [{ q: '日本文に合う英文を書こう。(1) 私は一度もスキーをしたことがありません。(2) あなたは今までに沖縄へ行ったことがありますか。', hint: '(1) は never、(2) は ever と have been to を使います。', steps: ['(1)「一度も〜ない」は never。have と過去分詞の間に置く → I have never 〜。', '「スキーをする」は ski。過去分詞は skied → I have never skied.', '(2)「行ったことがある」は have been to。疑問文なので have を主語の前に出す。', 'ever は主語と過去分詞の間に置く → Have you ever been to Okinawa?'], a: '(1) I have never skied. (2) Have you ever been to Okinawa?', check: '(2) を have gone to にすると「行ってしまった」という意味になり、文として不自然になることを確かめます。' }] },
      { h: '完了:ちょうど〜したところだ・もう〜した', t: '動作が今までに終わったこと、その結果が今に残っていることを表します。\n目じるし:just(ちょうど)、already(もう・すでに)、yet(疑問文で「もう」、否定文で「まだ」)\nI have just finished my homework.(私はちょうど宿題を終えたところです。)/She has already left.(彼女はもう出発しました。)\nHave you eaten lunch yet?(もう昼食を食べましたか。)/I haven\'t eaten lunch yet.(まだ昼食を食べていません。)\njust・already は have と過去分詞の間、yet は文の最後に置きます。',
        ex: [{ q: '2つの文を、現在完了を使って1つの文にしよう。I lost my key. I still don\'t have it.(私はかぎをなくした。今もまだ見つかっていない。)', hint: '「なくした結果が今も続いている」ことを1文で表します。', steps: ['「なくした」結果が今も続いている → 現在完了(完了・結果)を使う。', 'have + 過去分詞。lose の過去分詞は lost。', '主語 I なので have lost → I have lost my key.'], a: 'I have lost my key.(私はかぎをなくしてしまいました。)', check: '過去形 I lost my key. だけでは、今見つかったかどうかは分からないことと比べて確かめます。' }] },
      { h: '否定文・疑問文と、3つの意味の見分け方', t: '【否定文】have・has の後ろに not:He has not(hasn\'t) read this book.\n【疑問文】have・has を主語の前へ:Has he read this book? — Yes, he has. / No, he hasn\'t.\ndo・does・did は使いません。have・has が助動詞のような役目をしているからです。\n3つの意味は、いっしょに使われることばで見分けます。for・since・How long → 継続/ever・never・once・〜 times → 経験/just・already・yet → 完了\n目じるしがないときは、文の内容と前後の流れから判断します。',
        ex: [{ q: '次の文の現在完了は、継続・経験・完了のどれ? (1) I have already cleaned my room. (2) We have lived here since 2018. (3) She has read this book three times.', hint: 'いっしょに使われている目じるしのことばを探します。', steps: ['(1) already(もう)があるので完了。「もう部屋をそうじしました」。', '(2) since 2018(2018年から)があるので継続。「2018年からここに住んでいます」。', '(3) three times(3回)があるので経験。「この本を3回読んだことがあります」。'], a: '(1) 完了 (2) 継続 (3) 経験', check: 'それぞれの訳に「もう〜した」「ずっと〜している」「〜したことがある」を当てはめて、自然な日本語になるか確かめます。' }] }
    ],
    faq: [
      ['なぜ yesterday と現在完了をいっしょに使えないの?', '現在完了は「今」から見たつながりを表す形なので、「きのう」という過去の一点だけを指すことばと合わないからです。\n過去の一点のことを言うなら、過去形を使います:I saw him yesterday.'],
      ['have been to と have gone to のちがいは?', 'have been to 〜 は「〜へ行ったことがある(今はもどっている)」という経験です。\nhave gone to 〜 は「〜へ行ってしまった(今はここにいない)」という完了・結果です。そのため、話し手自身について I have gone to 〜.(私は行ってしまって、ここにいない)と言うのは、ふつう不自然です。'],
      ['現在完了の have に「持っている」の意味はあるの?', 'ありません。この have は「現在完了の文だ」と示す助動詞の役目をしています。\nだから疑問文は Have you 〜? と前に出し、否定文は have not とします。do は使いません。']
    ],
    terms: [['現在完了', 'have・has + 過去分詞。過去から今へのつながりを表す'], ['継続', 'ずっと〜している(for・since・How long)'], ['経験', '〜したことがある(ever・never・once・〜 times)'], ['完了', 'ちょうど〜した・もう〜した(just・already・yet)'], ['for と since', 'for + 期間(〜の間)、since + 始まった時点(〜から)'], ['have been to と have gone to', '「行ったことがある」と「行ってしまった」']],
    miss: ['yesterday・〜 ago など過去を表すことばといっしょに現在完了を使う。過去の一点を言うときは過去形を使いましょう。', '経験の「行ったことがある」を have gone to とする(○ have been to)。gone は「行ってしまって今いない」です。', 'for と since を取りちがえる。後ろが長さなら for、始まりの時点なら since です。', 'have の後ろを過去形にする(× have went → ○ have gone)。過去形と過去分詞がちがう動詞は、セットで確認しましょう。'],
    sum: ['現在完了 = have・has + 過去分詞。過去形とちがい、今とつながる。', '継続は for・since・How long。', '経験は ever・never・回数。have been to は「行ったことがある」。', '完了は just・already・yet。', '否定文は have・has + not、疑問文は have・has を前へ。過去を表すことばとは使わない。'],
    next: '次は「現在完了進行形」(e_pperfprog)へ進みましょう。現在完了と進行形を組み合わせて、「ずっと〜し続けている」という動作の継続を表します。'
  };
  L.e_pperfprog = {
    goal: '現在完了進行形(have・has been + ing形)で「ずっと〜し続けている」を表し、現在完了(継続)との使い分けが分かるようになる。',
    intro: '「2時間ずっと勉強している」「けさからずっと雨が降り続いている」。過去に始まった【動作】が今も続いているときは、【現在完了進行形】を使います。現在完了(have + 過去分詞)と進行形(be + ing)を合体させた形です。',
    pre: '【現在完了】は have・has + 過去分詞で、過去から今へのつながりを表しました。「継続」の意味では for(期間)・since(始まった時点)といっしょに使いました。I have lived here for ten years.\n【進行形】は be動詞 + ing形で、動作の途中であることを表しました。He is studying now.\nbe動詞の過去分詞は【been】です(be ― was・were ― been)。\nlike・know・want などの【状態動詞】は進行形にしない、というルールがありました。この単元でもそのまま使います。',
    secs: [
      { h: '「動作」がずっと続いている', t: '現在完了の「継続」では、I have known him for ten years.(10年間彼を知っている)のように、【状態】が続いていることを表しました。\nでは、「2時間ずっと勉強している」のように、【動作】が続いているときはどうするのでしょうか。\nstudy のような動作は、ふつう「途中」を表すときに進行形にします。そこで、現在完了と進行形を組み合わせた【現在完了進行形】を使います。\n「過去のある時に始めた動作を、今もまだしている途中だ」というのが基本のイメージです。',
        key: '過去に始まった「動作」が今も続いているときは、現在完了進行形を使う。' },
      { h: '現在完了進行形の形', t: '【have・has been + 動詞の ing形】で「(過去から今まで)ずっと〜し続けている」を表します。\n組み立て:have + been(現在完了の部分。be の過去分詞)+ 〜ing(進行形の部分)= have been 〜ing\nI have been studying English for two hours.(私は2時間ずっと英語を勉強しています。)\nIt has been raining since this morning.(けさからずっと雨が降り続いています。)\n主語が3人称単数なら has been、それ以外は have been です。期間の for、始まった時点の since をよくいっしょに使います。',
        ex: [{ q: '( )内の語を使って、現在完了進行形の文にしよう。(1) I (play) the game for three hours. (2) My father (work) since eight o\'clock.', hint: 'have・has been + ing形 の3つの部分をそろえます。', steps: ['(1) 主語 I なので have been。play に ing をつけて playing → I have been playing the game for three hours.', '(2) 主語 my father は3人称単数なので has been。', 'work に ing をつけて working → My father has been working since eight o\'clock.'], a: '(1) have been playing(私は3時間ずっとそのゲームをしています。) (2) has been working(父は8時からずっと働いています。)', check: '3つの部分(have・has/been/ing形)のどれかが欠けていないか、1つずつ指でさして確かめます。' }] },
      { h: '現在完了(継続)との使い分け', t: '「ずっと〜している」は、動詞の種類で形を使い分けます。\n【状態】を表す動詞(be・know・like・want・have(持っている)など)→ 現在完了:I have known him for ten years.(× I have been knowing him.)/I have been busy since yesterday.(きのうからずっといそがしい。)\n【動作】を表す動詞(study・play・run・read・wait・rain など)→ 現在完了進行形:He has been playing the game for three hours.\nlive・work・stay・teach のように、状態とも動作とも考えられる動詞は、どちらの形も使えます。\nI have lived here for ten years. / I have been living here for ten years.(どちらも「私は10年間ここに住んでいます」)\n進行形のほうが、「今まさに続いている」感じが強く出ます。',
        key: '状態の「ずっと」は現在完了、動作の「ずっと」は現在完了進行形。',
        ex: [{ q: '( )内の動詞を「ずっと〜している」の形にしよう。(1) She (wait) for the bus for twenty minutes. (2) We (know) each other since we were children.', hint: '動詞が「動作」か「状態」かを先に考えます。', steps: ['(1) wait(待つ)は動作 → 現在完了進行形。', '主語 She は3人称単数なので has been waiting。', '(2) know(知っている)は状態 → 進行形にせず現在完了。', '主語 We なので have known。'], a: '(1) has been waiting(彼女は20分間ずっとバスを待っています。) (2) have known(私たちは子どものころからおたがいを知っています。)', check: '(2) を「知っている途中」と言いかえると不自然になることから、進行形にしないのが正しいと確かめます。' }] },
      { h: '否定文・疑問文の作り方', t: '現在完了と同じく、have・has を使って作ります。do・does は使いません。\n【否定文】have・has の後ろに not:I have not(haven\'t) been sleeping well recently.(私は最近ずっとよく眠れていません。)\n【疑問文】have・has を主語の前へ:Have they been running for an hour?(彼らは1時間ずっと走っているのですか。)\n【答え方】Yes, they have. / No, they haven\'t.\n答えには been や ing形はつけず、have・has だけで答えます。',
        ex: [{ q: 'He has been reading comics since lunch.(彼は昼食のあとからずっとまんがを読んでいます。)を疑問文にし、Yes で答えよう。', hint: 'has を主語の前に出します。been 以下はそのままです。', steps: ['現在完了進行形の疑問文は、has を主語 He の前に出す。', 'been reading comics since lunch はそのままの順で残す → Has he been reading comics since lunch?', '答えは has を使う → Yes, he has.'], a: 'Has he been reading comics since lunch? — Yes, he has.', check: 'Does he been 〜 のように does を使っていないか確かめます。' }] },
      { h: 'How long でたずねる', t: '「どのくらい(の間)〜し続けていますか」と期間をたずねるときは、【How long + have・has + 主語 + been + ing形 〜?】の形にします。\nHow long have you been waiting?(どのくらい待っていますか。)\n答え方は、期間なら For 〜.、始まった時点なら Since 〜. と短く言えます。\n— For thirty minutes.(30分です。)/ — Since three o\'clock.(3時からです。)\n文で答えるときは I have been waiting for thirty minutes. のようにします。',
        ex: [{ q: '「あなたはどのくらい(の時間)ピアノを練習していますか。」を英語にしよう。', hint: '期間をたずねるので How long で始め、その後ろは現在完了進行形の疑問文の語順にします。', steps: ['期間をたずねるので How long で始める。', 'practice(練習する)は動作 → 現在完了進行形の疑問文。have を主語 you の前に出す。', 'practice は e で終わるので e をとって practicing。', 'How long + have + you + been + practicing + the piano?'], a: 'How long have you been practicing the piano?', check: '答えの文 I have been practicing the piano for two hours. を作り、How long が for two hours の部分をたずねていることを確かめます。' }] },
      { h: 'これまでの「進行形」をくらべる', t: '進行形のなかまを、時間の線でくらべてみましょう。どれも「動作の途中」を表しますが、どの時点で途中なのかがちがいます。\n【現在進行形】am・is・are + ing:I am studying now.(今、勉強しているところ)→ 今この瞬間の途中\n【過去進行形】was・were + ing:I was studying at nine.(9時に勉強しているところだった)→ 過去のある時点の途中\n【現在完了進行形】have・has been + ing:I have been studying for two hours.(2時間ずっと勉強している)→ 過去に始まり、今まで続いている途中\nfor・since・How long があれば現在完了進行形、now があれば現在進行形、at nine last night のような過去の時点があれば過去進行形、と目じるしで判断できます。' }
    ],
    faq: [
      ['I have studied for two hours. と I have been studying for two hours. のちがいは?', 'どちらも「2時間勉強している」と訳せますが、進行形のほうが「今もまだ勉強を続けている途中」だとはっきり伝わります。\n現在完了だと、「2時間勉強した(そして今終えたところ)」という意味にとられることもあります。'],
      ['been はなぜ必要なの?', 'have の後ろには過去分詞がくるきまりがあり、進行形の be をここでは過去分詞 been にしているからです。\nhave + been(現在完了)と be + ing(進行形)が重なって、have been + ing になります。']
    ],
    terms: [['現在完了進行形', 'have・has been + ing形。動作が今までずっと続いている'], ['been', 'be の過去分詞'], ['状態動詞', 'know・like・be など。「ずっと」は現在完了で表す'], ['動作動詞', 'study・play・wait など。「ずっと」は現在完了進行形で表す'], ['How long 〜?', '「どのくらいの間」と期間をたずねる']],
    miss: ['been を忘れる(× I have studying.)。have の後ろには過去分詞が必要なので、been を入れます。', 'been を be にする(× I have be studying.)。have の後ろは過去分詞 been です。', 'know・like を現在完了進行形にする(× I have been knowing him.)。状態動詞は進行形にしないルールがここでも生きています。', '主語が3人称単数なのに have を使う(○ He has been 〜)。現在完了と同じく、主語で have・has を使い分けます。'],
    sum: ['現在完了進行形 = have・has been + ing形。', '動作の「ずっと」は現在完了進行形、状態の「ずっと」は現在完了。', 'live・work などはどちらの形も使える。', '否定文は have・has + not、疑問文は have・has を前へ。', 'How long have you been 〜ing? で期間をたずねる。'],
    next: '次は「分詞の形容詞的用法」(e_partm)へ進みましょう。ing形と過去分詞を、名詞を説明することばとして使う方法を学びます。'
  };
  L.e_partm = {
    goal: '現在分詞(ing形)と過去分詞を使って名詞を説明し、どちらを使うか・名詞の前か後ろかを正しく判断できるようになる。',
    intro: '「眠っている赤ちゃん」「割れた窓」「テニスをしている男の子」。このように名詞をくわしく説明するとき、英語では動詞の ing形や過去分詞を形容詞のように使います。これを分詞の【形容詞的用法】といいます。判断のポイントは2つ、【する側か、される側か】と【何語か】です。',
    pre: '【形容詞】は名詞を説明することばで、ふつう名詞の前に置きました:a big dog(大きい犬)、a new car(新しい車)。\n【進行形】は be動詞 + ing形で「〜している」を表しました:The baby is sleeping.(赤ちゃんは眠っています。)\n【受動態】は be動詞 + 過去分詞で「〜される」を表しました:The window was broken.(窓は割られた。)\n不定詞の形容詞的用法では、something to drink(何か飲むもの)のように、説明が名詞の後ろにきました。この単元でも「後ろから説明する」形が出てきます。',
    secs: [
      { h: '分詞とは', t: '動詞の ing形を【現在分詞】、受動態で使った形を【過去分詞】といい、2つをまとめて【分詞】と呼びます。\n分詞は、進行形や受動態で使うだけでなく、形容詞のように【名詞を説明する】こともできます。\na sleeping baby(眠っている赤ちゃん)→ sleeping が baby を説明\na broken window(割れた窓)→ broken が window を説明\n「現在」「過去」という名前がついていますが、時制とは関係ありません。現在分詞は「〜している」、過去分詞は「〜された」という意味の形、と考えましょう。',
        key: '分詞は名詞を説明できる。現在分詞は「〜している」、過去分詞は「〜された」。' },
      { h: '現在分詞か過去分詞か', t: '説明される名詞と、動詞との関係を考えます。\n【名詞が「〜している」(する側)】→ 現在分詞(ing形)\na sleeping baby(眠っている赤ちゃん)→ 赤ちゃんが眠る(する側)\n【名詞が「〜される・〜された」(される側)】→ 過去分詞\na broken window(割られた窓 → 割れた窓)→ 窓が割られる(される側)\n迷ったら、「名詞 + is + 分詞」の文を作ってみましょう。The baby is sleeping.(進行形)なら ing形、The window is broken.(受動態)なら過去分詞です。',
        key: '名詞が「する側」なら ing形、「される側」なら過去分詞。',
        ex: [{ q: '( )内の動詞を、現在分詞か過去分詞にしよう。(1) a (cry) baby (2) a (use) car (3) (fall) leaves', hint: '名詞が「〜している」のか「〜される」のかを考えます。', steps: ['(1) 赤ちゃんは泣いている(する側)→ 現在分詞 crying →「泣いている赤ちゃん」。', '(2) 車は人に使われた(される側)→ 過去分詞 used →「中古車(使われた車)」。', '(3) 葉は落ちている(する側)→ 現在分詞 falling →「落ちている葉」。'], a: '(1) crying (2) used (3) falling', check: 'The baby is crying. / The car was used. / The leaves are falling. と文にして、進行形・受動態として自然か確かめます。' }] },
      { h: '1語なら前、2語以上なら後ろ', t: '【分詞1語だけ】→ 名詞の前に置きます。ふつうの形容詞と同じです。\na running dog(走っている犬)、used cars(中古車=使われた車)\n【分詞に語句がついて2語以上】→ 名詞の後ろに置きます。\nthe boy playing tennis(テニスをしている男の子)/a car made in Japan(日本で作られた車)/a letter written in English(英語で書かれた手紙)\n説明が長くなると、名詞の前に置くと読みにくくなるので、英語では後ろに回すのです。\n日本語では「テニスをしている → 男の子」の順ですが、英語では「男の子 → テニスをしている」の順になります。',
        ex: [{ q: '日本文に合うように[ ]の語を並べかえよう。「ドアのそばに立っている女の子はユミです。」 [ standing / the / girl / by ] the door is Yumi.', hint: '「ドアのそばに立っている」は2語以上なので、名詞の後ろに置きます。', steps: ['「女の子」は立っている側 → 現在分詞 standing。', 'standing by the door は2語以上なので、名詞 the girl の後ろに置く。', 'The girl standing by the door が主語、is が動詞。'], a: 'The girl standing by the door is Yumi.', check: '主語のかたまりから standing by the door を取ると The girl is Yumi. となり、文の骨組みが正しいことを確かめます。' }] },
      { h: '後ろから説明する分詞の練習', t: '手順は、①説明される名詞を見つける ②その名詞が「する側」か「される側」かを考える ③分詞の位置(前か後ろか)を決める、の3つです。\nLook at the dancing girls.(おどっている女の子たちを見て。)→ 1語なので前\nThis is a picture taken by my father.(これは父がとった写真です。)→ 写真は「とられた」側で、by my father がつくので後ろ\nThe language spoken in Brazil is Portuguese.(ブラジルで話されている言語はポルトガル語です。)',
        ex: [{ q: '( )内の動詞を正しい形にしよう。(1) Look at the (sleep) cat. (2) I have a bag (make) in Italy.', hint: '「する側・される側」と「語の数」の2つで判断します。', steps: ['(1) ねこは眠っている(する側)→ 現在分詞 sleeping。', '1語なので名詞 cat の前に置く(すでに前の位置にある)。', '(2) かばんはイタリアで作られた(される側)→ 過去分詞 made。', 'in Italy がついて2語以上なので名詞 a bag の後ろ(すでに後ろの位置にある)。'], a: '(1) sleeping(眠っているねこを見て。) (2) made(私はイタリアで作られたかばんを持っています。)', check: '(2) を The bag was made in Italy. と受動態の文にして、意味が通るか確かめます。' }] },
      { h: '主語が長くなる文に注意', t: '「名詞 + 分詞 + 語句」のかたまりが主語になると、主語が長くなります。\nThe boy playing tennis is my brother.(テニスをしている男の子は私の兄です。)\n→ 主語は The boy playing tennis(ここまでで1つのかたまり)、動詞は is。\n文の動詞の形は、かたまりの中心の名詞(the boy)に合わせます。tennis の後ろにあるからといって、動詞を tennis に合わせるのではありません。\nThe students living in this town are kind.(この町に住んでいる生徒たちは親切です。)→ 中心は students(複数)なので are。',
        ex: [{ q: '( )に is と are のどちらかを入れよう。(1) The girls singing on the stage (   ) my classmates. (2) The book written by him (   ) very popular.', hint: 'かたまりの中心になる名詞を見つけます。', steps: ['(1) 主語のかたまりは The girls singing on the stage。中心の名詞は girls(複数)。', '複数なので are。stage(単数)につられないようにする。', '(2) 主語のかたまりは The book written by him。中心の名詞は book(単数)→ is。'], a: '(1) are(ステージで歌っている女の子たちは私のクラスメートです。) (2) is(彼によって書かれた本はとても人気があります。)', check: '分詞のかたまりを取って The girls are my classmates. / The book is very popular. としても正しいことを確かめます。' }] },
      { h: '関係代名詞とのつながり・exciting と excited', t: '後ろから説明する分詞は、関係代名詞を使った文から「関係代名詞 + be動詞」を取ったものと考えられます(関係代名詞は次の単元で学びます)。\nthe boy who is playing tennis = the boy playing tennis/a car which was made in Japan = a car made in Japan\nまた、気持ちを表す分詞にも同じ考え方が使えます。excite は「わくわくさせる」という意味の動詞です。\n【exciting】(人を)わくわくさせるような:The game was exciting.(その試合はわくわくするものだった。)→ 試合が人をわくわくさせる(する側)\n【excited】(人が)わくわくした:I was excited.(私はわくわくした。)→ 私がわくわくさせられた(される側)\ninteresting(おもしろい)と interested(興味をもった)、surprising(おどろくべき)と surprised(おどろいた)も同じ関係です。' }
    ],
    faq: [
      ['a sleeping baby と a baby sleeping は、どちらも正しい?', '分詞1語だけのときは、ふつう名詞の前に置いて a sleeping baby とします。\nin the bed のような語句がつくと、a baby sleeping in the bed のように後ろに置きます。'],
      ['The boy playing tennis is my brother. の playing は進行形ではないの?', '進行形なら前に be動詞が必要です。ここでは playing の前に be動詞がなく、playing tennis が the boy を説明しているので、分詞の形容詞的用法です。\nこの文の動詞は is の1つだけです。'],
      ['過去分詞は、なぜ「過去」という名前なの?', '昔の文法用語の名残で、実際には時制とは関係ありません。\na car made in Japan は、今作られている車にも、昔作られた車にも使えます。「される側」を表す形、と覚えましょう。']
    ],
    terms: [['分詞', '現在分詞(ing形)と過去分詞をまとめた呼び名'], ['現在分詞', 'ing形。名詞を説明するときは「〜している」'], ['過去分詞', '名詞を説明するときは「〜される・〜された」'], ['形容詞的用法', '分詞が名詞を説明する使い方'], ['後置修飾', '名詞を後ろから説明すること'], ['exciting と excited', '「(人を)わくわくさせる」と「(人が)わくわくした」']],
    miss: ['2語以上なのに名詞の前に置く(× a playing tennis boy → ○ a boy playing tennis)。日本語の語順のまま並べるのが原因です。語句がついたら後ろ、と確認しましょう。', 'する側・される側を逆にする(× a breaking window → ○ a broken window)。「名詞 + is + 分詞」の文にして確かめましょう。', '主語が長くなって動詞の形をまちがえる(× The boy playing tennis are 〜)。かたまりの中心の名詞に動詞を合わせます。', '「わくわくさせる」exciting と「(人が)わくわくした」excited を取りちがえる。人の気持ちなら -ed、ものの性質なら -ing が基本です。'],
    sum: ['名詞が「する側」なら ing形、「される側」なら過去分詞。', '分詞1語なら名詞の前、2語以上なら名詞の後ろ。', '名詞 + 分詞のかたまり全体が、1つの名詞の働きをする。', '文の動詞は、かたまりの中心の名詞に合わせる。', 'exciting は「わくわくさせる」、excited は「わくわくした」。'],
    next: '次は「関係代名詞」(e_m8)へ進みましょう。分詞と同じように名詞を後ろから説明しますが、who・which・that を使って「主語 + 動詞」のある文で説明できるようになります。'
  };
  L.e_m8 = {
    goal: '関係代名詞(who・which・that)を使って名詞を後ろから説明し、主格と目的格を見分けられるようになる。',
    intro: '「カナダに住んでいる友だち」「私がきのう買った本」。日本語では説明が名詞の前にきますが、英語では【名詞の後ろに文をつなげて説明】します。そのつなぎ役が【関係代名詞】です。判断は「説明される名詞は人か物か」「後ろの文で何が欠けているか」の2段階です。',
    pre: '英語の文の骨組みは「主語 → 動詞 → 目的語」でした。He lives in Canada. では he が主語、I bought it. では it が目的語(〜を)です。\n代名詞には、主語の形(I・he・she・it・they)と、目的語の形(me・him・her・it・them)がありました。この「主語か目的語か」の区別が、この単元で大切になります。\n分詞の形容詞的用法では、the boy playing tennis のように、名詞の後ろに説明を置きました。\n英語では、長い説明は名詞の後ろに置く、という考え方を思い出しておきましょう。',
    secs: [
      { h: 'なぜ関係代名詞が必要なのか', t: '分詞を使うと、the boy playing tennis(テニスをしている男の子)のように名詞を後ろから説明できました。\nしかし「私がきのう買った本」のように、説明の中に「私が」という主語がある場合は、分詞では表せません。\nそこで、名詞の後ろに「主語 + 動詞」のある文を丸ごとつなげる方法が必要になります。そのつなぎ役が【関係代名詞】です。\n2つの文を「関係」づけ、代名詞のかわりをするので、関係代名詞と呼ばれます。',
        key: '関係代名詞は、名詞の後ろに文をつなげて、その名詞を説明するためのつなぎ役。' },
      { h: '関係代名詞のはたらき', t: '関係代名詞は、2つの文を1つにまとめて、名詞を後ろからくわしく説明します。\nI have a friend. + He lives in Canada.\n→ I have a friend who lives in Canada.(私にはカナダに住んでいる友だちがいます。)\n説明される名詞(ここでは a friend)を【先行詞】といいます。「先に行く(前にある)ことば」という意味です。\n関係代名詞 who は、2つ目の文の he のかわりになっています。だから、後ろの文から he は消えます。' },
      { h: '主格の who・which・that', t: '関係代名詞が、後ろの文の【主語】のかわりをするものを【主格】といいます。後ろにはすぐ動詞がきます。\n先行詞が人 → 【who】(that も可):The man who is talking with Ken is our teacher.(ケンと話している男性は私たちの先生です。)\n先行詞が物・動物 → 【which】(that も可):This is a bus which goes to the station.(これは駅へ行くバスです。)\n後ろの動詞の形は、先行詞に合わせます。a friend who lives(先行詞が単数なので s がつく)/friends who live(複数なので s なし)\n主格の関係代名詞は省略できません。省略すると、動詞が2つ並んだ文になってしまうからです。',
        key: '先行詞が人なら who、物・動物なら which。that はどちらにも使える。',
        ex: [{ q: '( )に入る語は? (1) I have a friend (   ) lives in Canada. (2) Look at the dog (   ) is running over there.', hint: '先行詞が人か物・動物か、後ろがすぐ動詞かを見ます。', steps: ['(1) 先行詞 a friend は人。後ろがすぐ動詞 lives → 主格 → who。', '(2) 先行詞 the dog は動物。', '後ろがすぐ動詞 is → 主格 → which(that も可)。'], a: '(1) who(私にはカナダに住んでいる友だちがいます。) (2) which(あそこで走っている犬を見て。)', check: '関係代名詞を he・it にかえると He lives in Canada. / It is running over there. という文になり、主語のかわりだと確かめられます。' },
          { q: '2つの文を、関係代名詞を使って1つにしよう。I know a girl. + She can speak three languages.', hint: 'She が a girl を指していることを確認し、She を関係代名詞にかえます。', steps: ['2つ目の文の She は1つ目の文の a girl を指している → 先行詞は a girl(人)。', 'She は2つ目の文の主語 → 主格の who を使う。', 'She を who にかえ、a girl の直後に置く。She は書かない。'], a: 'I know a girl who can speak three languages.(私は3か国語を話せる女の子を知っています。)', check: '先行詞 a girl のすぐ後ろに who があり、who の後ろがすぐ動詞(can speak)になっていることを確かめます。' }] },
      { h: '目的格の which・that と省略', t: '関係代名詞が、後ろの文の【目的語】のかわりをするものを【目的格】といいます。後ろには「主語 + 動詞」が続き、動詞の目的語がぬけています。\nThis is the book. + I bought it yesterday. → This is the book which(that) I bought yesterday.(これは私がきのう買った本です。)\nbought の後ろにあった it は、which になって前に移動したので、もう書きません。\n先行詞が人のときは、目的格では that を使うのがふつうです:The girl that I met yesterday was kind.(私がきのう会った女の子は親切でした。)\n【目的格の関係代名詞は省略できます】:This is the book I bought yesterday.\n省略しても、名詞のすぐ後ろに「主語 + 動詞」が続くことで、説明が始まっていると分かるからです。',
        key: '目的格は後ろが「主語 + 動詞」。目的格の関係代名詞は省略できる。',
        ex: [{ q: '2つの文を、関係代名詞を使って1つにしよう。This is the picture. + My father took it in Kyoto.', hint: 'it が何を指し、文の中で主語か目的語かを考えます。', steps: ['it は the picture を指している → 先行詞は the picture(物)。', 'it は took の目的語 → 目的格 → which(that)。', 'it を which にかえて、the picture の直後に置く。', 'took の後ろの it は書かない → my father took in Kyoto。'], a: 'This is the picture which(that) my father took in Kyoto.(これは父が京都でとった写真です。)※which・that は省略して This is the picture my father took in Kyoto. としてもよい。', check: 'took の後ろに it が残っていないか(the picture which my father took it としていないか)確かめます。' }] },
      { h: '主格か目的格かの見分け方', t: '関係代名詞のすぐ後ろを見れば見分けられます。\n【後ろがすぐ動詞】→ 主格:a friend who lives in Canada(lives が動詞)\n【後ろが「主語 + 動詞」】→ 目的格:the book which I bought(I が主語、bought が動詞)\n主格は省略できない、目的格は省略できる、というちがいもこの見分け方とつながっています。\nまた、名詞のすぐ後ろに「主語 + 動詞」が続いていたら、目的格の関係代名詞が省略されていると考えましょう:the woman I met yesterday(私がきのう会った女性)',
        ex: [{ q: '次の文で、関係代名詞を省略できるのはどちら? (1) The man who lives next door is a doctor. (2) The cake which my mother made was delicious.', hint: '関係代名詞のすぐ後ろが動詞か「主語 + 動詞」かを見ます。', steps: ['(1) who の後ろはすぐ動詞 lives → 主格 → 省略できない。', '(2) which の後ろは my mother(主語)+ made(動詞)→ 目的格 → 省略できる。', '(2) を省略すると The cake my mother made was delicious. となる。'], a: '(2)(母が作ったケーキはおいしかった。)※(1) は「となりに住んでいる男性は医者です」で、who は省略できない。', check: '(1) の who を取ると The man lives next door is a doctor. となり、動詞が2つ並ぶ不自然な文になることを確かめます。' }] },
      { h: 'that がよく使われる場面・whose(発展)', t: '【that がよく使われる場面】先行詞に the first・the only・最上級・all・every などがつくときや、先行詞が「人と物(動物)」の両方のとき。\nThis is the best movie that I have ever seen.(これは私が今までに見た中で一番よい映画です。)\nHe is the only student that knows the answer.(彼はその答えを知っている唯一の生徒です。)\n【whose】「その〜の」と持ち主を表します(発展)。\nI know a girl whose father is a pilot.(私は、お父さんがパイロットをしている女の子を知っています。)→ a girl の father' }
    ],
    faq: [
      ['who と that は、どちらを使えばいいの?', '先行詞が人で主格なら、who を使うのが最もふつうです。that でもまちがいではありません。\n先行詞が物なら which と that のどちらでもかまいません。迷ったら、人は who、物は which と決めておくと安心です。'],
      ['関係代名詞の who と、疑問詞の who はどうちがうの?', '疑問詞の who は「だれ」とたずねることばで、文の最初にきて最後は ? になります。\n関係代名詞の who は名詞のすぐ後ろにきて、その名詞を説明します。「だれ」とは訳しません。'],
      ['目的格を省略すると、どこからが説明か分からなくならない?', '名詞のすぐ後ろに「主語 + 動詞」が続いたら、そこから説明が始まる、と考えれば分かります。\nthe book I bought の book と I の間に which が省略されています。']
    ],
    terms: [['関係代名詞', '名詞の後ろに文をつなげて説明するつなぎのことば'], ['先行詞', '関係代名詞が説明する名詞'], ['主格', '関係代名詞が後ろの文の主語のかわり。後ろはすぐ動詞'], ['目的格', '関係代名詞が後ろの文の目的語のかわり。後ろは「主語 + 動詞」。省略できる'], ['who', '先行詞が人のときの関係代名詞'], ['which', '先行詞が物・動物のときの関係代名詞']],
    miss: ['目的格なのに、後ろの文に目的語を残す(× the book which I bought it)。関係代名詞が it のかわりになって前に出た、と考えて消しましょう。', '先行詞と動詞の形を合わせない(× a friend who live)。関係代名詞の後ろの動詞は、先行詞が単数か複数かに合わせます。', '先行詞が人なのに which を使う。先行詞が人か物かを最初に確認しましょう。', '主格の関係代名詞を省略する(× I have a friend lives in Canada.)。省略できるのは目的格だけです。'],
    sum: ['関係代名詞は、名詞の後ろに文をつなげて説明する。', '先行詞が人なら who、物なら which、that はどちらにも使える。', '後ろがすぐ動詞なら主格、「主語 + 動詞」なら目的格。', '目的格は省略できる。主格は省略できない。', '関係代名詞のかわりになった語は、後ろの文から消す。'],
    next: '次は「間接疑問文」(e_indq)へ進みましょう。疑問文を別の文の中に入れる方法を学びます。「文の中に入ると語順が変わる」点が、関係代名詞と並ぶ中3の重要ポイントです。'
  };
  L.e_indq = {
    goal: '疑問文を文の中に入れた「間接疑問文」を、「疑問詞 + 主語 + 動詞」の語順で正しく作れるようになる。',
    intro: '「彼はどこに住んでいますか。」をそのまま聞くかわりに、「彼がどこに住んでいるか知っていますか。」と聞くこともあります。このように、疑問文が別の文の一部になったものを【間接疑問文】といいます。最大のポイントは、【文の中に入ると、ふつうの文の語順にもどる】ことです。',
    pre: '疑問詞の文は「疑問詞 + ふつうの疑問文の語順」でした。Where does he live? / What is this? / When did she come?\nふつうの文(肯定文)の語順は「主語 + 動詞」です:He lives in Osaka. / This is a map.\n一般動詞の疑問文では do・does・did を使い、後ろの動詞は原形にしました。肯定文にもどすと、does の s や did の過去が動詞にもどります(does live → lives、did come → came)。\nWho plays the piano? のように、疑問詞が主語の文は、もともと「疑問詞(主語)+ 動詞」の語順でした。',
    secs: [
      { h: '間接疑問文とは', t: '疑問文を、I know(私は知っている)や Do you know(知っていますか)などの文の中に入れたものを【間接疑問文】といいます。\n直接たずねる Where does he live?(彼はどこに住んでいますか。)に対して、文の中に入れて間接的に言うので「間接疑問」と呼ばれます。\nDo you know where he lives?(彼がどこに住んでいるか知っていますか。)\nI don\'t know where he lives.(私は彼がどこに住んでいるか知りません。)\n日本語では「どこに住んでいる【か】」のように「か」がつく部分が、間接疑問にあたります。' },
      { h: '間接疑問文の語順', t: 'Where does he live? → Do you know where he lives?\n文の中に入った疑問文は、【疑問詞 + 主語 + 動詞】のふつうの文の語順になります。\nなぜでしょうか。文の中に入ると、その部分はもう「質問」ではなく、「彼がどこに住んでいるか」という1つの名詞のかたまりになるからです。質問の語順にする必要がなくなるのです。\ndo・does・did はなくなり、動詞は主語や時制に合った形にもどります。上の例では、does にふくまれていた3単現の s が live にもどって lives になります。',
        key: '間接疑問文の中は「疑問詞 + 主語 + 動詞」のふつうの語順。do・does・did は消える。' },
      { h: '作り方の手順', t: '①元の疑問文から疑問詞を取り出す。\n②残りを「主語 + 動詞」のふつうの文の語順にする(do・does・did は消し、動詞の形を直す)。\n③know・tell me・ask などの後ろに「疑問詞 + 主語 + 動詞」を置く。\nbe動詞の文:What is this? → I don\'t know what this is.(これが何なのか分かりません。)\n一般動詞の過去の文:When did she come? → Tell me when she came.(彼女がいつ来たか教えてください。)\n助動詞の文:What can I do? → I don\'t know what I can do.(私に何ができるか分かりません。)',
        ex: [{ q: '2つの文を1つにしよう。I know. + Where does Ken live?', hint: '①疑問詞を取り出す ②残りをふつうの文の語順に ③ I know の後ろに置く、の順です。', steps: ['疑問詞 where を取り出す。', '残り does Ken live を「主語 + 動詞」にする。does を消す。', 'does にふくまれていた3単現の s を動詞にもどすので、live → lives。', 'I know の後ろに where Ken lives を置く。'], a: 'I know where Ken lives.(私はケンがどこに住んでいるか知っています。)', check: 'where Ken lives の部分だけを取り出すと、Ken lives 〜. というふつうの文の語順になっていることを確かめます。' },
          { q: '2つの文を1つにしよう。(1) Please tell me. + What did you buy? (2) I don\'t know. + Who is that man?', hint: '(1) は did を消して過去形に、(2) は be動詞を主語の後ろに移します。', steps: ['(1) 疑問詞 what を取り出し、残り did you buy をふつうの文にする。', 'did を消し、過去のしるしを動詞にもどして buy → bought → what you bought。', '(2) 疑問詞 who を取り出し、残り is that man を「主語 + 動詞」の順にする → who that man is。', 'それぞれを外側の文の後ろに置く。'], a: '(1) Please tell me what you bought.(あなたが何を買ったか教えてください。) (2) I don\'t know who that man is.(私はあの男性がだれなのか知りません。)', check: '(2) で who is that man のまま入れていないか、is が文の最後に移っているか確かめます。' }] },
      { h: '疑問詞が主語のとき・疑問詞のかたまり', t: '【疑問詞が主語】のときは、元の疑問文がもともと「疑問詞(主語) + 動詞」の語順なので、そのまま入れます。\nWho broke the window? → I know who broke the window.(だれが窓を割ったか知っています。)\n【How many 〜・What time などのかたまり】は、かたまりのまま前に置きます。\nHow many books does he have? → I know how many books he has.(彼が何冊本を持っているか知っています。)\nWhat time is it? → Do you know what time it is?(今何時か分かりますか。)',
        ex: [{ q: '日本文に合うように[ ]の語を並べかえよう。「この本がいくらか教えてください。」 Please tell me [ is / much / this book / how ].', hint: 'How much はかたまりのまま前に置きます。', steps: ['元の疑問文は How much is this book?。', 'How much はかたまりのまま前に置く。', '残りを「主語(this book) + 動詞(is)」の順にする。'], a: 'Please tell me how much this book is.', check: 'how much is this book の順になっていないか、is が最後にきているか確かめます。' }] },
      { h: '文全体の形(肯定・否定・疑問)', t: '文全体が肯定文・否定文・疑問文のどれになるかは、【外側の文】で決まります。中の「疑問詞 + 主語 + 動詞」の部分は変わりません。\n【肯定文】I know where he lives.(私は彼がどこに住んでいるか知っています。)\n【否定文】I don\'t know where he lives.(私は彼がどこに住んでいるか知りません。)\n【疑問文】Do you know where he lives?(彼がどこに住んでいるか知っていますか。)\n【答え方】外側の Do you know 〜? に答えるので、Yes, I do. / No, I don\'t. で答えます。Yes と答えたあとに、He lives in Kobe.(神戸に住んでいます。)のように内容をつけ加えると親切です。\n文の最後の記号も外側で決まります。I don\'t know 〜 は「.」、Do you know 〜 は「?」です。',
        key: '文全体の形と最後の記号は、外側の文で決まる。中の語順は変わらない。',
        ex: [{ q: '日本文に合う英文を書こう。「あなたはその店が何時に開くか知っていますか。— はい、知っています。10時に開きます。」', hint: '元の疑問文 What time does the shop open? を、Do you know の後ろに入れます。', steps: ['元の疑問文は What time does the shop open?。What time はかたまりのまま前に置く。', 'does を消し、主語 the shop は3人称単数なので open → opens → what time the shop opens。', '外側の文は Do you know 〜? なので、最後は ? にする。', '答えは外側の Do you know に答えて Yes, I do.、内容は It opens at ten. とつけ加える。'], a: 'Do you know what time the shop opens? — Yes, I do. It opens at ten.', check: '答えの It opens at ten. の語順が、間接疑問の中の the shop opens と同じ「主語 + 動詞」になっていることを確かめます。' }] }
    ],
    faq: [
      ['なぜ文の中に入ると語順が変わるの?', '文の中に入った疑問文は、もう相手への質問ではなく、「彼がどこに住んでいるか」という1つのかたまり(名詞のような働き)になるからです。\n質問ではないので、質問の語順にする必要がなく、ふつうの文の語順にもどります。'],
      ['間接疑問文の最後は、いつも ? になるの?', 'なりません。最後の記号は外側の文で決まります。\nI know 〜. や Tell me 〜. なら「.」、Do you know 〜? や Can you tell me 〜? なら「?」です。'],
      ['間接疑問文と関係代名詞は、どちらも「疑問詞 + 主語 + 動詞」に見えるけど?', 'たしかに形は似ていますが、間接疑問文は know・tell などの後ろで「〜か」という意味を表します。\n関係代名詞は名詞のすぐ後ろで、その名詞を説明します。直前に名詞(先行詞)があるかどうかで見分けましょう。']
    ],
    terms: [['間接疑問文', '疑問文が別の文の一部になったもの'], ['直接疑問文', 'Where does he live? のように、直接たずねるふつうの疑問文'], ['語順', '間接疑問文の中は「疑問詞 + 主語 + 動詞」'], ['外側の文', 'I know・Do you know などの部分。文全体の形を決める']],
    miss: ['疑問文の語順のまま入れる(× Do you know where does he live?)。外側の Do you know の疑問文につられるのが原因です。中はふつうの文の語順、と確認しましょう。', 'does を消したのに s をつけ忘れる(× where he live → ○ where he lives)。does の s を動詞にもどす、と覚えましょう。', 'did を消したのに動詞を原形のままにする(× when she come → ○ when she came)。did の「過去」も動詞にもどします。', 'Do you know 〜? に、中の内容だけで答えて Yes・No を言わない。まず外側の質問に Yes・No で答えます。'],
    sum: ['間接疑問文の中は「疑問詞 + 主語 + 動詞」。', 'do・does・did は消し、動詞の形を主語・時制に合わせる。', '疑問詞が主語なら、そのままの語順で入れる。', 'How many 〜・What time などはかたまりのまま前に置く。', '文全体の形と最後の記号は、外側の文で決まる。'],
    next: '次は「難関:中学英語の並べかえ」(ex_jh3)に挑戦しましょう。関係代名詞・分詞・不定詞・間接疑問など、中学で学んだ語順の型を組み合わせて英文を組み立てます。'
  };

  // ===== 中学英単語 =====
  L.e_vocab_m = {
    goal: '中学英単語を、2段階の確認とくり返しで効率よく覚え、品詞・語形変化・反対語などで整理して使えるようになる。',
    intro: '中学校で学ぶ英単語は、およそ1600〜1800語です。一度に全部覚えようとすると、すぐに忘れてしまいます。大切なのは【少しずつ、何度も】見ることと、ばらばらに覚えずに【仲間ごとに整理する】ことです。この単元では、忘れにくい覚え方を紹介します。',
    pre: '英単語は、アルファベット26文字の組み合わせでできています。a・e・i・o・u の5つを【母音字】、それ以外を【子音字】といいます。\nつづりと発音は、日本語のかなほど一対一ではありません。たとえば a は cat では「ア」、name では「エイ」と読みます。だから、つづりだけでなく音もいっしょに覚えることが大切です。\n動詞の過去形(play → played)、名詞の複数形(book → books)、形容詞の比較級(tall → taller)のように、単語には形が変わるものがあります。\nこれまでの文法の単元で見た「子音字 + y は y を i にかえる」などのつづりのルールは、単語を覚えるときにも役立ちます。',
    secs: [
      { h: '覚え方は「2段階」', t: '単語は次の2段階で確認します。\n①英語を見て、意味が言える(読める)\n②意味を見て、英語が言える・書ける(使える)\n①ができても②ができないことはよくあります。読めるだけの単語は、英作文や並べかえでは使えません。両方を確認しましょう。\n確認するときは、答えをかくして自分でテストします。見て「分かったつもり」になるだけでは、記憶に残りにくいからです。',
        key: '「英語 → 意味」と「意味 → 英語」の両方向で確認する。' },
      { h: '忘れにくくする「くり返し」と「音・例文」', t: '人は覚えたことを、時間とともに忘れていきます。これはだれにでも起こることなので、気にしなくて大丈夫です。\n大切なのは、【忘れかけたころに見直す】ことです。1日目に覚えたら、次の日、3日後、1週間後と、間をあけて何度も見直すと記憶に残りやすくなります。\nまた、【音を聞いて、声に出す】ことも効果的です。目・耳・口を使うと、記憶の手がかりがふえます。\n【例文の中で覚える】と、使い方も身につきます。I\'m hungry.(おなかがすいた。)のように、短い文ごと覚えましょう。',
        key: '間をあけて何度も見直す。音と例文もいっしょに覚える。' },
      { h: '品詞で整理する', t: '単語は働きによって【品詞】に分けられます。品詞が分かると、文のどこに置けばよいかが分かります。\n【名詞】もの・人・ことの名前:book、teacher、music/【動詞】動作・状態:run、eat、know\n【形容詞】名詞のようす:big、happy、beautiful/【副詞】動詞や形容詞をくわしくする:fast、very、slowly\n【前置詞】名詞の前に置いて、場所・時などを表す:in、on、at、for/【接続詞】文と文をつなぐ:and、but、because\n単語帳で覚えるときも、「動詞の run」のように品詞をいっしょに確認しておくと、使いまちがいが減ります。',
        ex: [{ q: '次の文の (1)〜(3) の語の品詞を答えよう。She runs very fast. の (1) runs (2) very (3) fast', hint: 'それぞれの語が、文の中で何をくわしくしているかを考えます。', steps: ['(1) runs は「走る」という動作を表す → 動詞。', '(2) very は fast を「とても」とくわしくしている。形容詞や副詞をくわしくするのは副詞。', '(3) fast は runs(動詞)を「速く」とくわしくしている → 副詞。'], a: '(1) 動詞 (2) 副詞 (3) 副詞(彼女はとても速く走ります。)', check: 'a fast car(速い車)の fast は名詞 car を説明しているので形容詞になる、と比べて、置かれた場所で品詞が決まることを確かめます。' }] },
      { h: '語尾で品詞を知る・仲間をふやす', t: '語の終わりの部分(語尾)が、品詞の目じるしになることがあります。\n・-tion・-ment・-ness は名詞が多い:information(情報)、kindness(親切)\n・-ful・-ous は形容詞が多い:useful(役に立つ)、famous(有名な)\n・-ly は副詞が多い:quickly(すばやく)、slowly(ゆっくりと)(ただし friendly(親しみやすい)は形容詞)\n同じ仲間の語をまとめて覚えると、1語から何語も広がります。happy(幸せな)→ happily(幸せに)→ happiness(幸せ)',
        ex: [{ q: '( )内の語を、文に合う形にかえよう。(1) Thank you for your (kind).(ご親切にありがとう。) (2) This dictionary is very (use).(この辞書はとても役に立ちます。)', hint: '( )の位置に入るのが名詞か形容詞かを考え、語尾をつけます。', steps: ['(1) your の後ろには名詞がくる。kind(親切な)を名詞にするには -ness をつける → kindness。', '(2) be動詞 is と very の後ろで「役に立つ」というようすを表す → 形容詞。', 'use(使う)に形容詞の語尾 -ful をつける → useful。'], a: '(1) kindness (2) useful', check: '(2) を名詞の use のままにすると「この辞書はとても使用です」となり意味が通らないことから、形容詞が正しいと確かめます。' }] },
      { h: '形が変わる単語', t: '【名詞の複数形】ふつうは s。不規則なものに注意します。\nbox → boxes、city → cities、child → children、man → men、woman → women、foot → feet、tooth → teeth、leaf → leaves\n【不規則動詞】原形 ― 過去形 ― 過去分詞 をセットで声に出して覚えます。\ngo ― went ― gone/see ― saw ― seen/take ― took ― taken/buy ― bought ― bought/think ― thought ― thought/teach ― taught ― taught\n【形容詞の比較変化】good ― better ― best/bad ― worse ― worst',
        ex: [{ q: '次の名詞を複数形にしよう。(1) child (2) dictionary (3) foot (4) watch', hint: '不規則に変わる語か、つづりのルールで変わる語かを見分けます。', steps: ['(1) child は不規則に変わる → children。', '(2) dictionary は「子音字 r + y」で終わる → y を i にかえて es → dictionaries。', '(3) foot は不規則に変わる → feet。', '(4) watch は ch で終わる → es をつけて watches。'], a: '(1) children (2) dictionaries (3) feet (4) watches', check: '3単現の s のつけ方(study → studies、watch → watches)と同じルールが使えることを確かめます。' }] },
      { h: 'セットで覚える:反対語・同じ発音の語', t: '【反対の意味の語】はペアで覚えると効率的です。\nlong(長い)⇔ short(短い)/old(古い・年をとった)⇔ new(新しい)・young(若い)/easy(やさしい)⇔ difficult(むずかしい)/buy(買う)⇔ sell(売る)/borrow(借りる)⇔ lend(貸す)/remember(覚えている)⇔ forget(忘れる)\n【発音が同じでつづりがちがう語】は、つづりと意味をしっかり区別します。\nhear(聞く)/here(ここに)、know(知っている)/no(いいえ)、write(書く)/right(右・正しい)、meet(会う)/meat(肉)、son(息子)/sun(太陽)\n【つづりをまちがえやすい語】February(2月)、Wednesday(水曜日)、library(図書館)、beautiful(美しい)。曜日と月の名前は、文の途中でも大文字で書き始めます。',
        ex: [{ q: '( )に、前の語と反対の意味の語を入れよう。(1) This question is not easy. It is (   ). (2) Can you lend me your pen? — Sure. You can (   ) it.', hint: '(2) は、だれから見た動作かを考えます。', steps: ['(1) easy(やさしい)の反対は difficult(むずかしい)。', '(2) lend は「(相手に)貸す」。', 'ペンを受け取る側から言うと「借りる」なので borrow。'], a: '(1) difficult(この問題はやさしくない。むずかしい。) (2) borrow(ペンを貸してくれる?— いいよ。借りていいよ。)', check: '(2) の会話で、ペンを「貸す」のは答えた人、「借りる」のは質問した人(you)だと確かめます。' }] }
    ],
    faq: [
      ['1日に何語くらい覚えればいいの?', '人によりますが、新しい単語は1日10〜20語ほどにして、そのかわり前の日までの単語の見直しに時間を使うのがおすすめです。\n新しい語をふやすより、覚えた語を忘れないようにするほうが、結果的に多くの語が身につきます。'],
      ['つづりが覚えられないときは?', '声に出して読みながら、何回か書いてみましょう。発音とつづりのつながり(-tion は「ション」など)に注目すると覚えやすくなります。\nまちがえたつづりは、ノートにまとめて見直すと効果的です。'],
      ['単語帳と教科書、どちらで覚えるのがいいの?', 'まずは教科書の単語を、本文の文の中で覚えるのが基本です。使われ方がいっしょに分かるからです。\n単語帳は、覚えたかどうかを確かめたり、足りない語を補ったりするのに使いましょう。']
    ],
    terms: [['品詞', '名詞・動詞・形容詞・副詞など、単語の働きによる分類'], ['語尾', '単語の終わりの部分。-tion・-ful・-ly など'], ['複数形', '2つ・2人以上を表す名詞の形'], ['不規則動詞', '過去形・過去分詞が ed にならない動詞'], ['反対語(反意語)', '意味が反対になる語のペア'], ['母音字・子音字', 'a・e・i・o・u が母音字、それ以外が子音字']],
    miss: ['英語 → 意味の確認だけで終わり、意味 → 英語(書ける)の確認をしない。読めても書けない単語は使えないので、両方向でテストしましょう。', '一度覚えたら見直さず、すぐ忘れてしまう。忘れるのはふつうのことなので、間をあけて見直す計画を立てましょう。', 'borrow(借りる)と lend(貸す)を取りちがえる。「だれからだれへ物が動くか」を図にして覚えましょう。', 'hear と here、write と right のように、発音が同じ語のつづりをまちがえる。例文の中で意味とつづりをセットで覚えましょう。'],
    sum: ['「見て意味が言える」→「意味から英語が言える」の2段階で確認する。', '間をあけて何度も見直す。音と例文もいっしょに。', '品詞・語尾で整理すると、1語から仲間が広がる。', '複数形・不規則動詞・比較変化はセットで覚える。', '反対語・同じ発音の語はペアで覚える。曜日・月は大文字で始める。'],
    next: '単語の覚え方が分かったら、文法の単元(たとえば「be動詞と一般動詞」e_m1 や「過去形」e_m2)の例文で、覚えた単語を使ってみましょう。文の中で使うと、さらに忘れにくくなります。'
  };

  // ===== 難関:中学英語の並べかえ =====
  L.ex_jh3 = {
    goal: '並べかえ問題で、主語と動詞を先に決め、名詞の後置修飾・不定詞・間接疑問などの語順の型を使って、正しい英文を組み立てられるようになる。',
    intro: '並べかえ問題は、ばらばらの語をなんとなく並べると時間ばかりかかります。英語の文には決まった【骨組み(主語 → 動詞 → 目的語・補語 → 場所 → 時)】があり、その上に「名詞を後ろから説明する」「to 〜」「疑問詞 + 主語 + 動詞」などの【型】が乗っています。骨組みと型を知っていれば、迷わず並べられます。',
    pre: '英語の文の中心は「主語 + 動詞」でした。動詞は1つの文に原則1つで、主語に合わせて形を変えます(3単現の s・時制)。\n名詞を後ろから説明する方法は3つ学びました。①分詞(the boy playing tennis)②関係代名詞(the book which I bought)③不定詞(something to drink)\n間接疑問文の中は「疑問詞 + 主語 + 動詞」の語順でした(where he lives)。\n現在完了の ever・never・just・already は、have と過去分詞の間に置きました。\nこれらがあやしい人は、先に e_partm・e_m8・e_m4・e_indq・e_m7 の単元を復習しておきましょう。',
    secs: [
      { h: '英文の骨組みを知る', t: '英語の文は、ほとんどが次の骨組みでできています。【主語 → 動詞 → 目的語・補語 → 場所 → 時】\n日本語は動詞が最後にきますが、英語は主語のすぐ後ろに動詞がきます。この差が、並べかえでまちがえるいちばんの原因です。\n例:「私は きのう 図書館で 本を 読んだ」→ I(主語)read(動詞)a book(目的語)in the library(場所)yesterday(時).\nこの骨組みを頭に入れておけば、残った語を「場所」「時」などの決まった位置に置くだけで文が完成します。',
        key: '英文の骨組みは「主語 → 動詞 → 目的語・補語 → 場所 → 時」。まず主語と動詞を決める。' },
      { h: '並べかえの基本手順', t: '①日本文から【主語】と【動詞】を決める(「だれが」「どうする」)。\n②動詞の後ろに【目的語・補語】を置く。\n③残りの語(場所・時など)を最後に置く。英語では「場所 → 時」の順が基本です。\n④日本文の「〜する(名詞)」「〜された(名詞)」の部分は、名詞の後ろから説明する型を使う。\n⑤最後に、使っていない語・2回使った語がないか、文頭が大文字か、動詞の形(3単現・時制)が合っているかを確認する。\n主語が長いときは要注意です。The boy playing tennis is my brother. のように、主語のかたまりが終わったところに動詞がきます。',
        ex: [{ q: '日本文に合うように[ ]の語を並べかえよう。「私の兄は毎朝公園で走ります。」 [ runs / my / in / brother / the park ] every morning.', hint: '主語 → 動詞 → 場所 → 時 の骨組みにあてはめます。', steps: ['主語は「私の兄」→ my brother。', '動詞は「走ります」→ runs(主語が3人称単数なので s がついている)。', '場所「公園で」→ in the park を動詞の後ろに置く。', '時「毎朝」→ every morning は最後(すでに書いてある)。'], a: 'My brother runs in the park every morning.', check: '[ ]内の5つの語句をすべて1回ずつ使っているか、文頭の My が大文字かを確かめます。' }] },
      { h: '型1:名詞を後ろから説明する', t: '【名詞 + 関係代名詞 + 文】the book which I bought(私が買った本)\n【名詞 + 主語 + 動詞(関係代名詞の省略)】the woman I met yesterday(私がきのう会った女性)\n【名詞 + 分詞 + 語句】the boy sitting on the bench(ベンチにすわっている男の子)/a car made in Japan(日本製の車)\n【名詞 + to + 原形】something to drink(何か飲むもの)\n日本語で名詞の前にある長い説明は、英語では名詞の後ろにきます。\n並べかえでは、まず説明される名詞を決め、そのすぐ後ろに説明の語句をまとめて置きます。',
        key: '日本語で名詞の前にある長い説明は、英語では名詞の後ろに置く。',
        ex: [{ q: '日本文に合うように[ ]の語を並べかえよう。「私がきのう会った女性は先生です。」 [ yesterday / the / met / I / woman ] is a teacher.', hint: '文全体の主語と動詞を先に決めます。動詞 is はすでに書いてあります。', steps: ['文全体の主語は「女性」、動詞は is(すでに書いてある)。', '「私がきのう会った」は woman を説明する → 名詞の後ろに「主語 + 動詞」を置く(関係代名詞の省略)。', 'the woman + I met + yesterday の順にし、その後ろに is a teacher を続ける。'], a: 'The woman I met yesterday is a teacher.', check: '説明の部分 I met yesterday を取ると The woman is a teacher. となり、骨組みが正しいことを確かめます。' }] },
      { h: '型2:不定詞を使う', t: '【It is … (for 人) to 〜】〜することは(人にとって)…だ:It is difficult for me to speak English.(英語を話すことは私にとってむずかしい。)\n【want 人 to 〜】人に〜してほしい/【ask 人 to 〜】人に〜するよう頼む/【tell 人 to 〜】人に〜するよう言う\nI want you to help me.(私はあなたに手伝ってほしい。)\n【how to 〜】〜のしかた/【what to 〜】何を〜すべきか:I don\'t know how to use this computer.(私はこのコンピューターの使い方が分かりません。)\n「人」は to の前、「動作」は to の後ろ、と位置を決めてから並べます。',
        ex: [{ q: '「彼にもう一度来るように頼んでください。」 Please [ him / come / ask / to ] again.', hint: '「人に〜するよう頼む」は ask + 人 + to + 原形 の型です。', steps: ['Please の後ろは命令文なので、動詞の原形 → ask。', '「人に〜するよう頼む」は ask + 人 + to + 原形。', '人は him、動作は come → ask + him + to + come の順。'], a: 'Please ask him to come again.', check: 'ask to him come のように、人と to の位置が逆になっていないか確かめます。' }] },
      { h: '型3:間接疑問・現在完了', t: '【間接疑問】疑問詞 + 主語 + 動詞:Do you know when he came to Japan?(彼がいつ日本に来たか知っていますか。)\n間接疑問の中に did・does は入りません。並べかえの語群に did がなければ、動詞は過去形になっているはずです。\n【現在完了】ever・never・just・already は have と過去分詞の間:I have never seen such a big fish.(私はそんなに大きな魚を一度も見たことがありません。)\n【the + 最上級 + 名詞 + (that) I have ever + 過去分詞】今までに〜した中で一番…な(名詞):This is the most beautiful place I have ever visited.(ここは私が今までに訪れた中で一番美しい場所です。)',
        ex: [{ q: '「彼がいつ日本に来たか知っていますか。」 Do [ when / came / he / know / you ] to Japan?', hint: '外側の文 Do you know 〜? を先に作り、その後ろに間接疑問を置きます。', steps: ['外側の文は Do you know 〜?。', '間接疑問は「疑問詞 + 主語 + 動詞」→ when he came。', 'did は使わず、過去形 came を使う。', 'Do you know + when he came + to Japan?'], a: 'Do you know when he came to Japan?', check: 'when he came の部分が「主語 + 動詞」のふつうの語順になっているか確かめます。' },
          { q: '「これは私が今までに読んだ中で一番おもしろい本です。」 This is [ have / book / I / interesting / the / most / ever ] read.', hint: '「一番おもしろい本」を先に作り、その後ろに「私が今までに読んだ」を置きます。', steps: ['interesting は長い語 → 最上級は the most interesting。その後ろに名詞 book。', '「私が今までに読んだ」は book を後ろから説明する(関係代名詞 that の省略)→ I have ever read。', 'ever は have と過去分詞 read の間に置く。', 'This is + the most interesting book + I have ever read.'], a: 'This is the most interesting book I have ever read.', check: '7つの語をすべて使い、ever が have と read の間にあるか確かめます。' }] },
      { h: '型4:比較・SVOC', t: '【one of the + 最上級 + 複数名詞】最も〜な…の1つ:Tokyo is one of the largest cities in the world.(東京は世界で最も大きな都市の1つです。)→ cities と複数形にする点に注意\n【SVOC】make・call・name の後ろに「目的語(O)+ 補語(C)」を置き、「O を C にする・O を C と呼ぶ」を表します。O と C はイコールの関係です。\nThe news made me happy.(その知らせは私を幸せにした。)→ me = happy\nWe call him Ken.(私たちは彼をケンと呼びます。)→ him = Ken\nS は主語、V は動詞、O は目的語、C は補語の頭文字です。',
        ex: [{ q: '「その手紙は彼女を悲しい気持ちにさせました。」 [ her / the letter / sad / made ].', hint: 'make + 目的語 + 補語 で「〜を…にする」です。', steps: ['主語は「その手紙」→ The letter。', '動詞は「させた」→ made(make の過去形)。', '「彼女を悲しい気持ちに」は make + 目的語 + 補語 → her(目的語)+ sad(補語)。her = sad の関係になっている。'], a: 'The letter made her sad.', check: 'her と sad の間に「彼女は悲しい」という関係(her = sad)があることを確かめます。made sad her の順にしていないかも確認します。' }] }
    ],
    faq: [
      ['並べかえで、どこから手をつければいいか分からないときは?', 'まず日本文の「だれが」「どうする」を探して、主語と動詞を決めましょう。それだけで文の前半が決まります。\n次に、残った語のうち「場所」「時」を最後に回し、名詞を説明する語句は名詞のすぐ後ろにまとめます。'],
      ['語群に関係代名詞がないのに「〜した(名詞)」とあるときは?', '目的格の関係代名詞が省略されている形か、過去分詞を使う形を考えます。\n「私がきのう会った女性」のように説明の中に主語があれば「名詞 + 主語 + 動詞」、「日本で作られた車」のように主語がなければ「名詞 + 過去分詞」です。'],
      ['最後の確認では何を見ればいいの?', '①語をすべて1回ずつ使ったか ②文頭が大文字か ③動詞の形(3単現の s・時制)が主語に合っているか ④文の最後の記号(. か ?)の4つを確認します。']
    ],
    terms: [['後置修飾', '名詞を後ろから説明すること(関係代名詞・分詞・不定詞)'], ['骨組み', '主語 → 動詞 → 目的語・補語 → 場所 → 時 という英文の基本の順序'], ['間接疑問', '文の中の疑問文。「疑問詞 + 主語 + 動詞」の語順'], ['SVOC', '「目的語 = 補語」の関係がある文(make me happy など)'], ['want 人 to 〜', '「人に〜してほしい」。人は to の前'], ['one of the + 最上級 + 複数名詞', '「最も〜な…の1つ」']],
    miss: ['主語のかたまりを見落とし、途中に動詞を置いてしまう。主語が長いときは、説明の部分が終わったところに動詞がくると確認しましょう。', '間接疑問を疑問文の語順にする(× when did he come)。外側の文が疑問文でも、中はふつうの文の語順です。', 'want to you help のように、人と to の位置を逆にする。「人」は to の前、「動作」は to の後ろです。', 'ever・never を文の最後に置く。have と過去分詞の間に置きます。', 'one of the の後ろの名詞を単数にする(× one of the largest city)。「〜の中の1つ」なので複数形です。'],
    sum: ['まず主語と動詞を決め、「主語 → 動詞 → 目的語・補語 → 場所 → 時」で並べる。', '日本語で名詞の前にある長い説明は、英語では名詞の後ろ。', '人 + to + 原形、疑問詞 + 主語 + 動詞 などの型を使う。', 'ever・never は have と過去分詞の間。one of the + 最上級 + 複数名詞。', '最後に、語の数・大文字・動詞の形・記号を確認する。'],
    next: '中学英語の文法はここまでで一通りそろいました。高校の「不定詞・動名詞・分詞の基本」(e_inf)などへ進むと、ここで学んだ型がさらに広がります。'
  };
})(WPS.LESSONS);
